/* DAWAH X — ahmad, অধ্যায় 9 · খণ্ড 9 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][9]=[[1601,1601,"","আমরা সেই বধিরদের কথা বলেছি যেটা আমাদের কাছে স্বপ্নের মাধ্যমে ভুল হবে, ঈশ্বর হয়তো আমার বাবার হাতে লুট করেছেন, যে ডাক্তার তার কাছে এসেছে শান্তি আর বলা হয়েছে, কেউ যেন না ভুলে যায়। সে বলবে সে আমাকে আমার দর্শন থেকে কিছু শিক্ষা দেবে অথবা আমার কথা শুনবে, প্রভু, কিভাবে সে এটা করতে বলে। তাহলে তো বলতেই হতো","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَنْبَأَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سُرَاقَةَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ بْنِ الْجَرَّاحِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّهُ ‏ ‏لَمْ يَكُنْ نَبِيٌّ بَعْدَ ‏ ‏نُوحٍ ‏ ‏إِلَّا وَقَدْ أَنْذَرَ ‏ ‏الدَّجَّالَ ‏ ‏قَوْمَهُ وَإِنِّي أُنْذِرُكُمُوهُ قَالَ فَوَصَفَهُ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَلَعَلَّهُ يُدْرِكُهُ بَعْضُ مَنْ رَآنِي أَوْ سَمِعَ كَلَامِي قَالُوا يَا رَسُولَ اللَّهِ كَيْفَ قُلُوبُنَا يَوْمَئِذٍ أَمِثْلُهَا الْيَوْمَ قَالَ أَوْ خَيْرٌ ‏","","",""],[1602,1602,"","সার্জন বলেছিলেন যে, তিনি প্রভুর কাছে প্রার্থনা করেছিলেন এবং আমি খুঁজে পাব । কিন্তু, ঈশ্বর তাকে বলেছিলেন যে, যারা তাঁকে হত্যা করেছে, তাদের বিয়ে হবে ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ سَمُرَةَ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ بْنِ الْجَرَّاحِ ‏ ‏قَالَ ‏ ‏كَانَ آخِرُ مَا تَكَلَّمَ بِهِ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أَخْرِجُوا ‏ ‏يَهُودَ ‏ ‏الْحِجَازِ ‏ ‏مِنْ ‏ ‏جَزِيرَةِ الْعَرَبِ ‏ ‏وَاعْلَمُوا أَنَّ شِرَارَ النَّاسِ الَّذِينَ يَتَّخِذُونَ الْقُبُورَ مَسَاجِدَ ‏","","",""],[1603,1603,"","আমার বাবা বলেছিলেন, একজন মানুষের ঘোড়া থেকে বেঁচে থাকার জন্য ভাড়া করা হয়েছে। তারা ঝড়ে পাস করে, আমরা দৌড় দেই এবং বলি না যে আমরা দৌড় দেই বাবা তার কথা শুনে শুনেই ভগবানের কাছে প্রার্থনা করে, আর সে এটা করতে পারবে না।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ بْنِ أَرْطَاةَ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ أَبِي مَالِكٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏أَجَارَ ‏ ‏رَجُلٌ مِنْ الْمُسْلِمِينَ رَجُلًا وَعَلَى الْجَيْشِ ‏ ‏أَبُو عُبَيْدَةَ بْنُ الْجَرَّاحِ ‏ ‏فَقَالَ ‏ ‏خَالِدُ بْنُ الْوَلِيدِ ‏ ‏وَعَمْرُو بْنُ الْعَاصِ ‏ ‏لَا نُجِيرُهُ ‏ ‏وَقَالَ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏نُجِيرُهُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يُجِيرُ ‏ ‏عَلَى الْمُسْلِمِينَ أَحَدُهُمْ ‏","","",""],[1604,1604,"","আমার বাবা যিনি তার কাছে এসে চিৎকার করে বলেছিলেন, তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন । সে তার কথা স্বীকার করেছে আর সে কখনো এটা নিয়ে ভাবেনি। তোমার বাবা, সুন্দরী চাকর, সার্ভার থেকে তোমাকে ছিনিয়ে নিয়ে, আর তারপর তাকে হত্যা করতে ভয় পায়। আমি আমার স্টেশনে তাকিয়ে দরজা দিয়ে গিয়ে ঈশ্বরের ইচ্ছার সাথে পরিচিত হয়ে তার কাছে প্রার্থনা করছি। আর আমি তোমাকে ভালবাসি আমার কাছে যেতে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبُو حِسْبَةَ مُسْلِمُ بْنُ أُكَيْسٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَامِرٍ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ بْنِ الْجَرَّاحِ ‏ ‏قَالَ ‏ ‏ذَكَرَ ‏ ‏مَنْ دَخَلَ ‏ ‏عَلَيْهِ فَوَجَدَهُ يَبْكِي فَقَالَ مَا يُبْكِيكَ يَا ‏ ‏أَبَا عُبَيْدَةَ ‏ ‏فَقَالَ ‏ ‏نَبْكِي أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَكَرَ يَوْمًا ‏ ‏مَا يَفْتَحُ اللَّهُ عَلَى الْمُسْلِمِينَ وَيُفِيءُ عَلَيْهِمْ حَتَّى ذَكَرَ ‏ ‏الشَّامَ ‏ ‏فَقَالَ إِنْ ‏ ‏يُنْسَأْ ‏ ‏فِي أَجَلِكَ يَا ‏ ‏أَبَا عُبَيْدَةَ ‏ ‏فَحَسْبُكَ ‏ ‏مِنْ الْخَدَمِ ثَلَاثَةٌ خَادِمٌ يَخْدُمُكَ وَخَادِمٌ يُسَافِرُ مَعَكَ وَخَادِمٌ يَخْدُمُ أَهْلَكَ وَيَرُدُّ عَلَيْهِمْ وَحَسْبُكَ مِنْ الدَّوَابِّ ثَلَاثَةٌ دَابَّةٌ لِرَحْلِكَ وَدَابَّةٌ لِثَقَلِكَ وَدَابَّةٌ لِغُلَامِكَ ثُمَّ هَذَا أَنَا أَنْظُرُ إِلَى بَيْتِي قَدْ امْتَلَأَ رَقِيقًا وَأَنْظُرُ إِلَى ‏ ‏مِرْبَطِي ‏ ‏قَدْ امْتَلَأَ دَوَابَّ وَخَيْلًا فَكَيْفَ أَلْقَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ هَذَا وَقَدْ أَوْصَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَحَبَّكُمْ إِلَيَّ وَأَقْرَبَكُمْ مِنِّي مَنْ لَقِيَنِي عَلَى مِثْلِ الْحَالِ الَّذِي فَارَقَنِي عَلَيْهَا ‏","","",""],[1605,1605,"","তার বাবা জানতে পেরেছিলেন যে, তার বাবা চেষ্টা করার পর তার মা মারা গিয়েছে । ( আদিপুস্তক ৬: ৯) কিন্তু, ঈশ্বর তাঁর প্রতিজ্ঞা পূর্ণ করার জন্য তাঁর পুত্রকে অনুরোধ করেছিলেন । তিনি তার দৃষ্টি দেখেছিলেন, তার দিকে তাকিয়ে তিনি তার দিকে তাকিয়েছিলেন এবং তারপর ভয় পেয়েছিলেন সে বলল আমি তোমার সাথে যা চাই তা হল, মানুষ ঝড় পার হয়ে গেছে, আমরা পাপ করেছি, মানুষ বলল, আমরা ওখানেই যাই, আমরা ওর পাহাড়ে। তার কাছে তার কাছে তার কাছে আমাদের কথা আছে। বাবা আর আমার পাপের প্রমাণ সে নিজের ভাগ্যের কাছে গিয়েছে, আমার আত্মা, ঈশ্বরের একটা দল, আর তুমি বলবে, \"আমরা এটা করি নি\" তুমি ভুল রাস্তা পার হয়ে গেছ, আমার দেখা লর্ডের থেকে। আমার মনে হয় ছেলে খুবই সুস্থ, আমার বাবার কাছে ক্ষমা আছে।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏أَبَانُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ الْأَشْعَرِيِّ ‏ ‏عَنْ ‏ ‏رَابِّهِ ‏ ‏رَجُلٍ مِنْ قَوْمِهِ كَانَ خَلَفَ عَلَى أُمِّهِ بَعْدَ أَبِيهِ كَانَ شَهِدَ طَاعُونَ ‏ ‏عَمَوَاسَ ‏ ‏قَالَ ‏ ‏لَمَّا اشْتَعَلَ الْوَجَعُ قَامَ ‏ ‏أَبُو عُبَيْدَةَ بْنُ الْجَرَّاحِ ‏ ‏فِي النَّاسِ خَطِيبًا فَقَالَ أَيُّهَا النَّاسُ ‏ ‏إِنَّ هَذَا الْوَجَعَ رَحْمَةُ رَبِّكُمْ وَدَعْوَةُ نَبِيِّكُمْ وَمَوْتُ الصَّالِحِينَ قَبْلَكُمْ وَإِنَّ ‏ ‏أَبَا عُبَيْدَةَ ‏ ‏يَسْأَلُ اللَّهَ أَنْ يَقْسِمَ لَهُ مِنْهُ حَظَّهُ قَالَ فَطُعِنَ فَمَاتَ رَحِمَهُ اللَّهُ ‏ ‏وَاسْتُخْلِفَ عَلَى النَّاسِ ‏ ‏مُعَاذُ بْنُ جَبَلٍ ‏ ‏فَقَامَ خَطِيبًا بَعْدَهُ فَقَالَ أَيُّهَا النَّاسُ إِنَّ هَذَا الْوَجَعَ رَحْمَةُ رَبِّكُمْ وَدَعْوَةُ نَبِيِّكُمْ وَمَوْتُ الصَّالِحِينَ قَبْلَكُمْ وَإِنَّ ‏ ‏مُعَاذًا ‏ ‏يَسْأَلُ اللَّهَ أَنْ يَقْسِمَ لِآلِ ‏ ‏مُعَاذٍ ‏ ‏مِنْهُ حَظَّهُ قَالَ فَطُعِنَ ابْنُهُ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مُعَاذٍ ‏ ‏فَمَاتَ ثُمَّ قَامَ فَدَعَا رَبَّهُ لِنَفْسِهِ فَطُعِنَ فِي ‏ ‏رَاحَتِهِ ‏ ‏فَلَقَدْ رَأَيْتُهُ يَنْظُرُ إِلَيْهَا ثُمَّ يُقَبِّلُ ظَهْرَ كَفِّهِ ثُمَّ يَقُولُ مَا أُحِبُّ أَنَّ لِي بِمَا فِيكِ شَيْئًا مِنْ الدُّنْيَا ‏ ‏فَلَمَّا مَاتَ اسْتُخْلِفَ عَلَى النَّاسِ ‏ ‏عَمْرُو بْنُ الْعَاصِ ‏ ‏فَقَامَ فِينَا خَطِيبًا فَقَالَ أَيُّهَا النَّاسُ إِنَّ هَذَا الْوَجَعَ إِذَا وَقَعَ فَإِنَّمَا يَشْتَعِلُ اشْتِعَالَ النَّارِ فَتَجَبَّلُوا مِنْهُ فِي الْجِبَالِ ‏ ‏قَالَ فَقَالَ لَهُ ‏ ‏أَبُو وَاثِلَةَ الْهُذَلِيُّ ‏ ‏كَذَبْتَ وَاللَّهِ لَقَدْ صَحِبْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنْتَ شَرٌّ مِنْ حِمَارِي هَذَا قَالَ وَاللَّهِ مَا أَرُدُّ عَلَيْكَ مَا تَقُولُ وَايْمُ اللَّهِ لَا نُقِيمُ عَلَيْهِ ثُمَّ خَرَجَ وَخَرَجَ النَّاسُ فَتَفَرَّقُوا عَنْهُ وَدَفَعَهُ اللَّهُ عَنْهُمْ قَالَ فَبَلَغَ ذَلِكَ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏مِنْ رَأْيِ ‏ ‏عَمْرٍو ‏ ‏فَوَاللَّهِ مَا كَرِهَهُ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد بْن حَنْبَلٍ ‏ ‏أَبَانُ بْنُ صَالِحٍ ‏ ‏جَدُّ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ مُشْكُدَانَةَ ‏","","",""],[1606,1606,"","আমরা বাবার সাথে কথা বলেছি, এক বছরের শত্রু, সে ঈশ্বরের শান্তি নিয়ে কাজ করেছে। বাবার কাছে অনুরোধ করাটা হবে ভালো কাজ করার কৌশল। তারা আমার মতো অনেক পরিবর্তন করতে যাচ্ছে। আমি জানি, আমি কি করেছি? আমার বাবা তা করতে পারতেন, ঈশ্বরের দোহাই তাকে হত্যা করতে আমি আপনার জন্য ঘোমটা পার হব, আমি ঈশ্বরের দোহাই দিয়ে বলছি, আল্লাহ্‌র কসম! তাকে তার যাদুঘর তৈরি করে দিয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏قَالَ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَيْشَ ذَاتِ السُّلَاسِلِ فَاسْتَعْمَلَ ‏ ‏أَبَا عُبَيْدَةَ ‏ ‏عَلَى ‏ ‏الْمُهَاجِرِينَ ‏ ‏وَاسْتَعْمَلَ ‏ ‏عَمْرَو بْنَ الْعَاصِ ‏ ‏عَلَى ‏ ‏الْأَعْرَابِ ‏ ‏فَقَالَ لَهُمَا تَطَاوَعَا قَالَ وَكَانُوا يُؤْمَرُونَ أَنْ يُغِيرُوا عَلَى ‏ ‏بَكْرٍ ‏ ‏فَانْطَلَقَ ‏ ‏عَمْرٌو ‏ ‏فَأَغَارَ ‏ ‏عَلَى ‏ ‏قُضَاعَةَ ‏ ‏لِأَنَّ ‏ ‏بَكْرًا ‏ ‏أَخْوَالُهُ فَانْطَلَقَ ‏ ‏الْمُغِيرَةُ بْنُ شُعْبَةَ ‏ ‏إِلَى ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَعْمَلَكَ عَلَيْنَا وَإِنَّ ابْنَ فُلَانٍ قَدْ ‏ ‏ارْتَبَعَ ‏ ‏أَمْرَ الْقَوْمِ وَلَيْسَ لَكَ مَعَهُ أَمْرٌ فَقَالَ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَنَا أَنْ نَتَطَاوَعَ فَأَنَا أُطِيعُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنْ عَصَاهُ ‏ ‏عَمْرٌو ‏","","",""],[1607,1607,"","আমরা তাদের অনেক বার চেষ্টা করেছি একটি দেবতাহীন প্রাণীর সেবায়. শেষ পর্যন্ত সে হতেও খুব পছন্দ করবে। আর আমরা কি বিয়ে দ্বীপ থেকে পালাই?","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ بْنُ مَيْمُونٍ ‏ ‏مَوْلَى آلِ ‏ ‏سَمُرَةَ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ سَعْدِ بْنِ سَمُرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ بْنِ الْجَرَّاحِ ‏ ‏قَالَ ‏ ‏إِنَّ آخِرَ مَا تَكَلَّمَ بِهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَخْرِجُوا ‏ ‏يَهُودَ ‏ ‏أَهْلِ ‏ ‏الْحِجَازِ ‏ ‏وَأَهْلِ ‏ ‏نَجْرَانَ ‏ ‏مِنْ ‏ ‏جَزِيرَةِ الْعَرَبِ ‏","","",""],[1608,1608,"","আমরা পৃথিবীর সেরা জীবনের জন্য ভাল একটি জীবনের কথা বলেছি। আমরা বাবাকে তার কাছে ফিরে যেতে দিলাম। আমি শুনেছি ঈশ্বরের পথে, ঈশ্বরের পথে, এটা একটা মূল্য। আমি আমার বাবা-মা-কে বলতে চাই, ঈশ্বরের কাছে প্রার্থনা করা উচিত। আমি আমার বাবার কাছে প্রার্থনা করি, আমি আমার সৃষ্টিকর্তাকে সবচেয়ে ভালো কিছু করতে পারি। আমি যদি আমার বাবা না বলি, আমি আমার বাবা আমাকে বলেছি, আমি আমার বাবা আমার বাবা আমাকে বলেন, আমি আমার কাছে এটা করতে হবে। আমি কি এটা একটা ভাল জীবন হবে? আমি কি করতে পারি? আমি কি তাকে বলব? আমি কি করতে পারি? আমি কি এটা করতে পারি? আমি জানি না যে, আমি আমার বাবা, আমি কি করতে পারি? আমি কি করতে পারি? আমি কি করতে পারি না? আমি এটা আমার বাবা, আমি কি করতে পারি? আমি কি করতে পারি? আমি জানি না? আমি জানি না, আমি জানি না যে, আমি এটা আমার বাবা, আমি কি করেছে? আমি কি করেছে? আমি কি করে, আমি জানি না? আমরা আমার সম্বন্ধে একটা বিষয় নিয়ে কথা বলেছিলাম । তোমার প্রতি করুণা দেখানোর জন্য বাবা যুদ্ধ করতে যাচ্ছে.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَنْبَأَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏وَاصِلٍ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عِيَاضِ بْنِ غُطَيْفٍ ‏ ‏قَالَ ‏ ‏دَخَلْنَا عَلَى ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏نَعُودُهُ ‏ ‏قَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَنْفَقَ نَفَقَةً ‏ ‏فَاضِلَةً ‏ ‏فِي سَبِيلِ اللَّهِ فَبِسَبْعِ مِائَةٍ وَمَنْ أَنْفَقَ عَلَى نَفْسِهِ أَوْ عَلَى أَهْلِهِ أَوْ عَادَ مَرِيضًا أَوْ مَازَ أَذًى عَنْ طَرِيقٍ فَهِيَ حَسَنَةٌ بِعَشْرِ أَمْثَالِهَا وَالصَّوْمُ جُنَّةٌ مَا لَمْ ‏ ‏يَخْرِقْهَا ‏ ‏وَمَنْ ابْتَلَاهُ اللَّهُ بَلَاءً فِي جَسَدِهِ فَهُوَ لَهُ ‏ ‏حِطَّةٌ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏حَدَّثَنَا ‏ ‏بَشَّارُ بْنُ أَبِي سَيْفٍ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عِيَاضِ بْنِ غُطَيْفٍ ‏ ‏قَالَ دَخَلْنَا عَلَى ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[1609,1609,"","আমার বাবা আমার চেয়ে ভাল ছিলেন বলে আমি আমার বাবার সঙ্গে কথা বলেছিলাম । আমার বাবা - মা আমাকে বলেছিলেন যে, তারা যেন আমাকে বাইবেল থেকে সত্য জানায় । আমরা খাওয়ার আগে তারা তাকে খেতে এবং ঈশ্বর তাকে তা করতে বলেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ يَعْنِي التَّيْمِيَّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بِضَيْفٍ لَهُ ‏ ‏أَوْ بِأَضْيَافٍ لَهُ ‏ ‏قَالَ فَأَمْسَى عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَلَمَّا أَمْسَى قَالَتْ لَهُ أُمِّي ‏ ‏احْتَبَسْتَ ‏ ‏عَنْ ضَيْفِكَ ‏ ‏أَوْ أَضْيَافِكَ ‏ ‏مُنْذُ اللَّيْلَةِ قَالَ أَمَا عَشَّيْتِهِمْ قَالَتْ لَا قَالَتْ قَدْ عَرَضْتُ ذَاكَ عَلَيْهِ ‏ ‏أَوْ عَلَيْهِمْ ‏ ‏فَأَبَوْا ‏ ‏أَوْ فَأَبَى ‏ ‏قَالَ فَغَضِبَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَحَلَفَ أَنْ لَا يَطْعَمَهُ وَحَلَفَ الضَّيْفُ ‏ ‏أَوْ الْأَضْيَافُ ‏ ‏أَنْ لَا يَطْعَمُوهُ حَتَّى يَطْعَمَهُ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏إِنْ كَانَتْ هَذِهِ مِنْ الشَّيْطَانِ قَالَ فَدَعَا بِالطَّعَامِ فَأَكَلَ وَأَكَلُوا قَالَ فَجَعَلُوا لَا يَرْفَعُونَ لُقْمَةً إِلَّا ‏ ‏رَبَتْ ‏ ‏مِنْ أَسْفَلِهَا أَكْثَرَ مِنْهَا فَقَالَ يَا أُخْتَ ‏ ‏بَنِي فِرَاسٍ ‏ ‏مَا هَذَا قَالَ فَقَالَتْ ‏ ‏قُرَّةُ ‏ ‏عَيْنِي إِنَّهَا الْآنَ لَأَكْثَرُ مِنْهَا قَبْلَ أَنْ نَأْكُلَ قَالَ فَأَكَلُوا وَبَعَثَ بِهَا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ أَنَّهُ أَكَلَ مِنْهَا ‏","","",""],[1610,1610,"","আমরা বাবার ভালবাসার একটা সাধারণ জ্ঞান নিয়ে কথা বলেছি। আমরা তার কাছে প্রার্থনা করেছিলাম এবং তার কাছে প্রার্থনা করেছিলাম এবং তার জন্য তিন বছর এবং তার মৃত্যু হল, ঈশ্বর তার স্বপ্নকে রক্ষা করেছেন। এক বছর বয়সী একজন লোকের সাথে গিয়েছিল, না আমরা তাকে যেতে চাই... ...আর তারপর একজন হট ডগ নিয়ে আসি। ( গীতসংহিতা ৩৭: ১১) আপনি বলেছিলেন যে, আমরা সবাই একত্রিত হয়েছি এবং আমরা করেছি । দুর্গের চেয়ে ভালো আর আমার মতো করে তৈরি করো।","‏ ‏حَدَّثَنَا ‏ ‏عَارِمٌ ‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ ‏ ‏أَنَّهُ ‏ ‏قَالَ كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثِينَ وَمِائَةً فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ مَعَ أَحَدٍ مِنْكُمْ طَعَامٌ فَإِذَا مَعَ رَجُلٍ ‏ ‏صَاعٌ ‏ ‏مِنْ طَعَامٍ ‏ ‏أَوْ نَحْوُهُ ‏ ‏فَعُجِنَ ثُمَّ جَاءَ رَجُلٌ مُشْرِكٌ ‏ ‏مُشْعَانٌّ ‏ ‏طَوِيلٌ بِغَنَمٍ يَسُوقُهَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَيْعًا أَمْ عَطِيَّةً ‏ ‏أَوْ قَالَ أَمْ هَدِيَّةً ‏ ‏قَالَ لَا بَلْ بَيْعٌ فَاشْتَرَى مِنْهُ شَاةً فَصُنِعَتْ ‏ ‏وَأَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِسَوَادِ ‏ ‏الْبَطْنِ أَنْ يُشْوَى قَالَ وَايْمُ اللَّهِ مَا مِنْ الثَّلَاثِينَ وَالْمِائَةِ إِلَّا قَدْ ‏ ‏حَزَّ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حُزَّةً ‏ ‏مِنْ ‏ ‏سَوَادِ ‏ ‏بَطْنِهَا إِنْ كَانَ شَاهِدًا أَعْطَاهَا إِيَّاهُ وَإِنْ كَانَ غَائِبًا خَبَأَ لَهُ قَالَ وَجَعَلَ مِنْهَا ‏ ‏قَصْعَتَيْنِ ‏ ‏قَالَ فَأَكَلْنَا أَجْمَعُونَ وَشَبِعْنَا وَفَضَلَ فِي ‏ ‏الْقَصْعَتَيْنِ ‏ ‏فَجَعَلْنَاهُ عَلَى الْبَعِيرِ ‏ ‏أَوْ كَمَا قَالَ ‏","","",""],[1611,1611,"","আমরা একটি ছেলের সাথে কথা বলেছি যে তার সময় বাঁচিয়েছে, আর আমি আমার বাবাকে ভালবাসি, তারপর সে আমার বাবার প্রতি করুণা প্রদর্শন করার কথা বলল, যেমনটা আমি আমার জীবনে জিততে যাচ্ছিলাম। সে করেছিল। আত্মসমর্পণের সময় একবার বলেছিলেন, কার দুটো খাবার খেতে হবে, আমি ছয় বছর বয়সী আর কিভাবে সে বলেছে বাবা তার কিছু কাজ করতে হবে, দশ বার আর বাবা ছিল, সে কিছু সময় বলেছিল সে নাকি শিক্ষক।","‏ ‏حَدَّثَنَا ‏ ‏عَارِمٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عُثْمَانَ ‏ ‏أَنَّهُ حَدَّثَهُ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرٍ ‏ ‏أَنَّ ‏ ‏أَصْحَابَ الصُّفَّةِ ‏ ‏كَانُوا أُنَاسًا فُقَرَاءَ وَأَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَرَّةً ‏ ‏مَنْ كَانَ عِنْدَهُ طَعَامُ اثْنَيْنِ فَلْيَذْهَبْ بِثَالِثٍ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏بِثَلَاثَةٍ ‏ ‏وَمَنْ كَانَ عِنْدَهُ طَعَامُ أَرْبَعَةٍ فَلْيَذْهَبْ بِخَامِسٍ سَادِسٍ ‏ ‏أَوْ كَمَا قَالَ ‏ ‏وَأَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏جَاءَ بِثَلَاثَةٍ وَانْطَلَقَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعَشَرَةٍ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏بِثَلَاثَةٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏بِسَادِسٍ ‏","","",""],[1612,1612,"","আমরা দুই বছর ধরে কাজ করেছি যার মানে হলো আমার ঈশ্বর বা ঈশ্বর তাকে আমি বলে। আমার বাবা আমাকে বলেছে, ঈশ্বর তাকে উদ্ধার করতে হবে এবং তাকে তার মুক্তি দিতে হবে। দুনিয়ার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَمْرٍو يَعْنِي ابْنَ دِينَارٍ ‏ ‏أَخْبَرَهُ ‏ ‏عَمْرُو بْنُ أَوْسٍ الثَّقَفِيُّ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرٍ ‏ ‏قَالَ ‏ ‏أَمَرَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏أُرْدِفَ ‏ ‏عَائِشَةَ ‏ ‏إِلَى ‏ ‏التَّنْعِيمِ ‏ ‏فَأُعْمِرَهَا ‏","","",""],[1613,1613,"","আমরা ইশ্বরের সাথে কথা বলেছি যে আমরা একজন যাজকের চেয়ে ভাল কথা বলেছি, আমার বাবা আমাকে রক্ষা করার জন্য এত কিছু করেছেন যে তিনি আমার জন্য ঈশ্বরের কাছে পাঠানো হয়েছে। ঈশ্বর তাঁর চোখে যা খুঁজে পেয়েছেন, তা শুনে আমার মা নিশ্চয়ই তোমাকে অপমান করবে। ( আদি.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ السَّهْمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مِهْرَانَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏مَيْمُونِ بْنِ مِهْرَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ رَبِّي أَعْطَانِي سَبْعِينَ أَلْفًا مِنْ أُمَّتِي يَدْخُلُونَ الْجَنَّةَ بِغَيْرِ حِسَابٍ فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ فَهَلَّا اسْتَزَدْتَهُ قَالَ قَدْ اسْتَزَدْتُهُ فَأَعْطَانِي مَعَ كُلِّ رَجُلٍ سَبْعِينَ أَلْفًا قَالَ ‏ ‏عُمَرُ ‏ ‏فَهَلَّا اسْتَزَدْتَهُ قَالَ قَدْ اسْتَزَدْتُهُ فَأَعْطَانِي هَكَذَا ‏ ‏وَفَرَّجَ ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ ‏ ‏بَيْنَ يَدَيْهِ وَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَبَسَطَ ‏ ‏بَاعَيْهِ ‏ ‏وَحَثَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏و قَالَ ‏ ‏هِشَامٌ ‏ ‏وَهَذَا مِنْ اللَّهِ لَا يُدْرَى مَا عَدَدُهُ ‏","","",""],[1614,1614,"","আমরা আমার বাবার ঘোড়ার সাথে থাকার জন্য একটা মশার বন্ধুত্বের চেয়ে ভাল কিছু করেছি, দুটো ঘোড়াই দৃষ্টির জন্য বিখ্যাত আর প্রভুর অনুগ্রহের প্রতি শ্রদ্ধার জন্য বিখ্যাত আমার বাবার সবচেয়ে বড় কথা, খোদা তার আদর্শে যাওয়ার জন্য খারাপ, হয়তো তুমি জানতে আমি তাকে হারাতে না, যখন আগুন বা আগুনের মধ্যে দিয়ে চলে যাই। অথবা কোনো কোনো কারণে আগুন জ্বালিয়ে দেওয়া ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏صَدَقَةُ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ الْجَوْنِيِّ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏قَاضِي الْمِصْرَيْنِ وَهُوَ ‏ ‏شُرَيْحٌ ‏ ‏وَالْمِصْرَانِ ‏ ‏الْبَصْرَةُ ‏ ‏وَالْكُوفَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏لَيَدْعُو بِصَاحِبِ الدَّيْنِ يَوْمَ الْقِيَامَةِ فَيُقِيمُهُ بَيْنَ يَدَيْهِ فَيَقُولُ أَيْ عَبْدِي فِيمَ أَذْهَبْتَ مَالَ النَّاسِ فَيَقُولُ أَيْ رَبِّ قَدْ عَلِمْتَ أَنِّي لَمْ أُفْسِدْهُ إِنَّمَا ذَهَبَ فِي ‏ ‏غَرَقٍ ‏ ‏أَوْ حَرَقٍ أَوْ سَرِقَةٍ أَوْ ‏ ‏وَضِيعَةٍ ‏ ‏فَيَدْعُو اللَّهُ عَزَّ وَجَلَّ بِشَيْءٍ فَيَضَعُهُ فِي مِيزَانِهِ فَتَرْجَحُ حَسَنَاتُهُ ‏","","",""],[1615,1615,"","আমরা সেই বধিরদের কথা বলেছি, আমার যাজকত্বের কাঠবিড়ালী নিয়ে। ঈশ্বর আমার বাবাকে এত আশীর্বাদ করবেন যেন তিনি তার কাছে ঈশ্বরের অনুগ্রহের কথা বলতে পারেন এবং তার হাত তুলে নিতে পারেন। কিন্তু তাকে অবশ্যই যেতে হবে। বল, ছেলে, আমি রক্ত নিয়ে এসেছি আর সে মানুষের অধিকার হারিয়েছে বলে যে তুমি মারা গিয়েছ, আমি মদ খাইনি, কিন্তু আমার হাতে অধিকার আছে। আমি চাইলে এটা আমার হাতের হাতে রেখে দিয়েছিলাম, তার বদলে তুমি তাকে রক্ষা করেছ.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏صَدَقَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عِمْرَانَ ‏ ‏حَدَّثَنِي ‏ ‏قَيْسُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏قَاضِي الْمِصْرَيْنِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَدْعُو اللَّهُ بِصَاحِبِ الدَّيْنِ يَوْمَ الْقِيَامَةِ حَتَّى يُوقَفَ بَيْنَ يَدَيْهِ فَيُقَالُ يَا ابْنَ ‏ ‏آدَمَ ‏ ‏فِيمَ أَخَذْتَ هَذَا الدَّيْنَ وَفِيمَ ضَيَّعْتَ حُقُوقَ النَّاسِ فَيَقُولُ يَا رَبِّ إِنَّكَ تَعْلَمُ أَنِّي أَخَذْتُهُ فَلَمْ آكُلْ وَلَمْ أَشْرَبْ وَلَمْ أَلْبَسْ وَلَمْ أُضَيِّعْ وَلَكِنْ أَتَى عَلَى يَدَيَّ إِمَّا حَرَقٌ وَإِمَّا سَرَقٌ وَإِمَّا ‏ ‏وَضِيعَةٌ ‏ ‏فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ صَدَقَ عَبْدِي أَنَا أَحَقُّ مَنْ قَضَى عَنْكَ الْيَوْمَ فَيَدْعُو اللَّهُ بِشَيْءٍ فَيَضَعُهُ فِي كِفَّةِ مِيزَانِهِ فَتَرْجَحُ حَسَنَاتُهُ عَلَى سَيِّئَاتِهِ فَيَدْخُلُ الْجَنَّةَ بِفَضْلِ رَحْمَتِهِ ‏","","",""],[1616,1616,"","আমরা জানতে পারলাম যে, আমি আপনার ছেলেকে এই ব্যাপারে চিন্তা করতে ব্যবহার করতে পারি। তাহলে আমি চাই তোমার বোন ড্রাগনের মুখ থেকে চলে যাও.","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَنْبَأَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏أَنْبَأَنَا ‏ ‏زَكَرِيَّا بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ أَنَّهُ أَخْبَرَهُ ‏ ‏مَنْ سَمِعَ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ أَبِي بَكْرٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ارْحَلْ هَذِهِ النَّاقَةَ ثُمَّ ‏ ‏أَرْدِفْ ‏ ‏أُخْتَكَ فَإِذَا هَبَطْتُمَا مِنْ ‏ ‏أَكَمَةِ ‏ ‏التَّنْعِيمِ ‏ ‏فَأَهِلَّا ‏ ‏وَأَقْبِلَا وَذَلِكَ لَيْلَةُ ‏ ‏الصَّدَرِ ‏","","",""],[1617,1617,"","আমরা দুজন ছুরি নিয়ে কথা বলেছি... ...তোমার ব্যাপারে উড়ন্ত ছেলে, লর্ড লর্ডের মেয়ে, তার বাবার মহান বন্ধু আমি চাই যে, তোমার ভাই তার মুখ দিয়ে যদি সে শিক্ষা দিয়ে থাকে, তা হলে আমি তার সঙ্গে বাস করি । ভয়ানক।","‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ مِهْرَانَ الدَّبَّاغُ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ يَعْنِي الْعَطَّارَ ‏ ‏عَنِ ‏ ‏ابْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مَاهَكَ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ابْنَةِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ الصِّدِّيقِ ‏ ‏عَنْ ‏ ‏أَبِيهَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِعَبْدِ الرَّحْمَنِ ‏ ‏أَرْدِفْ أُخْتَكَ ‏ ‏يَعْنِي ‏ ‏عَائِشَةَ ‏ ‏فَأَعْمِرْهَا مِنْ ‏ ‏التَّنْعِيمِ ‏ ‏فَإِذَا هَبَطْتَ بِهَا مِنْ ‏ ‏الْأَكَمَةِ ‏ ‏فَمُرْهَا فَلْتُحْرِمْ فَإِنَّهَا عُمْرَةٌ مُتَقَبَّلَةٌ ‏","","",""],[1618,1618,"","বাবার সম্পর্কে আমরা একটা সাধারণ জ্ঞানও জানি। আমরা ভাববাদীর কাছে প্রার্থনা করেছিলাম তিনি দু সেকেন্ড সময় দিয়েছেন আর তিনি বলেছিলেন যে ভবিষ্যদ্বাণী সেরা কাজ ছিল তাই, পৃথিবীর একজন মানুষ সঙ্গে আমরা চলে যাবো, অথবা তারপর একজন মানুষ একটা সাধারণ কৌতুকের মধ্যে চলে আসবে। ঈশ্বরের কাছে আছে আর এটা বিক্রি করে দেবে অথবা বলেছে যে এটা কখনোই করা হয়নি। ঈশ্বর আমাদেরকে পাপ করেছেন আর তাকে অবশ্যই রক্ষা করতে হবে । আমরা আমাদের প্রাসাদে গিয়ে অনেক বেশি মদ খেয়েছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏عَارِمٌ ‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ ‏ ‏أَنَّهُ قَالَ كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثِينَ وَمِائَةً فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ مَعَ أَحَدٍ مِنْكُمْ طَعَامٌ فَإِذَا مَعَ رَجُلٍ ‏ ‏صَاعٌ ‏ ‏مِنْ طَعَامٍ ‏ ‏أَوْ نَحْوُهُ ‏ ‏فَعُجِنَ ثُمَّ جَاءَ رَجُلٌ مُشْرِكٌ ‏ ‏مُشْعَانٌّ ‏ ‏طَوِيلٌ بِغَنَمٍ يَسُوقُهَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَيْعًا أَمْ عَطِيَّةً ‏ ‏أَوْ قَالَ أَمْ هِبَةً ‏ ‏قَالَ لَا بَلْ بَيْعٌ فَاشْتَرَى مِنْهُ شَاةً فَصُنِعَتْ ‏ ‏وَأَمَرَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِسَوَادِ ‏ ‏الْبَطْنِ أَنْ يُشْوَى قَالَ وَايْمُ اللَّهِ مَا مِنْ الثَّلَاثِينَ وَالْمِائَةِ إِلَّا قَدْ ‏ ‏حَزَّ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَهُ ‏ ‏حُزَّةً ‏ ‏مِنْ ‏ ‏سَوَادِ ‏ ‏بَطْنِهَا إِنْ كَانَ شَاهِدًا أَعْطَاهُ إِيَّاهُ وَإِنْ كَانَ غَائِبًا خَبَأَ لَهُ قَالَ وَجَعَلَ مِنْهَا ‏ ‏قَصْعَتَيْنِ ‏ ‏قَالَ فَأَكَلْنَا أَجْمَعُونَ وَشَبِعْنَا وَفَضَلَ فِي ‏ ‏الْقَصْعَتَيْنِ ‏ ‏فَحَمَلْنَاهُ عَلَى بَعِيرٍ ‏ ‏أَوْ كَمَا قَالَ ‏","","",""],[1619,1619,"","আমরা একটি ছেলে সম্পর্কে আমাদের আলোচনা শিখেছি, যে কিনা ঈশ্বরের কাছে কথা বলেছে, কিন্তু গ্রীষ্মের কথা সেই মানুষ যারা সিদ্ধান্ত নিয়েছে যে ঈশ্বর এটা করেছেন। দুইজন মানুষ এটা করেছে। আমি অনেক খাবার ও কতগুলো খাবার পেয়েছি, তার চেয়ে বেশি কিছু নয় । ( গীতসংহিতা ১১৯: ১৬৫) ঈশ্বর তাকে আদেশ দিয়েছেন, যেন তিনি তোমাকে ছেড়ে না দেন অথবা আপনার জীবন বলে থাকেন । তারা বলেছিল যে, আমি তাকে বলতে গিয়েছিলাম যে, সে ধনী কি না । তার বাবার বড় হওয়ার আগে সে তোমাকে দেখে বড় হতে দেখেছে। আমার মন এখন বড় হয়েছে, তোমার কাজের আগে থেকেই। তারপর সে একটা সামিটে বসে... ...আর সে এটা করেছে আর সে আত্মসমর্পণ করেছে. আমি এই সময়টা নিয়ে দু'জনেই একসাথে কাজ করেছি. আমি একত্র হই অথবা সে কিভাবে বললো","‏ ‏حَدَّثَنَا ‏ ‏عَارِمٌ ‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عُثْمَانَ ‏ ‏أَنَّهُ حَدَّثَهُ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرٍ ‏ ‏أَنَّ ‏ ‏أَصْحَابَ الصُّفَّةِ ‏ ‏كَانُوا أُنَاسًا فُقَرَاءَ وَأَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَرَّةً ‏ ‏مَنْ كَانَ عِنْدَهُ طَعَامُ اثْنَيْنِ فَلْيَذْهَبْ بِثَالِثٍ مَنْ كَانَ عِنْدَهُ طَعَامُ أَرْبَعَةٍ فَلْيَذْهَبْ بِخَامِسٍ بِسَادِسٍ ‏ ‏أَوْ كَمَا قَالَ ‏ ‏وَأَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏جَاءَ بِثَلَاثَةٍ فَانْطَلَقَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعَشَرَةٍ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏بِثَلَاثَةٍ قَالَ فَهُوَ أَنَا وَأَبِي وَأُمِّي ‏ ‏وَلَا أَدْرِي هَلْ قَالَ وَامْرَأَتِي ‏ ‏وَخَادِمٌ بَيْنَ بَيْتِنَا وَبَيْتِ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَإِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏تَعَشَّى عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ لَبِثَ حَتَّى صَلَّيْتُ الْعِشَاءَ ثُمَّ رَجَعَ فَلَبِثَ حَتَّى نَعَسَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ بَعْدَمَا مَضَى مِنْ اللَّيْلِ مَا شَاءَ اللَّهُ قَالَتْ لَهُ امْرَأَتُهُ مَا حَبَسَكَ عَنْ أَضْيَافِكَ ‏ ‏أَوْ قَالَتْ ضَيْفِكَ ‏ ‏قَالَ أَوَمَا عَشَّيْتِهِمْ قَالَتْ أَبَوْا حَتَّى تَجِيءَ قَدْ عَرَضُوا عَلَيْهِمْ فَغَلَبُوهُمْ قَالَ فَذَهَبْتُ أَنَا فَاخْتَبَأْتُ قَالَ يَا ‏ ‏غُنْثَرُ ‏ ‏أَوْ يَا ‏ ‏عَنْتَرُ ‏ ‏فَجَدَّعَ ‏ ‏وَسَبَّ وَقَالَ كُلُوا لَا ‏ ‏هَنِيًّا وَقَالَ وَاللَّهِ لَا أَطْعَمُهُ أَبَدًا قَالَ وَحَلَفَ الضَّيْفُ أَنْ لَا يَطْعَمَهُ حَتَّى يَطْعَمَهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏قَالَ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏هَذِهِ مِنْ الشَّيْطَانِ قَالَ فَدَعَا بِالطَّعَامِ فَأَكَلَ قَالَ فَايْمُ اللَّهِ مَا كُنَّا نَأْخُذُ مِنْ لُقْمَةٍ إِلَّا ‏ ‏رَبَا ‏ ‏مِنْ أَسْفَلِهَا أَكْثَرَ مِنْهَا قَالَ حَتَّى شَبِعُوا وَصَارَتْ أَكْثَرَ مِمَّا كَانَتْ قَبْلَ ذَلِكَ فَنَظَرَ إِلَيْهَا ‏ ‏أَبُو بَكْرٍ ‏ ‏فَإِذَا هِيَ كَمَا هِيَ أَوْ أَكْثَرُ فَقَالَ لِامْرَأَتِهِ يَا أُخْتَ ‏ ‏بَنِي فِرَاسٍ ‏ ‏مَا هَذَا قَالَتْ لَا وَقُرَّةِ عَيْنِي لَهِيَ الْآنَ أَكْثَرُ مِنْهَا قَبْلَ ذَلِكَ بِثَلَاثِ مِرَارٍ فَأَكَلَ مِنْهَا ‏ ‏أَبُو بَكْرٍ ‏ ‏وَقَالَ إِنَّمَا كَانَ ذَلِكَ مِنْ الشَّيْطَانِ ‏ ‏يَعْنِي يَمِينَهُ ‏ ‏ثُمَّ أَكَلَ لُقْمَةً ثُمَّ حَمَلَهَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَصْبَحَتْ عِنْدَهُ قَالَ وَكَانَ بَيْنَنَا وَبَيْنَ قَوْمٍ عَقْدٌ فَمَضَى ‏ ‏الْأَجَلُ ‏ ‏فَعَرَّفْنَا اثْنَيْ عَشَرَ رَجُلًا مَعَ كُلِّ رَجُلٍ أُنَاسٌ اللَّهُ أَعْلَمُ كَمْ مَعَ كُلِّ رَجُلٍ غَيْرَ أَنَّهُ بَعَثَ مَعَهُمْ فَأَكَلُوا مِنْهَا أَجْمَعُونَ ‏ ‏أَوْ كَمَا قَالَ ‏","","",""],[1620,1620,"","আমার বাবা মারা যাওয়ার বিষয়ে কথা বলেছিলেন । তিনি কয়েক বার আমার ছেলেকে ও আমার ছেলেকে প্রার্থনা করেছিলেন এবং তিনি তার দশটি শব্দ দিয়েছিলেন । ঈশ্বরের কাছে এটা হল.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يَقُولُ حَدَّثَنَا ‏ ‏أَبُو عُثْمَانَ ‏ ‏أَنَّهُ حَدَّثَهُ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرٍ ‏ ‏أَنَّ ‏ ‏أَصْحَابَ الصُّفَّةِ ‏ ‏كَانُوا أُنَاسًا فُقَرَاءَ وَأَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَانَ عِنْدَهُ طَعَامُ اثْنَيْنِ فَلْيَذْهَبْ بِثَلَاثَةٍ وَمَنْ كَانَ عِنْدَهُ طَعَامُ أَرْبَعَةٍ فَلْيَذْهَبْ بِخَامِسٍ بِسَادِسٍ ‏ ‏أَوْ كَمَا قَالَ ‏ ‏وَأَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏جَاءَ بِثَلَاثَةٍ وَانْطَلَقَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعَشَرَةٍ قَالَ فَهُوَ وَأَنَا وَأَبِي وَأُمِّي ‏ ‏وَلَا أَدْرِي هَلْ قَالَ امْرَأَتِي وَخَادِمٌ بَيْنَ بَيْتِنَا وَبَيْتِ ‏ ‏أَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏","","",""],[1621,1621,"","আমরা যে - সর্বোত্তম বিচার করেছিলাম, সেই সম্বন্ধে কথা বলেছিলাম । আমি তার প্রার্থনা করি, তার পতাকার জন্য প্রভু তার পতাকার জন্য প্রার্থনা করেন এবং আমি লর্ডের কাছে আদেশ চাই তিনি ঈশ্বরের কাছে প্রার্থনা করুন, তিনি তার ছেলেকে এবং তার ছেলেকে রক্ষা করেছেন। তারা তোমাকে ঈশ্বরের কাছে আশীর্বাদ করেছে, যেন তুমি কিছু কাজ করে থাকো.","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ حَكِيمٍ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ سَلَمَةَ ‏ ‏أَنْ ‏ ‏عَبْدَ الْحَمِيدِ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏دَعَا ‏ ‏مُوسَى بْنَ طَلْحَةَ ‏ ‏حِينَ ‏ ‏عَرَّسَ ‏ ‏عَلَى ابْنِهِ فَقَالَ يَا ‏ ‏أَبَا عِيسَى ‏ ‏كَيْفَ بَلَغَكَ فِي الصَّلَاةِ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مُوسَى ‏ ‏سَأَلْتُ ‏ ‏زَيْدَ بْنَ خَارِجَةَ ‏ ‏عَنْ الصَّلَاةِ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏زَيْدٌ ‏ ‏إِنِّي سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِنَفْسِي فَقُلْتُ ‏ ‏كَيْفَ الصَّلَاةُ عَلَيْكَ قَالَ ‏ ‏صَلُّوا وَاجْتَهِدُوا ثُمَّ قُولُوا اللَّهُمَّ بَارِكْ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَعَلَى آلِ ‏ ‏مُحَمَّدٍ ‏ ‏كَمَا بَارَكْتَ عَلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏إِنَّكَ حَمِيدٌ مَجِيدٌ ‏","","",""],[1622,1622,"","আমরা যে - স্বাধীনতা সৃষ্টি করেছি, সেই সম্বন্ধে আমরা কথা বলেছিলাম কিন্তু এটা ছিল এক দুঃখকর প্রাণীর স্বপ্ন । আমি তোমার সাথে ব্রেক-আপ করবো, আর আমি কখনো জানিনা আমি কে, ঈশ্বর তাকে আদেশ দিয়েছেন আর তিনি তাকে তার শান্তি দেয়ার জন্য তাকে সেবা করেছেন আর আমি তাকে দেখতে পাব। তিনি বলেছিলেন যে, যদি আমি অন্য শ্বাস নিয়ে তিনটে জিনিস করতাম, তা হলে তারা দরিদ্রদের থেকে কিছুটা দূরে চলে যেত ।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبَّادٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَبَّادِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏أَتَى ‏ ‏الْحَارِثُ بْنُ خَزَمَةَ ‏ ‏بِهَاتَيْنِ الْآيَتَيْنِ مِنْ آخِرِ ‏ ‏بَرَاءَةَ ‏ { ‏لَقَدْ جَاءَكُمْ رَسُولٌ مِنْ أَنْفُسِكُمْ ‏} ‏إِلَى ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏فَقَالَ مَنْ مَعَكَ عَلَى هَذَا قَالَ لَا أَدْرِي وَاللَّهِ ‏ ‏إِلَّا أَنِّي ‏ ‏أَشْهَدُ لَسَمِعْتُهَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَوَعَيْتُهَا وَحَفِظْتُهَا ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏وَأَنَا أَشْهَدُ لَسَمِعْتُهَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ ‏ ‏لَوْ كَانَتْ ثَلَاثَ آيَاتٍ لَجَعَلْتُهَا سُورَةً عَلَى حِدَةٍ فَانْظُرُوا سُورَةً مِنْ الْقُرْآنِ فَضَعُوهَا فِيهَا فَوَضَعْتُهَا فِي آخِرِ ‏ ‏بَرَاءَةَ ‏","","",""],[1623,1623,"","আমরা দুই দিন কথা বলেছি, কিন্তু বাবা সবসময় ফিরে আসে।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ يَعْنِي أَبَا دَاوُدَ الطَّيَالِسِيَّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ الْخَزَّازُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏قَالَ ‏ ‏قَدَّمْتُ بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَمْرًا فَجَعَلُوا ‏ ‏يَقْرُنُونَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تَقْرُنُوا ‏","","",""],[1624,1624,"","আমরা বাবাকে সাহায্য করার জন্য একটি ভাল উপায় নিয়ে কথা বলেছি এবং তিনি গর্বিত ছিলেন। ঈশ্বর তাঁর কাছে সাহায্য চেয়ে প্রার্থনা করেছেন এবং তাঁর গালের গালটিও ভালবাসেন। আমাদের যা বলার আছে তা হল, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আমি ঈশ্বরের কাছে ফিরে যাচ্ছি, কারণ আমি বলতে চাই।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏وَكَانَ يَخْدُمُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْجِبُهُ خِدْمَتُهُ فَقَالَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏أَعْتِقْ ‏ ‏سَعْدًا ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ مَا لَنَا ‏ ‏مَاهِنٌ غَيْرُهُ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْتِقْ ‏ ‏سَعْدًا ‏ ‏أَتَتْكَ الرِّجَالُ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُدَ ‏ ‏يَعْنِي السَّبْيَ ‏","","",""],[1625,1625,"","আমরা একে অপরের ছেলের কথা বলেছি যার বাবার আমার ছেলে আছে। আমি জানি সে আমাকে এটা জিজ্ঞেস করতে শিখিয়েছে। আর আমি যা বলি তা হলো অনুপ্রেরণার শক্তিতে। আমি আমার নিজের ভাগ্য বেছে নিতে সক্ষম, সে বলে তুমি কে, আমরা হয়তো তোমাকে মোকাবেলা করেছি।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏بُرَيْدِ بْنِ أَبِي مَرْيَمَ السَّلُولِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الْحَوْرَاءِ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ عَلِيٍّ ‏ ‏قَالَ ‏ ‏عَلَّمَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَلِمَاتٍ أَقُولُهُنَّ فِي ‏ ‏قُنُوتِ ‏ ‏الْوَتْرِ ‏ ‏اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ وَعَافِنِي فِيمَنْ عَافَيْتَ وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ وَبَارِكْ لِي فِيمَا أَعْطَيْتَ وَقِنِي شَرَّ مَا قَضَيْتَ فَإِنَّكَ تَقْضِي وَلَا ‏ ‏يُقْضَى عَلَيْكَ إِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ ‏","","",""],[1626,1626,"","আমরা বাবার সাথে তোমার পার্টনারের কথা বলেছি... ...আমরা তার হেফাজতে জড়িত ছিলাম... ...তোমার লোকেরা ঐ লোকদের স্পর্শ করেছে যারা এটা করতে পারেনি. তার ডান এবং Miky এর পেটেন্ট তার টাকার জন্য যাবে না যতক্ষণ না সে যেতে পারবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏هُبَيْرَةَ ‏ ‏خَطَبَنَا ‏ ‏الْحَسَنُ بْنُ عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ ‏ ‏لَقَدْ فَارَقَكُمْ رَجُلٌ بِالْأَمْسِ لَمْ يَسْبِقْهُ الْأَوَّلُونَ بِعِلْمٍ وَلَا يُدْرِكُهُ الْآخِرُونَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَبْعَثُهُ بِالرَّايَةِ ‏ ‏جِبْرِيلُ ‏ ‏عَنْ يَمِينِهِ ‏ ‏وَمِيكَائِيلُ ‏ ‏عَنْ شِمَالِهِ لَا يَنْصَرِفُ حَتَّى يُفْتَحَ لَهُ ‏","","",""],[1627,1627,"","আমরা বাবার গোপন কথা বলেছি, আমাকে ধোঁকা দেয়ার চেষ্টা করে। আমি তোমাদের বলছি, সে যা করেছে তা স্পর্শ করতে। সে তাকে ছেড়ে দেবে এবং পতাকা দিয়ে পতাকাটি তুলে দিবে। সে তার সময় তার নিজের সাথে কাটাতে পারবে, সে একটা চাকরের জন্য শিকার করছিল, আমাদের জেতার আগে তাকে শিকার করা হয়েছিল, আমার বাবা খুশি হতে হবে, ঈশ্বরের ইচ্ছাতে যেতে হলে আমাকে খুশি হতে হবে। তাকে তার কাছে পৌঁছে দিতে হবে এবং তাকে তার কাছে পৌঁছে দিতে হবে, যেমন Yons.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ حُبْشِيٍّ ‏ ‏قَالَ ‏ ‏خَطَبَنَا ‏ ‏الْحَسَنُ بْنُ عَلِيٍّ ‏ ‏بَعْدَ قَتْلِ ‏ ‏عَلِيٍّ ‏ ‏فَقَالَ لَقَدْ فَارَقَكُمْ رَجُلٌ بِالْأَمْسِ مَا سَبَقَهُ الْأَوَّلُونَ بِعِلْمٍ وَلَا أَدْرَكَهُ الْآخِرُونَ إِنْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَبْعَثُهُ وَيُعْطِيهِ الرَّايَةَ فَلَا يَنْصَرِفُ حَتَّى يُفْتَحَ لَهُ وَمَا تَرَكَ مِنْ صَفْرَاءَ وَلَا بَيْضَاءَ إِلَّا سَبْعَ مِائَةِ دِرْهَمٍ مِنْ عَطَائِهِ كَانَ ‏ ‏يَرْصُدُهَا ‏ ‏لِخَادِمٍ لِأَهْلِهِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏بُرَيْدِ بْنِ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏أَبِي الْحَوْرَاءِ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ عَلِيٍّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَّمَهُ أَنْ يَقُولَ فِي ‏ ‏الْوَتْرِ ‏ ‏فَذَكَرَ مِثْلَ حَدِيثِ ‏ ‏يُونُسَ ‏","","",""],[1628,1628,"","আমরা কথা বলেছিলাম আমার উপর একটা আঘাত লেগেছে তারা শক্তি তৈরি করেছে আর দেবীর জন্ম দেয়ার সময় তারা কখনো ভালো কাউকে হত্যা করেনি.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏أَنْبَأَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ بْنِ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ عَلِيٍّ ‏ ‏أَنَّهُ مَرَّ بِهِمْ جَنَازَةٌ فَقَامَ الْقَوْمُ وَلَمْ يَقُمْ فَقَالَ ‏ ‏الْحَسَنُ ‏ ‏مَا صَنَعْتُمْ إِنَّمَا ‏ ‏قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَأَذِّيًا بِرِيحِ الْيَهُودِيِّ ‏","","",""],[1629,1629,"","আমি আমার বাবার কাছে ক্লান্ত হয়ে পড়ায় খুশি হয়ে কথা বলেছি, আমাকে বলতেই হচ্ছে যে, সে যদি না পড়ে যায় তাহলে আমি আনন্দ পেয়েছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি তার সাথে দেখা করতে রাজি হবেন ঐ অনুষ্ঠানে তার একজন মানুষ আছে, পাসটা বললো আমরা বন্ধুত্ব করি নি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏بُرَيْدُ بْنُ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏أَبِي الْحَوْرَاءِ السَّعْدِيِّ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِلْحَسَنِ بْنِ عَلِيٍّ ‏ ‏مَا تَذْكُرُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَذْكُرُ أَنِّي أَخَذْتُ تَمْرَةً مِنْ تَمْرِ ‏ ‏الصَّدَقَةِ ‏ ‏فَأَلْقَيْتُهَا فِي ‏ ‏فِيَّ فَانْتَزَعَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِلُعَابِهَا فَأَلْقَاهَا فِي التَّمْرِ فَقَالَ لَهُ رَجُلٌ مَا عَلَيْكَ لَوْ أَكَلَ هَذِهِ التَّمْرَةَ قَالَ ‏ ‏إِنَّا لَا نَأْكُلُ ‏ ‏الصَّدَقَةَ ‏","","",""],[1630,1630,"","সে বলছিল যে সে তোমাকে কি বলতে চায়... ...যেটা না জেনে যে বিশ্বাসীদের আদেশ দেয়া হয়েছে আর মিথ্যাটা ঠিক আছে।","‏ ‏قَالَ ‏ ‏وَكَانَ يَقُولُ ‏ ‏دَعْ مَا ‏ ‏يَرِيبُكَ ‏ ‏إِلَى مَا لَا ‏ ‏يَرِيبُكَ ‏ ‏فَإِنَّ الصِّدْقَ طُمَأْنِينَةٌ وَإِنَّ الْكَذِبَ ‏ ‏رِيبَةٌ ‏","","",""],[1631,1631,"","তিনি আমাদের শেখানো হয়েছে আমাকে ঈশ্বর, তিনি আমাকে আমার জীবন থেকে মুক্তির হুমকি, যখন আপনি আমার আত্মবিশ্বাস, আপনি কি আপনি জানেন আপনি জানেন আপনি কি মনে আছে আপনি কি না আপনি বলতে পারে.","‏ ‏قَالَ ‏ ‏وَكَانَ يُعَلِّمُنَا هَذَا الدُّعَاءَ ‏ ‏اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ وَعَافِنِي فِيمَنْ عَافَيْتَ ‏ ‏وَتَوَلَّنِي ‏ ‏فِيمَنْ ‏ ‏تَوَلَّيْتَ ‏ ‏وَبَارِكْ لِي فِيمَا أَعْطَيْتَ وَقِنِي شَرَّ مَا قَضَيْتَ إِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ ‏ ‏وَرُبَّمَا قَالَ تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ ‏","","",""],[1632,1632,"","আমরা কিভাবে একজন যাজকের সাথে দেখা করতে পারি, যে তাকে মারতে চেয়েছিল, ঈশ্বর কখনোই আমাকে বন্ধুত্বের অনুগ্রহে প্রবেশ করতে বলেননি। তার নিজের একটা প্রার্থনা ঈশ্বরের কাছে করতে হবে ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتُ بْنُ عُمَارَةَ ‏ ‏حَدَّثَنَا ‏ ‏رَبِيعَةُ بْنُ شَيْبَانَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لِلْحَسَنِ بْنِ عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏مَا تَذْكُرُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَدْخَلَنِي غُرْفَةَ ‏ ‏الصَّدَقَةِ ‏ ‏فَأَخَذْتُ مِنْهَا تَمْرَةً فَأَلْقَيْتُهَا فِي ‏ ‏فِيَّ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلْقِهَا فَإِنَّهَا لَا تَحِلُّ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا لِأَحَدٍ مِنْ أَهْلِ بَيْتِهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1633,1633,"","বাবার সাথে আমার ভাইয়ের সাথে যাওয়ার চেষ্টা করা সম্পর্কে আমরা কথা বলেছিলাম। আমি তার চেয়ে ভালো ছিলাম। তুমি কি তাকে বলেছিলে নাকি সে আসবে, সে বলেছে আমি তার সাথে হাঁটবো। আমি আমার স্ত্রীর সঙ্গে বাইবেল অধ্যয়ন করতে শুরু করি এবং আমার জীবনে ঈশ্বরের উদ্দেশ্য সম্বন্ধে আরও ভালোভাবে জানতে পারি । অবিশ্বাস্য অবিশ্বাস্য অবিশ্বাস্য ভাবে অবিশ্বাস্য ভাবে বিশ্বাস করবেন না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ هُوَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ صَالِحٍ ‏ ‏حَدَّثَنَا ‏ ‏بُرَيْدُ بْنُ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏أَبِي الْحَوْرَاءِ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ ‏ ‏حَسَنِ بْنِ عَلِيٍّ ‏ ‏فَسُئِلَ مَا ‏ ‏عَقَلْتَ ‏ ‏مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ كُنْتُ أَمْشِي مَعَهُ فَمَرَّ عَلَى ‏ ‏جَرِينٍ ‏ ‏مِنْ تَمْرِ ‏ ‏الصَّدَقَةِ ‏ ‏فَأَخَذْتُ تَمْرَةً فَأَلْقَيْتُهَا فِي ‏ ‏فِيَّ فَأَدْخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُصْبُعَهُ فِي ‏ ‏فِيَّ فَأَخْرَجَهَا ‏ ‏بِلُعَابِي فَقَالَ بَعْضُ الْقَوْمِ وَمَا عَلَيْكَ لَوْ تَرَكْتَهَا قَالَ ‏ ‏إِنَّا آلَ ‏ ‏مُحَمَّدٍ ‏ ‏لَا تَحِلُّ لَنَا ‏ ‏الصَّدَقَةُ ‏ ‏قَالَ ‏ ‏وَعَقَلْتُ ‏ ‏مِنْهُ الصَّلَوَاتِ الْخَمْسَ ‏","","",""],[1634,1634,"","একজন ভাল যাজকের চেয়ে ভাল ছেলে, যিনি কখনো বালক ছিলেন না বলে মনে হয় । একজন ছেলের দ্বারা পাঠানো হয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ يَعْنِي ابْنَ إِبْرَاهِيمَ وَهُوَ التُّسْتَرِيُّ ‏ ‏أَنْبَأَنَا ‏ ‏مُحَمَّدٌ ‏ ‏قَالَ ‏ ‏نُبِّئْتُ أَنَّ ‏ ‏جِنَازَةً مَرَّتْ عَلَى ‏ ‏الْحَسَنِ بْنِ عَلِيٍّ ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏فَقَامَ ‏ ‏الْحَسَنُ ‏ ‏وَقَعَدَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏فَقَالَ ‏ ‏الْحَسَنُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏أَلَمْ تَرَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّتْ بِهِ جِنَازَةٌ فَقَامَ ‏ ‏فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏بَلَى وَقَدْ جَلَسَ فَلَمْ يُنْكِرْ ‏ ‏الْحَسَنُ ‏ ‏مَا قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏","","",""],[1635,1635,"","আমরা প্রভুর সাথে আমার ভালোবাসাকে খালি করতে চেষ্টা করেছি। আমি জানি, ঈশ্বরের প্রতি তুমি কী করবে তা নিয়ে তুমি কি ভাবছো আর সে আমাকে জিজ্ঞেস করতে বলেছে যে সে কে। আমি একটা টেকস্ট নিয়ে এসেছি। ঈশ্বরের কাছে যাওয়াতে আমি যে - বন্ধুত্ব গড়েছিলাম, তা আমার মধ্যে দ্বন্দ্বের সৃষ্টি করেছিল ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏بُرَيْدَ بْنَ أَبِي مَرْيَمَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي الْحَوْرَاءِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِلْحَسَنِ بْنِ عَلِيٍّ ‏ ‏مَا تَذْكُرُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَذْكُرُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنِّي أَخَذْتُ تَمْرَةً مِنْ تَمْرِ الصَّدَقَةِ فَجَعَلْتُهَا فِي ‏ ‏فِيَّ قَالَ فَنَزَعَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِلُعَابِهَا فَجَعَلَهَا فِي التَّمْرِ فَقِيلَ يَا رَسُولَ اللَّهِ مَا كَانَ عَلَيْكَ مِنْ هَذِهِ التَّمْرَةِ لِهَذَا الصَّبِيِّ قَالَ ‏ ‏وَإِنَّا آلَ ‏ ‏مُحَمَّدٍ ‏ ‏لَا تَحِلُّ لَنَا ‏ ‏الصَّدَقَةُ ‏","","",""],[1636,1636,"","সে বলছিল যে সে তোমাকে কি বলতে চায়... ...যেটা না জেনে যে বিশ্বাসীদের আদেশ দেয়া হয়েছে আর মিথ্যাটা ঠিক আছে।","‏ ‏قَالَ ‏ ‏وَكَانَ يَقُولُ ‏ ‏دَعْ مَا ‏ ‏يَرِيبُكَ ‏ ‏إِلَى مَا لَا ‏ ‏يَرِيبُكَ ‏ ‏فَإِنَّ الصِّدْقَ طُمَأْنِينَةٌ وَإِنَّ الْكَذِبَ ‏ ‏رِيبَةٌ ‏","","",""],[1637,1637,"","আমাকে ঈশ্বর বলে ডাকা হয়েছে, তিনি আমাকে আমার জীবন থেকে মুক্ত করার হুমকি দিয়েছেন। আমার বাবা মারা যাওয়ার পর যে গৌরব সে তোমার মনের উপর সন্দেহ করেনি.","‏ ‏قَالَ ‏ ‏وَكَانَ يُعَلِّمُنَا هَذَا الدُّعَاءَ ‏ ‏اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ وَعَافِنِي فِيمَنْ عَافَيْتَ ‏ ‏وَتَوَلَّنِي ‏ ‏فِيمَنْ ‏ ‏تَوَلَّيْتَ ‏ ‏وَبَارِكْ لِي فِيمَا أَعْطَيْتَ وَقِنِي شَرَّ مَا قَضَيْتَ إِنَّكَ تَقْضِي وَلَا ‏ ‏يُقْضَى عَلَيْكَ إِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَأَظُنُّهُ قَدْ قَالَ هَذِهِ أَيْضًا تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَقَدْ حَدَّثَنِي مَنْ سَمِعَ هَذَا مِنْهُ ثُمَّ إِنِّي سَمِعْتُهُ حَدَّثَ بِهَذَا الْحَدِيثِ مَخْرَجَهُ إِلَى ‏ ‏الْمَهْدِيِّ ‏ ‏بَعْدَ مَوْتِ أَبِيهِ فَلَمْ يَشُكَّ فِي تَبَارَكْتَ وَتَعَالَيْتَ فَقُلْتُ ‏ ‏لِشُعْبَةَ ‏ ‏إِنَّكَ تَشُكُّ فِيهِ فَقَالَ لَيْسَ فِيهِ شَكٌّ ‏","","",""],[1638,1638,"","আমরা আমাদের সেরাদের কথা বলছি, যে কিনা এক কৌতুকের সন্তান, সে এক অন্ত্যেষ্টিক্রিয়ার আয়োজন করেছে, আমি তাদের একত্রিত করেছি এবং অন্য জন বলেছে যে সে জানতো। সে এটা করতে পারে নি, সে সেট করেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏وَالْحَسَنَ بْنَ عَلِيٍّ ‏ ‏مَرَّتْ بِهِمَا ‏ ‏جِنَازَةٌ فَقَامَ أَحَدُهُمَا وَجَلَسَ الْآخَرُ فَقَالَ الَّذِي قَامَ أَمَا تَعْلَمُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَامَ قَالَ بَلَى وَقَعَدَ ‏","","",""],[1639,1639,"","আমরা কথা বলেছিলাম, একসময় হাই-এন্ড ছেলেকে হারিয়ে ফেলার ব্যাপারে। মনে হয়, তারা বলেছে সে ঈশ্বরের দোহাই দিয়ে নয়, সে নিজেই বলে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الثَّقَفِيُّ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏أَنَّ ‏ ‏الْحَسَنَ بْنَ عَلِيٍّ ‏ ‏وَابْنَ عَبَّاسٍ ‏ ‏رَأَيَا جَنَازَةً فَقَامَ أَحَدُهُمَا وَقَعَدَ الْآخَرُ فَقَالَ الَّذِي قَامَ أَلَمْ يَقُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ الَّذِي قَعَدَ بَلَى وَقَعَدَ ‏","","",""],[1640,1640,"","আমরা অনেক আশীর্বাদ করেছি, আমরা তোমার বাবার মত পুতুল ছেলে হয়ে কথা বলেছি। তারপর তিনি চেয়ার নিয়ে আসেন।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ أَبِي يَحْيَى ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِيهَا ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلسَّائِلِ حَقٌّ وَإِنْ جَاءَ عَلَى فَرَسٍ ‏","","",""],[1641,1641,"","আমি ইতিমধ্যেই একটি চমৎকার পুত্র কথা বলেছি, আপনি কি মনে করেন না যে, ঈশ্বর তার কাছে প্রার্থনা করবেন তার সাথে বন্ধুত্বের অনুগ্রহ নিয়ে। লর্ড প্রার্থনা করেন এবং আমি তাকে লিফট দিয়ে তুলে ধরি।","‏ ‏أَنْبَأَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتُ بْنُ عُمَارَةَ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ شَيْبَانَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِلْحُسَيْنِ بْنِ عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏مَا ‏ ‏تَعْقِلُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ صَعِدْتُ ‏ ‏مَعَهُ غُرْفَةَ الصَّدَقَةِ ‏ ‏فَأَخَذْتُ تَمْرَةً ‏ ‏فَلُكْتُهَا ‏ ‏فِي ‏ ‏فِيَّ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلْقِهَا فَإِنَّهَا لَا تَحِلُّ لَنَا ‏ ‏الصَّدَقَةُ ‏","","",""],[1642,1642,"","আমরা একটা ছেলে নিয়ে কথা বলেছি, আমার সাথে কিছু একটা সমস্যা আছে। সে ঈশ্বরের কাছে প্রার্থনা করলো, আর তার মুখের মধ্যে শান্তি আনার জন্য সে আত্মসমর্পণ করবে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏وَيَعْلَي ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَجَّاحٌ يَعْنِي ابْنَ دِينَارٍ الْوَاسِطِيَّ ‏ ‏عَنْ ‏ ‏شُعَيْبِ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏حُسَيْنِ بْنِ عَلِيٍّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْ حُسْنِ إِسْلَامِ الْمَرْءِ قِلَّةَ الْكَلَامِ فِيمَا لَا يَعْنِيهِ ‏","","",""],[1643,1643,"","আমি মনে করি, তিনি যখন ঈশ্বরের কাছে প্রার্থনা করেছিলেন, তখন তিনি জিজ্ঞেস করেছিলেন, তিনি কার কাছে আত্মসমর্পণ করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ عَلِيٍّ ‏ ‏يَزْعُمُ عَنْ ‏ ‏حُسَيْنٍ ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏أَحَدِهِمَا ‏ ‏أَنَّهُ قَالَ إِنَّمَا ‏ ‏قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَجْلِ جَنَازَةِ يَهُودِيٍّ مُرَّ بِهَا عَلَيْهِ فَقَالَ آذَانِي رِيحُهَا ‏","","",""],[1644,1644,"","আমরা আমাদের এক বানের কাছে এসেছি, যে আমাদের বলে যে আমার বাবা একটা কুত্তার বাচ্চা ছিল, বাবার চেয়ে ভালো, আমার বাবার মেয়ে। প্রভু, তাকে একটা স্বপ্নের কথা মনে করিয়ে দিতে হবে তাকে যেন মনে করিয়ে দিতে হয়। যদি তুমি এটা ভাড়া দিতে চাও, এটা কেবল তখনই ঘটে যখন আমরা ভালো থাকি। আমার বাবা জানতে চায়। আমি যা বলি, তা হল বৃষ্টিতে আমি যা বলি, তা নিয়ে তিনি বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏وَعَبَّادُ بْنُ عَبَّادٍ ‏ ‏قَالَا أَنْبَأَنَا ‏ ‏هِشَامُ بْنُ أَبِي هِشَامٍ ‏ ‏قَالَ ‏ ‏عَبَّادٌ ‏ ‏ابْنُ زِيَادٍ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ ابْنَةِ الْحُسَيْنِ ‏ ‏عَنْ ‏ ‏أَبِيهَا ‏ ‏الْحُسَيْنِ بْنِ عَلِيٍّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ مُسْلِمٍ وَلَا مُسْلِمَةٍ يُصَابُ بِمُصِيبَةٍ فَيَذْكُرُهَا وَإِنْ طَالَ عَهْدُهَا ‏ ‏قَالَ ‏ ‏عَبَّادٌ ‏ ‏قَدُمَ عَهْدُهَا ‏ ‏فَيُحْدِثُ لِذَلِكَ اسْتِرْجَاعًا إِلَّا جَدَّدَ اللَّهُ لَهُ عِنْدَ ذَلِكَ فَأَعْطَاهُ مِثْلَ أَجْرِهَا يَوْمَ أُصِيبَ بِهَا ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏شَرِيكُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏بُرَيْدِ بْنِ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏أَبِي الْحَوْرَاءِ ‏ ‏عَنِ ‏ ‏الْحُسَيْنِ بْنِ عَلِيٍّ ‏ ‏قَالَ ‏ ‏عَلَّمَنِي جَدِّي ‏ ‏أَوْ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَلِمَاتٍ أَقُولُهُنَّ فِي ‏ ‏الْوَتْرِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[1645,1645,"","আমার বাবার চেয়ে বাবার চেয়ে আমার দুটো ভাল আগ্রহ রয়েছে, যার বাবার চেয়ে তার বাবার চেয়ে ভাল । আমি তাকে বলেছিলাম, আর সে আমাকে প্রার্থনা করতে দেয়নি, আর সে আত্মসমর্পণ করেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏وَأَبُو سَعِيدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ غَزِيَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْبَخِيلُ مَنْ ذُكِرْتُ عِنْدَهُ ثُمَّ لَمْ يُصَلِّ عَلَيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1646,1646,"","আমরা মূসা আমাদের সেরাদের সাথে কথা বলেছি, ঈশ্বর একজন ইহুদি পুত্রকে খুঁজে বের করতে সক্ষম হয়েছেন। আপনি বলতে পারবেন, ঈশ্বর প্রার্থনা করছেন তিনি যেন প্রার্থনা করেন, যেন তিনি একজন ব্যক্তি পাওয়া পেয়ে ভালোর থেকে মুক্তি লাভ করেন।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ حُسْنِ إِسْلَامِ الْمَرْءِ تَرْكُهُ مَا لَا يَعْنِيهِ ‏","","",""],[1647,1647,"","আমরা ঈশ্বরের প্রেমে জীবন্ত ছেলেকে সাহায্য করার মাধ্যমে বিচার করার চেষ্টা করেছি। তিনি বলেছিলেন যে, আমরা যাচ্ছি বলে যে, ঈশ্বর তার জন্য প্রার্থনা করুন এবং তার জন্য প্রার্থনা করুন। সে আত্মসমর্পণ করবে... ...আমরা হয়ত তোমার আশীর্বাদের কথা শেষ করতে পারি... ...আর তোমার আশীর্বাদ তোমার কাছে আছে.","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏قَالَ ‏ ‏تَزَوَّجَ ‏ ‏عَقِيلُ بْنُ أَبِي طَالِبٍ ‏ ‏فَخَرَجَ عَلَيْنَا فَقُلْنَا ‏ ‏بِالرِّفَاءِ ‏ ‏وَالْبَنِينَ فَقَالَ ‏ ‏مَهْ ‏ ‏لَا تَقُولُوا ذَلِكَ فَإِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏نَهَانَا عَنْ ذَلِكَ وَقَالَ قُولُوا بَارَكَ اللَّهُ لَهَا فِيكَ وَبَارَكَ لَكَ فِيهَا ‏","","",""],[1648,1648,"","আমি আমার বাবাকে গ্রেপ্তার করার বিষয়ে কথা বলেছিলাম । তুমি আর তোমার আশীর্বাদ আমাদের কমান্ডের ব্যাপারে যা কিছু শিখেছ.","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ وَهُوَ ابْنُ عُلَيَّةَ ‏ ‏أَنْبَأَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏أَنَّ ‏ ‏عَقِيلَ بْنَ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏تَزَوَّجَ امْرَأَةً مِنْ ‏ ‏بَنِي جُشَمَ ‏ ‏فَدَخَلَ عَلَيْهِ الْقَوْمُ فَقَالُوا ‏ ‏بِالرِّفَاءِ ‏ ‏وَالْبَنِينَ فَقَالَ لَا تَفْعَلُوا ذَلِكَ قَالُوا فَمَا نَقُولُ يَا ‏ ‏أَبَا يَزِيدَ ‏ ‏قَالَ قُولُوا ‏ ‏بَارَكَ اللَّهُ لَكُمْ وَبَارَكَ عَلَيْكُمْ إِنَّا كَذَلِكَ كُنَّا نُؤْمَرُ ‏","","",""],[1649,1649,"","আমার বাবার সাথে আমার ভালবাসার কথা বলেছিলাম, আমার ছেলের অনুগ্রহে আশীর্বাদ করো, আমার ভালবাসার আনন্দ নিয়ে। আমাদের দরজা থেকে বেঁচে যাওয়াটা বেছে নেয়া হয়েছে। আমরা এমন কিছু শুনতে পাচ্ছি না যখন তারা চলে যাবে। আমার গর্ব এবং যারা তাদেরকে শত্রু হিসেবে সেবা করতে ইচ্ছুক, তাদের দুঃখ সম্বন্ধে নিশ্চিত করে বলা হয়েছিল । তারপর আমরা ভালো প্রতিবেশীকে পেয়ে গেলাম, তার আগে তিনি সামন্তের সাথে কথা বলেছিলেন আর তারপর তাদের সবাইকে বললেন যে তিনি তাদের সেরাটা করেছেন। তাদের শক্তি নিজের হাতে ছিল না এবং তারা দুই হাত দিয়ে এসেছে, আমরা জানি না আমরা কি করব, তারা জানে তারা কি করেছে, তারপর তারা আমাদের প্রভু। আমরা তাকে চিনি না। আমি জানি না, তারা এমন কিছু করেছে যে এটা এমন নয় যে তারা বোকা হতে যাচ্ছে। তারা বলে এটা বিশ্বাস করা বা না করা। তারা তাদের নিজেদের চলে যেতে দেবে এবং তারা জানতে পারবে আমি তাদের সাথে যেতে রাজি নই এবং আমি তাদের কাছে যেতে এবং যেতে প্রস্তুত। আমি তাদেরকে বলতে চাই যে, কীভাবে তারা তাদের কাছে প্রতিজ্ঞা করেছিল । তাদের মধ্যে কেউ কিছু বলে যদি তারা আমাদের জানা কথা বলে, সে আমাদের হারাত এবং আমাদের সাথে যুদ্ধ করতে দিত। আমাদের মধ্যে অনেকেই রয়েছেন আমাদের মধ্যে অনেকে সবচেয়ে খারাপ প্রতিবেশী । শুধু তাকে সফল করতে, আমরা যা খুঁজছি তা দূর করতে, আমরা তদন্ত করেছি এবং নিরাপত্তা ও ক্ষমার আগমনের মাধ্যমে। যুদ্ধের সময় আসা লোকেরা বলেছে সব এতিমদের টাকা ত্রাণে নষ্ট হয়ে গেছে এবং আমরা ঈশ্বরকে খেলতে চেয়েছিলাম, তার সাথে যে কোম্পানিটি বলল তার আদেশ ছিল, সে তা পালন করতে হবে। আমরা তোমাকে কিছু বলবো, আর আমাদের কখনোই যেতে হবে না। আমাদের খুঁজে বের করতে হবে আপনি কে আর আমরা আপনার জীবনে আমরা কে, সে বলেছে সে কি তার কাছে এসেছে যা তিনি বলেছিলেন ভুল করার সাহস ছিল, ভুল করার সাহস? তারা যা বলেছে আর বলে যে নারীগুলো তাই করবে। একটা সমস্যা যা আমি কখনও প্রভুকে সেবা করবো না। ঝড় আর ঈশ্বর তাদের আগামীকাল তাদের বলেছেন। তাদের ক্ষমতা আছে, তারপর আমি তাদের খুঁজে বের করবো, আমাদের মধ্যে কাউকে রক্ষা করবো না যদি তারা তাকে ধোঁকা দেয়। তাদের জিজ্ঞেস করুন তারা কি আর কি কি করবে। আমাকে যদি আমি জিজ্ঞেস করি, তারা আমাকে কি বলেছে। যখন তারা তাকে বলে তারা বলে তারা তার নিজের ছেলের সাথে কথা বলে না, তখন তারা বলে সে নাকি তার একটা মহান ছেলেকে নিয়ে গেছে। আর যদি আমরা ফিরে যাই, তাহলে তুমি প্রেমে পড়ে যাবে । আমার সাথে, তুমি কে হবে, আমি বাড়ি গিয়ে তোমাদের একজনকে কষ্ট দিতে চাই, আর আমি তোমাকে ভালবাসি, আর আমরা এটা পেয়েছি। ঈশ্বর আমার কাছ থেকে ঘুষ নিয়েছেন যখন তিনি আমার রাজাকে কেড়ে নিয়েছেন, তখন তিনি আমার রাজা হিসেবে গ্রহণ করেছেন। ঘুষ নিতে এবং বিশ্বের শপথ নিতে, তিনি কোথাও আউট এবং আমরা অনেক মজা আছে পেয়েছিলাম. আমরা জানতাম আমাদের কী ছিল কিন্তু সে আমাদের যা জানা ছিল তা নিয়ে ভীত ছিল। এটা দেখায় যে আমার লোক কে, কে আসলে কে তা জানে না। এবং তারা নাইলকে বলার জন্য আবেদন জানিয়েছে। আর তারা বলে দিয়েছে, নীলনদের কথা বলার জন্য। কিন্তু আমরা কি জানি? এটা আসলে আমার কাছে আছে। কিন্তু আমি জানি না যে, আমি জানি না। কিন্তু আমি জানি না, আমি জানি না, আমি জানি না। কিন্তু আমি জানি না যে আমার এই ব্যাপারে আমার কোন ধারণা নেই। কিন্তু আমি নিশ্চিত। কিন্তু আমি জানি না। কিন্তু আমি যদি আমার ধারণা করি, আমি জানি যে, আমি জানি, আমি জানি না যে, আমি আসলে আমি জানি না যে, আমি আসলে জানি না। কিন্তু আমি জানি না। কিন্তু আমি জানি, আমি জানি, আমি জানি না। আমি জানি, আমি জানি না যে, আমি আসলে আমি জানি না। আমি জানি না। আমি জানি, আমি জানি, আমি জানি, আমি কী করব। কিন্তু আমি জানি যে, আমি জানি। এবং আমি জানি না। এটা আমার কাছে এটা একটা ছোট। কিন্তু আমি যা। এবং আমি যদি তুমি জানো না। কিন্তু আমি যখন তুমি জানো না, আমি এটা একটা প্রশ্ন করি, ঈশ্বরের দেবতা এসেছে এবং তাকে আত্মসমর্পণ করেছে যে তার ইচ্ছা হারিয়েছে। তারপর আমরা বলবো যে ভালোটা হারিয়ে যাবে। তারপর সে তার বুকে লিখে দিয়েছে। পথে পথে বেরিয়ে গেলাম, খোদা তাঁর গণনায় ফিরে গেল এবং নিজের ভিনেগার আর তার সিঁড়িতে থাকার জন্য। আর আত্মসমর্পণ করো আর তোমার হাতে.","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ مُسْلِمِ بْنِ عُبَيْدِ اللَّهِ بْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ الْمَخْزُومِيِّ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ابْنَةِ أَبِي أُمَيَّةَ بْنِ الْمُغِيرَةِ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏لَمَّا نَزَلْنَا أَرْضَ ‏ ‏الْحَبَشَةِ ‏ ‏جَاوَرْنَا بِهَا خَيْرَ جَارٍ ‏ ‏النَّجَاشِيَّ ‏ ‏أَمِنَّا عَلَى دِينِنَا وَعَبَدْنَا اللَّهَ لَا نُؤْذَى وَلَا نَسْمَعُ شَيْئًا نَكْرَهُهُ فَلَمَّا بَلَغَ ذَلِكَ ‏ ‏قُرَيْشًا ‏ ‏ائْتَمَرُوا ‏ ‏أَنْ يَبْعَثُوا إِلَى ‏ ‏النَّجَاشِيِّ ‏ ‏فِينَا رَجُلَيْنِ ‏ ‏جَلْدَيْنِ ‏ ‏وَأَنْ يُهْدُوا ‏ ‏لِلنَّجَاشِيِّ ‏ ‏هَدَايَا مِمَّا يُسْتَطْرَفُ مِنْ مَتَاعِ ‏ ‏مَكَّةَ ‏ ‏وَكَانَ مِنْ أَعْجَبِ مَا يَأْتِيهِ مِنْهَا إِلَيْهِ ‏ ‏الْأَدَمُ ‏ ‏فَجَمَعُوا لَهُ ‏ ‏أَدَمًا ‏ ‏كَثِيرًا وَلَمْ يَتْرُكُوا مِنْ ‏ ‏بَطَارِقَتِهِ ‏ ‏بِطْرِيقًا ‏ ‏إِلَّا أَهْدَوْا لَهُ هَدِيَّةً ثُمَّ بَعَثُوا بِذَلِكَ مَعَ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي رَبِيعَةَ بْنِ الْمُغِيرَةِ الْمَخْزُومِيِّ ‏ ‏وَعَمْرِو بْنِ الْعَاصِ بْنِ وَائِلٍ السَّهْمِيِّ ‏ ‏وَأَمَرُوهُمَا أَمْرَهُمْ وَقَالُوا لَهُمَا ادْفَعُوا إِلَى كُلِّ ‏ ‏بِطْرِيقٍ ‏ ‏هَدِيَّتَهُ قَبْلَ أَنْ تُكَلِّمُوا ‏ ‏النَّجَاشِيَّ ‏ ‏فِيهِمْ ثُمَّ قَدِّمُوا ‏ ‏لِلنَّجَاشِيِّ ‏ ‏هَدَايَاهُ ثُمَّ سَلُوهُ أَنْ يُسْلِمَهُمْ إِلَيْكُمْ قَبْلَ أَنْ يُكَلِّمَهُمْ قَالَتْ فَخَرَجَا فَقَدِمَا عَلَى ‏ ‏النَّجَاشِيِّ ‏ ‏وَنَحْنُ عِنْدَهُ بِخَيْرِ دَارٍ وَعِنْدَ خَيْرِ جَارٍ فَلَمْ يَبْقَ مِنْ ‏ ‏بَطَارِقَتِهِ ‏ ‏بِطْرِيقٌ ‏ ‏إِلَّا دَفَعَا إِلَيْهِ هَدِيَّتَهُ قَبْلَ أَنْ يُكَلِّمَا ‏ ‏النَّجَاشِيَّ ‏ ‏ثُمَّ قَالَا لِكُلِّ ‏ ‏بِطْرِيقٍ ‏ ‏مِنْهُمْ إِنَّهُ قَدْ ‏ ‏صَبَا ‏ ‏إِلَى بَلَدِ الْمَلِكِ مِنَّا غِلْمَانٌ ‏ ‏سُفَهَاءُ ‏ ‏فَارَقُوا دِينَ قَوْمِهِمْ وَلَمْ يَدْخُلُوا فِي دِينِكُمْ وَجَاءُوا بِدِينٍ مُبْتَدَعٍ لَا نَعْرِفُهُ نَحْنُ وَلَا أَنْتُمْ وَقَدْ بَعَثَنَا إِلَى الْمَلِكِ فِيهِمْ أَشْرَافُ قَوْمِهِمْ لِيَرُدَّهُمْ إِلَيْهِمْ فَإِذَا كَلَّمْنَا الْمَلِكَ فِيهِمْ ‏ ‏فَتُشِيرُوا ‏ ‏عَلَيْهِ بِأَنْ يُسْلِمَهُمْ إِلَيْنَا وَلَا يُكَلِّمَهُمْ فَإِنَّ قَوْمَهُمْ أَعَلَى بِهِمْ عَيْنًا وَأَعْلَمُ بِمَا عَابُوا عَلَيْهِمْ فَقَالُوا لَهُمَا نَعَمْ ثُمَّ إِنَّهُمَا قَرَّبَا هَدَايَاهُمْ إِلَى ‏ ‏النَّجَاشِيِّ ‏ ‏فَقَبِلَهَا مِنْهُمَا ثُمَّ كَلَّمَاهُ فَقَالَا لَهُ أَيُّهَا الْمَلِكُ إِنَّهُ قَدْ ‏ ‏صَبَا ‏ ‏إِلَى بَلَدِكَ مِنَّا غِلْمَانٌ ‏ ‏سُفَهَاءُ ‏ ‏فَارَقُوا دِينَ قَوْمِهِمْ وَلَمْ يَدْخُلُوا فِي دِينِكَ وَجَاءُوا بِدِينٍ مُبْتَدَعٍ لَا نَعْرِفُهُ نَحْنُ وَلَا أَنْتَ وَقَدْ بَعَثَنَا إِلَيْكَ فِيهِمْ أَشْرَافُ قَوْمِهِمْ مِنْ آبَائِهِمْ وَأَعْمَامِهِمْ وَعَشَائِرِهِمْ لِتَرُدَّهُمْ إِلَيْهِمْ فَهُمْ أَعَلَى بِهِمْ عَيْنًا وَأَعْلَمُ بِمَا عَابُوا عَلَيْهِمْ وَعَاتَبُوهُمْ فِيهِ قَالَتْ وَلَمْ يَكُنْ شَيْءٌ أَبْغَضَ إِلَى ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي رَبِيعَةَ ‏ ‏وَعَمْرِو بْنِ الْعَاصِ ‏ ‏مِنْ أَنْ يَسْمَعَ ‏ ‏النَّجَاشِيُّ ‏ ‏كَلَامَهُمْ فَقَالَتْ ‏ ‏بَطَارِقَتُهُ ‏ ‏حَوْلَهُ صَدَقُوا أَيُّهَا الْمَلِكُ قَوْمُهُمْ أَعَلَى بِهِمْ عَيْنًا وَأَعْلَمُ بِمَا عَابُوا عَلَيْهِمْ فَأَسْلِمْهُمْ إِلَيْهِمَا فَلْيَرُدَّاهُمْ إِلَى بِلَادِهِمْ وَقَوْمِهِمْ قَالَ فَغَضِبَ ‏ ‏النَّجَاشِيُّ ‏ ‏ثُمَّ قَالَ لَا هَا اللَّهِ ايْمُ اللَّهِ إِذَنْ لَا أُسْلِمُهُمْ إِلَيْهِمَا وَلَا أُكَادُ قَوْمًا جَاوَرُونِي وَنَزَلُوا بِلَادِي وَاخْتَارُونِي عَلَى مَنْ سِوَايَ حَتَّى أَدْعُوَهُمْ فَأَسْأَلَهُمْ مَاذَا يَقُولُ هَذَانِ فِي أَمْرِهِمْ فَإِنْ كَانُوا كَمَا يَقُولَانِ أَسْلَمْتُهُمْ إِلَيْهِمَا وَرَدَدْتُهُمْ إِلَى قَوْمِهِمْ وَإِنْ كَانُوا عَلَى غَيْرِ ذَلِكَ مَنَعْتُهُمْ مِنْهُمَا وَأَحْسَنْتُ جِوَارَهُمْ مَا جَاوَرُونِي قَالَتْ ثُمَّ أَرْسَلَ إِلَى ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَعَاهُمْ فَلَمَّا جَاءَهُمْ رَسُولُهُ اجْتَمَعُوا ثُمَّ قَالَ بَعْضُهُمْ لِبَعْضٍ مَا تَقُولُونَ لِلرَّجُلِ إِذَا جِئْتُمُوهُ قَالُوا نَقُولُ وَاللَّهِ مَا عَلَّمَنَا وَمَا أَمَرَنَا بِهِ نَبِيُّنَا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَائِنٌ فِي ذَلِكَ مَا هُوَ كَائِنٌ فَلَمَّا جَاءُوهُ وَقَدْ دَعَا ‏ ‏النَّجَاشِيُّ ‏ ‏أَسَاقِفَتَهُ ‏ ‏فَنَشَرُوا مَصَاحِفَهُمْ حَوْلَهُ سَأَلَهُمْ فَقَالَ مَا هَذَا الدِّينُ الَّذِي فَارَقْتُمْ فِيهِ قَوْمَكُمْ وَلَمْ تَدْخُلُوا فِي دِينِي وَلَا فِي دِينِ أَحَدٍ مِنْ هَذِهِ الْأُمَمِ قَالَتْ فَكَانَ الَّذِي كَلَّمَهُ ‏ ‏جَعْفَرُ بْنُ أَبِي طَالِبٍ ‏ ‏فَقَالَ لَهُ أَيُّهَا الْمَلِكُ كُنَّا قَوْمًا أَهْلَ جَاهِلِيَّةٍ نَعْبُدُ الْأَصْنَامَ وَنَأْكُلُ الْمَيْتَةَ ‏ ‏وَنَأْتِي ‏ ‏الْفَوَاحِشَ ‏ ‏وَنَقْطَعُ ‏ ‏الْأَرْحَامَ ‏ ‏وَنُسِيءُ الْجِوَارَ يَأْكُلُ الْقَوِيُّ مِنَّا الضَّعِيفَ فَكُنَّا عَلَى ذَلِكَ حَتَّى ‏ ‏بَعَثَ اللَّهُ إِلَيْنَا رَسُولًا مِنَّا نَعْرِفُ نَسَبَهُ وَصِدْقَهُ وَأَمَانَتَهُ وَعَفَافَهُ فَدَعَانَا إِلَى اللَّهِ لِنُوَحِّدَهُ وَنَعْبُدَهُ وَنَخْلَعَ مَا كُنَّا نَعْبُدُ نَحْنُ وَآبَاؤُنَا مِنْ دُونِهِ مِنْ الْحِجَارَةِ وَالْأَوْثَانِ وَأَمَرَنَا بِصِدْقِ الْحَدِيثِ وَأَدَاءِ الْأَمَانَةِ وَصِلَةِ ‏ ‏الرَّحِمِ ‏ ‏وَحُسْنِ الْجِوَارِ وَالْكَفِّ عَنْ الْمَحَارِمِ وَالدِّمَاءِ وَنَهَانَا عَنْ ‏ ‏الْفَوَاحِشِ ‏ ‏وَقَوْلِ الزُّورِ وَأَكْلِ مَالَ الْيَتِيمِ ‏ ‏وَقَذْفِ ‏ ‏الْمُحْصَنَةِ ‏ ‏وَأَمَرَنَا أَنْ نَعْبُدَ اللَّهَ وَحْدَهُ لَا نُشْرِكُ بِهِ شَيْئًا وَأَمَرَنَا بِالصَّلَاةِ وَالزَّكَاةِ وَالصِّيَامِ قَالَ فَعَدَّدَ عَلَيْهِ أُمُورَ الْإِسْلَامِ فَصَدَّقْنَاهُ وَآمَنَّا بِهِ وَاتَّبَعْنَاهُ عَلَى مَا جَاءَ بِهِ فَعَبَدْنَا اللَّهَ وَحْدَهُ فَلَمْ نُشْرِكْ بِهِ شَيْئًا وَحَرَّمْنَا مَا حَرَّمَ عَلَيْنَا وَأَحْلَلْنَا مَا أَحَلَّ لَنَا فَعَدَا عَلَيْنَا قَوْمُنَا فَعَذَّبُونَا وَفَتَنُونَا عَنْ دِينِنَا لِيَرُدُّونَا إِلَى عِبَادَةِ الْأَوْثَانِ مِنْ عِبَادَةِ اللَّهِ وَأَنْ نَسْتَحِلَّ مَا كُنَّا نَسْتَحِلُّ مِنْ ‏ ‏الْخَبَائِثِ ‏ ‏فَلَمَّا قَهَرُونَا وَظَلَمُونَا وَشَقُّوا عَلَيْنَا وَحَالُوا بَيْنَنَا وَبَيْنَ دِينِنَا خَرَجْنَا إِلَى بَلَدِكَ وَاخْتَرْنَاكَ عَلَى مَنْ سِوَاكَ وَرَغِبْنَا فِي جِوَارِكَ وَرَجَوْنَا أَنْ لَا نُظْلَمَ عِنْدَكَ أَيُّهَا الْمَلِكُ قَالَتْ فَقَالَ لَهُ ‏ ‏النَّجَاشِيُّ ‏ ‏هَلْ مَعَكَ مِمَّا جَاءَ بِهِ عَنْ اللَّهِ مِنْ شَيْءٍ قَالَتْ ‏ ‏فَقَالَ لَهُ ‏ ‏جَعْفَرٌ ‏ ‏نَعَمْ فَقَالَ لَهُ ‏ ‏النَّجَاشِيُّ ‏ ‏فَاقْرَأْهُ عَلَيَّ فَقَرَأَ عَلَيْهِ ‏ ‏صَدْرًا ‏ ‏مِنْ ‏ ‏كهيعص ‏ ‏قَالَتْ فَبَكَى وَاللَّهِ ‏ ‏النَّجَاشِيُّ ‏ ‏حَتَّى ‏ ‏أَخْضَلَ ‏ ‏لِحْيَتَهُ وَبَكَتْ ‏ ‏أَسَاقِفَتُهُ ‏ ‏حَتَّى ‏ ‏أَخْضَلُوا ‏ ‏مَصَاحِفَهُمْ حِينَ سَمِعُوا مَا تَلَا عَلَيْهِمْ ثُمَّ قَالَ ‏ ‏النَّجَاشِيُّ ‏ ‏إِنَّ هَذَا وَاللَّهِ وَالَّذِي جَاءَ بِهِ ‏ ‏مُوسَى ‏ ‏لَيَخْرُجُ مِنْ ‏ ‏مِشْكَاةٍ ‏ ‏وَاحِدَةٍ انْطَلِقَا فَوَاللَّهِ لَا أُسْلِمُهُمْ إِلَيْكُمْ أَبَدًا وَلَا أُكَادُ قَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏فَلَمَّا خَرَجَا مِنْ عِنْدِهِ قَالَ ‏ ‏عَمْرُو بْنُ الْعَاصِ ‏ ‏وَاللَّهِ لَأُنَبِّئَنَّهُمْ غَدًا عَيْبَهُمْ عِنْدَهُمْ ثُمَّ أَسْتَأْصِلُ بِهِ خَضْرَاءَهُمْ قَالَتْ فَقَالَ لَهُ ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي رَبِيعَةَ ‏ ‏وَكَانَ أَتْقَى الرَّجُلَيْنِ فِينَا لَا تَفْعَلْ فَإِنَّ لَهُمْ أَرْحَامًا وَإِنْ كَانُوا قَدْ خَالَفُونَا قَالَ وَاللَّهِ لَأُخْبِرَنَّهُ أَنَّهُمْ يَزْعُمُونَ أَنَّ ‏ ‏عِيسَى ابْنَ مَرْيَمَ ‏ ‏عَبْدٌ قَالَتْ ثُمَّ غَدَا عَلَيْهِ الْغَدَ فَقَالَ لَهُ أَيُّهَا الْمَلِكُ إِنَّهُمْ يَقُولُونَ فِي ‏ ‏عِيسَى ابْنِ مَرْيَمَ ‏ ‏قَوْلًا عَظِيمًا فَأَرْسِلْ إِلَيْهِمْ فَاسْأَلْهُمْ عَمَّا يَقُولُونَ فِيهِ قَالَتْ فَأَرْسَلَ إِلَيْهِمْ يَسْأَلُهُمْ عَنْهُ قَالَتْ وَلَمْ يَنْزِلْ بِنَا مِثْلُهُ فَاجْتَمَعَ الْقَوْمُ فَقَالَ بَعْضُهُمْ لِبَعْضٍ مَاذَا تَقُولُونَ فِي ‏ ‏عِيسَى ‏ ‏إِذَا سَأَلَكُمْ عَنْهُ قَالُوا نَقُولُ وَاللَّهِ فِيهِ مَا قَالَ اللَّهُ وَمَا جَاءَ بِهِ نَبِيُّنَا كَائِنًا فِي ذَلِكَ مَا هُوَ كَائِنٌ فَلَمَّا دَخَلُوا عَلَيْهِ قَالَ لَهُمْ مَا تَقُولُونَ فِي ‏ ‏عِيسَى ابْنِ مَرْيَمَ ‏ ‏فَقَالَ لَهُ ‏ ‏جَعْفَرُ بْنُ أَبِي طَالِبٍ ‏ ‏نَقُولُ فِيهِ الَّذِي جَاءَ بِهِ نَبِيُّنَا هُوَ عَبْدُ اللَّهِ وَرَسُولُهُ وَرُوحُهُ وَكَلِمَتُهُ أَلْقَاهَا إِلَى ‏ ‏مَرْيَمَ ‏ ‏الْعَذْرَاءِ ‏ ‏الْبَتُولِ ‏ ‏قَالَتْ فَضَرَبَ ‏ ‏النَّجَاشِيُّ ‏ ‏يَدَهُ إِلَى الْأَرْضِ فَأَخَذَ مِنْهَا عُودًا ثُمَّ قَالَ مَا عَدَا ‏ ‏عِيسَى ابْنُ مَرْيَمَ ‏ ‏مَا قُلْتَ هَذَا الْعُودَ ‏ ‏فَتَنَاخَرَتْ ‏ ‏بَطَارِقَتُهُ ‏ ‏حَوْلَهُ حِينَ قَالَ مَا قَالَ فَقَالَ وَإِنْ ‏ ‏نَخَرْتُمْ ‏ ‏وَاللَّهِ اذْهَبُوا فَأَنْتُمْ ‏ ‏سُيُومٌ ‏ ‏بِأَرْضِي ‏ ‏وَالسُّيُومُ ‏ ‏الْآمِنُونَ ‏ ‏مَنْ سَبَّكُمْ ‏ ‏غُرِّمَ ‏ ‏ثُمَّ مَنْ سَبَّكُمْ ‏ ‏غُرِّمَ ‏ ‏فَمَا أُحِبُّ أَنَّ لِي دَبْرًا ذَهَبًا وَأَنِّي آذَيْتُ رَجُلًا مِنْكُمْ ‏ ‏وَالدَّبْرُ بِلِسَانِ ‏ ‏الْحَبَشَةِ ‏ ‏الْجَبَلُ ‏ ‏رُدُّوا عَلَيْهِمَا هَدَايَاهُمَا فَلَا حَاجَةَ لَنَا بِهَا فَوَاللَّهِ مَا أَخَذَ اللَّهُ مِنِّي الرِّشْوَةَ حِينَ رَدَّ عَلَيَّ مُلْكِي فَآخُذَ الرِّشْوَةَ فِيهِ وَمَا أَطَاعَ النَّاسَ فِيَّ فَأُطِيعَهُمْ فِيهِ قَالَتْ فَخَرَجَا مِنْ عِنْدِهِ ‏ ‏مَقْبُوحَيْنِ ‏ ‏مَرْدُودًا عَلَيْهِمَا مَا جَاءَا بِهِ وَأَقَمْنَا عِنْدَهُ بِخَيْرِ دَارٍ مَعَ خَيْرِ جَارٍ قَالَتْ فَوَاللَّهِ إِنَّا عَلَى ذَلِكَ إِذْ نَزَلَ بِهِ ‏ ‏يَعْنِي مَنْ يُنَازِعُهُ فِي مُلْكِهِ ‏ ‏قَالَ فَوَاللَّهِ مَا عَلِمْنَا حُزْنًا قَطُّ كَانَ أَشَدَّ مِنْ حُزْنٍ حَزِنَّاهُ عِنْدَ ذَلِكَ تَخَوُّفًا أَنْ يَظْهَرَ ذَلِكَ عَلَى ‏ ‏النَّجَاشِيِّ ‏ ‏فَيَأْتِيَ رَجُلٌ لَا يَعْرِفُ مِنْ حَقِّنَا مَا كَانَ ‏ ‏النَّجَاشِيُّ ‏ ‏يَعْرِفُ مِنْهُ قَالَتْ وَسَارَ ‏ ‏النَّجَاشِيُّ ‏ ‏وَبَيْنَهُمَا عُرْضُ النِّيلِ قَالَتْ فَقَالَ ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ رَجُلٌ يَخْرُجُ حَتَّى يَحْضُرَ ‏ ‏وَقْعَةَ ‏ ‏الْقَوْمِ ثُمَّ يَأْتِيَنَا بِالْخَبَرِ قَالَتْ فَقَالَ ‏ ‏الزُّبَيْرُ بْنُ الْعَوَّامِ ‏ ‏أَنَا قَالَتْ وَكَانَ مِنْ أَحْدَثِ الْقَوْمِ سِنًّا قَالَتْ فَنَفَخُوا لَهُ ‏ ‏قِرْبَةً ‏ ‏فَجَعَلَهَا فِي صَدْرِهِ ثُمَّ سَبَحَ عَلَيْهَا حَتَّى خَرَجَ إِلَى نَاحِيَةِ النِّيلِ الَّتِي بِهَا مُلْتَقَى الْقَوْمِ ثُمَّ انْطَلَقَ حَتَّى حَضَرَهُمْ قَالَتْ وَدَعَوْنَا اللَّهَ ‏ ‏لِلنَّجَاشِيِّ ‏ ‏بِالظُّهُورِ عَلَى عَدُوِّهِ وَالتَّمْكِينِ لَهُ فِي بِلَادِهِ وَاسْتَوْسَقَ عَلَيْهِ أَمْرُ ‏ ‏الْحَبَشَةِ ‏ ‏فَكُنَّا عِنْدَهُ فِي خَيْرِ مَنْزِلٍ حَتَّى قَدِمْنَا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏بِمَكَّةَ ‏","","",""],[1650,1650,"","আমরা তাদের বলেছিলাম, আমার বাবা ঈশ্বরের আবেগ নিয়ে কথা বলছেন, লাশের সাথে তাল মিলিয়ে খেতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْكُلُ ‏ ‏الْقِثَّاءَ ‏ ‏بِالرُّطَبِ ‏","","",""],[1651,1651,"","আমরা ঈশ্বরের দোহাইর কাছে সাক্ষ্যের ছেলেকে ভালোবাসার কথা বলেছিলাম, আমার ছেলে খোদা হয়তো থাকতে পারে। পাইলট মনে রাখবে যদি আমরা তার জন্য প্রার্থনা করি আর আমরা তাকে উদ্ধার করবো। আমরা আমাদের সেরাটা করেছি তোমাকে ছেড়ে দিতে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَنْبَأَنَا ‏ ‏حَبِيبُ بْنُ الشَّهِيدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي مُلَيْكَةَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ ‏ ‏لِابْنِ الزُّبَيْرِ ‏ ‏أَتَذْكُرُ إِذْ تَلَقَّيْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا وَأَنْتَ ‏ ‏وَابْنُ عَبَّاسٍ ‏ ‏فَقَالَ نَعَمْ قَالَ ‏ ‏فَحَمَلَنَا وَتَرَكَكَ ‏ ‏وَقَالَ ‏ ‏إِسْمَاعِيلُ ‏ ‏مَرَّةً أَتَذْكُرُ إِذْ تَلَقَّيْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا وَأَنْتَ ‏ ‏وَابْنُ عَبَّاسٍ ‏ ‏فَقَالَ نَعَمْ فَحَمَلَنَا وَتَرَكَكَ ‏","","",""],[1652,1652,"","বাবা কীভাবে মারা গিয়েছিলেন, সেই বিষয়ে কথা বলার চেষ্টা আমরা বাবা সম্বন্ধে কথা বলেছিলাম । গোপন ভাবে সে আমাকে তার নিজের ভাষায় ধরে রেখেছিল, তারপর আমার এক ছেলে এসে হাজির হল, সে পড়ে গিয়েছিল, নয়তো সে ভালো ছিল।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏مُوَرِّقٍ الْعِجْلِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَدِمَ مِنْ سَفَرٍ تُلُقِّيَ بِالصِّبْيَانِ مِنْ أَهْلِ بَيْتِهِ قَالَ ‏ ‏وَإِنَّهُ قَدِمَ مَرَّةً مِنْ سَفَرٍ قَالَ فَسُبِقَ بِي إِلَيْهِ قَالَ فَحَمَلَنِي بَيْنَ يَدَيْهِ قَالَ ثُمَّ جِيءَ بِأَحَدِ ابْنَيْ ‏ ‏فَاطِمَةَ ‏ ‏إِمَّا ‏ ‏حَسَنٍ ‏ ‏وَإِمَّا ‏ ‏حُسَيْنٍ ‏ ‏فَأَرْدَفَهُ ‏ ‏خَلْفَهُ قَالَ فَدَخَلْنَا ‏ ‏الْمَدِينَةَ ‏ ‏ثَلَاثَةً عَلَى دَابَّةٍ ‏","","",""],[1653,1653,"","আমরা কিভাবে একটি ফাঁদ সম্পর্কে কথা বলেছিলাম যে আমি মনে করি একটি গর্ভের কথা বলা হয়েছে, আমি মনে করি এটা বিশুদ্ধ যে তিনি হয়তো কোন ধরনের কথা বলতে পারেন বাচ্চাটি আর হয়তো তার কাছে যেতে পারে, ঈশ্বর তার কাছে প্রার্থনা করেছেন আর ঈশ্বরের কাছে প্রার্থনা করেছেন... বিকেল বেলা","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏حَدَّثَنِي ‏ ‏شَيْخٌ مِنْ ‏ ‏فَهْمٍ ‏ ‏قَالَ ‏ ‏وَأَظُنُّهُ يُسَمَّى ‏ ‏مُحَمَّدَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏وَأَظُنُّهُ حِجَازِيًّا ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ جَعْفَرٍ ‏ ‏يُحَدِّثُ ‏ ‏ابْنَ الزُّبَيْرِ ‏ ‏وَقَدْ نُحِرَتْ لِلْقَوْمِ جَزُورٌ أَوْ بَعِيرٌ أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْقَوْمُ يُلْقُونَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّحْمَ يَقُولُ ‏ ‏أَطْيَبُ اللَّحْمِ لَحْمُ الظَّهْرِ ‏","","",""],[1654,1654,"","বাবার চেয়ে অনেক ভালো কাজ করেছি আমার ছেলের ভালোর জন্য। আমরা আমার ছেলেকে খুন করার চেষ্টা করেছি। আমি তাকে কখনোই বলিনি যে আমি কখনোই ঈশ্বরের ইচ্ছার কাছে যাব না, যা আমি ভেঙ্গে ফেলেছি, যা হয়তো আমার কল্পনার দেয়াল, মৃত্যুর জন্য শপথ নিয়েছে। যখন সে দেখেছে, সে তাকে দেখে, তখন সে তাকে খুন করে। নবী তাঁর কাছে প্রার্থনা করে এবং তাঁর নাম দ্বারা তাকে উদ্ধার করে তিনি ঈশ্বরের কাছে পাঠান। তিনি আমাকে মেরে ফেলবেন।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏مَهْدِيُّ بْنُ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي يَعْقُوبَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مَهْدِيٌّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي يَعْقُوبَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏مَوْلَى ‏ ‏الْحَسَنِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏أَرْدَفَنِي ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ خَلْفَهُ فَأَسَرَّ إِلَيَّ حَدِيثًا لَا أُخْبِرُ بِهِ أَحَدًا أَبَدًا وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَبُّ مَا اسْتَتَرَ بِهِ فِي حَاجَتِهِ ‏ ‏هَدَفٌ ‏ ‏أَوْ ‏ ‏حَائِشُ ‏ ‏نَخْلٍ فَدَخَلَ يَوْمًا ‏ ‏حَائِطًا ‏ ‏مِنْ ‏ ‏حِيطَانِ ‏ ‏الْأَنْصَارِ ‏ ‏فَإِذَا جَمَلٌ قَدْ أَتَاهُ فَجَرْجَرَ وَذَرَفَتْ عَيْنَاهُ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏فَلَمَّا رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَنَّ وَذَرَفَتْ عَيْنَاهُ ‏ ‏فَمَسَحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَرَاتَهُ ‏ ‏وَذِفْرَاهُ ‏ ‏فَسَكَنَ فَقَالَ ‏ ‏مَنْ صَاحِبُ الْجَمَلِ فَجَاءَ فَتًى مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ هُوَ لِي يَا رَسُولَ اللَّهِ فَقَالَ أَمَا تَتَّقِي اللَّهَ فِي هَذِهِ الْبَهِيمَةِ الَّتِي مَلَّكَكَهَا اللَّهُ إِنَّهُ شَكَا إِلَيَّ أَنَّكَ تُجِيعُهُ ‏ ‏وَتُدْئِبُهُ ‏","","",""],[1655,1655,"","আমরা একটি স্বপ্নের মাধ্যমে বাপ্তিস্ম নিয়েছি, তিনি আমার পিতার পুত্র হিসেবে দেখা, তার ন্যায্য পুত্র হিসেবে ব্যবহৃত. তিনি ঈশ্বরের শক্তিশালী আবেগ তার ডান এবং তিনি বলেন ঈশ্বর একটি সৃষ্টি করতে পারে. তিনি মনে হয় তিনি একটি মহান মহান মহান মহান মহান মহান মহান পিতা হতে পারে. তিনি একটি সৃষ্টি করেছি. তিনি একটি পিতা হতে পারে যে তিনি একটি মহান মহান মহান মহান মহান মহান পিতা হতে পারে, এবং তিনি একটি পিতা হতে পারে, তিনি একটি মহান পিতা হতে পারে যে তিনি একটি পিতা একটি পিতা হতে পারে, তিনি একটি সৃষ্টি করেছি, তিনি একটি মহান মহান পিতা হতে পারে, তিনি একটি পিতা, তিনি একটি পিতা হতে পারে, তিনি একটি মহান মহান মহান মহান পিতা হতে পারে, এবং তিনি একটি পিতা হতে পারে. তিনি একটি পিতা, তিনি একটি পিতা, তিনি একটি মহান মহান মহান পিতা হতে পারে, এবং তিনি একটি পিতা, তিনি একটি পিতা, তিনি একটি মহান পিতা হতে পারে, এবং তিনি একটি মহান মহান মহান মহান মহান পিতা হতে পারে, এবং তিনি একটি পিতা হতে পারে. পার্থক্য, তাকে তার ডান দিকে বেছে নেয়া হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏ابْنَ أَبِي رَافِعٍ ‏ ‏يَتَخَتَّمُ فِي يَمِينِهِ فَسَأَلْتُهُ عَنْ ذَلِكَ فَذَكَرَ أَنَّهُ رَأَى ‏ ‏عَبْدَ اللَّهِ بْنَ جَعْفَرٍ ‏ ‏يَتَخَتَّمُ فِي يَمِينِهِ وَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَخَتَّمُ فِي يَمِينِهِ ‏","","",""],[1656,1656,"","আমরা তার ভয়ের সাথে ঝামেলা নিয়ে কথা বলেছিলাম, সে লর্ডের কাছে প্রার্থনা করছিল এবং জিজ্ঞেস করলো সে কে।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ مُسَافِعٍ ‏ ‏أَنَّ ‏ ‏مُصْعَبَ بْنَ شَيْبَةَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عُقْبَةَ بْنِ مُحَمَّدِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ شَكَّ فِي صَلَاتِهِ فَلْيَسْجُدْ سَجْدَتَيْنِ وَهُوَ جَالِسٌ ‏","","",""],[1657,1657,"","আমরা বাবার কথা বলেছি একটি ছেলে পাওয়ার চেষ্টা করছে. একটি কুকুর বলেছে যে তিনি আমার কথা শুনবেন ঈশ্বরের নামে. সে এটা আত্মসমর্পণ করতে চেয়েছিল, ঈশ্বর তোমার জন্য দোয়া করছেন।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏وَيَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَسْوَدِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُبَيْدَ بْنَ أُمِّ كِلَابٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ جَعْفَرٍ ‏ ‏قَالَ أَحَدُهُمَا ذِي الْجَنَاحَيْنِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا عَطَسَ حَمِدَ اللَّهَ فَيُقَالُ لَهُ يَرْحَمُكَ اللَّهُ فَيَقُولُ ‏ ‏يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ ‏","","",""],[1658,1658,"","আমরা আলোচনা করেছিলাম যে, ঈশ্বর তাঁর পাপের একটা ও শেষ কয়েক জনের মধ্যে থেকে একটা পাপ উদ্ধার করতে চান ।","‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ بَابٍ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ آخِرَ مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي إِحْدَى يَدَيْهِ رُطَبَاتٌ وَفِي الْأُخْرَى ‏ ‏قِثَّاءٌ ‏ ‏وَهُوَ يَأْكُلُ مِنْ هَذِهِ وَيَعَضُّ مِنْ هَذِهِ وَقَالَ ‏ ‏إِنَّ أَطْيَبَ الشَّاةِ لَحْمُ الظَّهْرِ ‏","","",""],[1659,1659,"","আমরা আমার বাবার কথা বলেছিলাম যে তিনি সূর্য সম্পর্কে জানতে চান, একটি আবেগ দিয়ে তিনি বলেছিলেন তিনি ঈশ্বরের কাছে আসবেন একটি মৃত স্বপ্নের সাথে করবেন। একজন মৃত মানুষকে হত্যা করা হয়েছে, তারপর সে পতাকা তুলে নেয়... ...আর তারপর সে এটা নিয়ে নেয়. ঈশ্বর পাপ করেছেন এবং বলেছিলেন যে, আপনার ভাইয়েরা শত্রুকে সেবা করেছে এবং এরপর পতাকা তুলে নিয়েছে । সাক্ষী, তারপর আমি পতাকাটি তুলে নেই, তারপর সাক্ষী হিসেবে শপথ নেই, পতাকাটি নিয়ে নাও, ঈশ্বরের পুত্রের জন্মের জন্য ঈশ্বরের যন্ত্রণা হবে। এবং আমি বুঝতে পারছি যে, তারা আমাকে ছেড়ে দেবে না। ভাই মনে করেন যে দিন বা কাল তারা আমার বাবা হওয়ার ভান করে। তারা আমাকে বারবারশপ বলে, সে এটা নিয়ে হল হলে ধরা পড়ে, সে আমাকে মেরে ফেলতে চায়। তারপর আমাকে মেরে ফেলতে হবে এবং খুন করতে হবে। একবার সে বলেছিল যে, আমরা তার ইচ্ছা নিয়ে চিন্তা করতে এবং তাকে ব্যাখ্যা করতে নিরাপদ আছি ।","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ أَبِي يَعْقُوبَ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَيْشًا اسْتَعْمَلَ عَلَيْهِمْ ‏ ‏زَيْدَ بْنَ حَارِثَةَ ‏ ‏وَقَالَ فَإِنْ قُتِلَ ‏ ‏زَيْدٌ ‏ ‏أَوْ اسْتُشْهِدَ ‏ ‏فَأَمِيرُكُمْ ‏ ‏جَعْفَرٌ ‏ ‏فَإِنْ قُتِلَ أَوْ اسْتُشْهِدَ فَأَمِيرُكُمْ ‏ ‏عَبْدُ اللَّهِ بْنُ رَوَاحَةَ ‏ ‏فَلَقُوا الْعَدُوَّ فَأَخَذَ الرَّايَةَ ‏ ‏زَيْدٌ ‏ ‏فَقَاتَلَ حَتَّى قُتِلَ ثُمَّ أَخَذَ الرَّايَةَ ‏ ‏جَعْفَرٌ ‏ ‏فَقَاتَلَ حَتَّى قُتِلَ ثُمَّ أَخَذَهَا ‏ ‏عَبْدُ اللَّهِ بْنُ رَوَاحَةَ ‏ ‏فَقَاتَلَ حَتَّى قُتِلَ ثُمَّ أَخَذَ الرَّايَةَ ‏ ‏خَالِدُ بْنُ الْوَلِيدِ ‏ ‏فَفَتَحَ اللَّهُ عَلَيْهِ وَأَتَى خَبَرُهُمْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَرَجَ إِلَى النَّاسِ فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ وَقَالَ ‏ ‏إِنَّ إِخْوَانَكُمْ لَقُوا الْعَدُوَّ وَإِنَّ ‏ ‏زَيْدًا ‏ ‏أَخَذَ الرَّايَةَ فَقَاتَلَ حَتَّى قُتِلَ ‏ ‏أَوْ اسْتُشْهِدَ ‏ ‏ثُمَّ أَخَذَ الرَّايَةَ بَعْدَهُ ‏ ‏جَعْفَرُ بْنُ أَبِي طَالِبٍ ‏ ‏فَقَاتَلَ حَتَّى قُتِلَ ‏ ‏أَوْ اسْتُشْهِدَ ‏ ‏ثُمَّ أَخَذَ الرَّايَةَ ‏ ‏عَبْدُ اللَّهِ بْنُ رَوَاحَةَ ‏ ‏فَقَاتَلَ حَتَّى قُتِلَ ‏ ‏أَوْ اسْتُشْهِدَ ‏ ‏ثُمَّ أَخَذَ الرَّايَةَ سَيْفٌ مِنْ سُيُوفِ اللَّهِ ‏ ‏خَالِدُ بْنُ الْوَلِيدِ ‏ ‏فَفَتَحَ اللَّهُ عَلَيْهِ فَأَمْهَلَ ثُمَّ أَمْهَلَ آلَ ‏ ‏جَعْفَرٍ ‏ ‏ثَلَاثًا أَنْ يَأْتِيَهُمْ ثُمَّ أَتَاهُمْ فَقَالَ لَا تَبْكُوا عَلَى أَخِي بَعْدَ الْيَوْمِ أَوْ غَدٍ ادْعُوا لِي ابْنَيْ أَخِي قَالَ فَجِيءَ بِنَا كَأَنَّا أَفْرُخٌ فَقَالَ ادْعُوا إِلَيَّ الْحَلَّاقَ فَجِيءَ بِالْحَلَّاقِ فَحَلَقَ رُءُوسَنَا ثُمَّ قَالَ أَمَّا ‏ ‏مُحَمَّدٌ ‏ ‏فَشَبِيهُ عَمِّنَا ‏ ‏أَبِي طَالِبٍ ‏ ‏وَأَمَّا ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَشَبِيهُ خَلْقِي وَخُلُقِي ثُمَّ أَخَذَ بِيَدِي فَأَشَالَهَا فَقَالَ اللَّهُمَّ اخْلُفْ ‏ ‏جَعْفَرًا ‏ ‏فِي أَهْلِهِ وَبَارِكْ ‏ ‏لِعَبْدِ اللَّهِ ‏ ‏فِي صَفْقَةِ يَمِينِهِ قَالَهَا ثَلَاثَ مِرَارٍ قَالَ فَجَاءَتْ أُمُّنَا فَذَكَرَتْ لَهُ يُتْمَنَا وَجَعَلَتْ تُفْرِحُ لَهُ فَقَالَ الْعَيْلَةَ تَخَافِينَ عَلَيْهِمْ وَأَنَا وَلِيُّهُمْ فِي الدُّنْيَا وَالْآخِرَةِ ‏","","",""],[1660,1660,"","আমরা দুই বছর ধরে আমার বাবাকে ঈশ্বরের কাছ থেকে একটি পছন্দ করার চেষ্টা করেছি, একটি হিংস্র রাগের মাধ্যমে। মজা করলাম।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏لَمَّا جَاءَ نَعْيُ ‏ ‏جَعْفَرٍ ‏ ‏حِينَ قُتِلَ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اصْنَعُوا لِآلِ ‏ ‏جَعْفَرٍ ‏ ‏طَعَامًا فَقَدْ أَتَاهُمْ أَمْرٌ يَشْغَلُهُمْ ‏ ‏أَوْ أَتَاهُمْ مَا يَشْغَلُهُمْ ‏","","",""],[1661,1661,"","আমরা একটা কাপুরুষ ছেলের কথা বলেছি যে ঈশ্বর হয়ত তার নিজের একটা কুত্তা। সে এটা নিয়ে কথা বলার জন্য ২ দিন চেষ্টা করছে। আমরা একটা ছেলের উপর নজর রাখার পর তোমাকে খুজে পেয়েছি যে কিনা টেনেছে। কিন্তু, অবাক হওয়ার মতো বিষয় হল, একজন খুনীর এক নির্দিষ্ট সন্তানের জন্য শাস্তি নিয়ে আসা।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ مُسَافِعٍ ‏ ‏أَنَّ ‏ ‏مُصْعَبَ بْنَ شَيْبَةَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عُقْبَةَ بْنِ مُحَمَّدِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ شَكَّ فِي صَلَاتِهِ فَلْيَسْجُدْ سَجْدَتَيْنِ بَعْدَمَا يُسَلِّمُ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَنْبَأَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُسَافِعٍ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ مُحَمَّدِ بْنِ الْحَارِثِ ‏ ‏فَذَكَرَ مِثْلَهُ بِإِسْنَادِهِ ‏","","",""],[1662,1662,"","আমি আমার বাবার কথা বলেছিলাম যে তিনি সূর্য সম্পর্কে জানতে চান। তিনি তার জীবন দিয়ে ঈশ্বরের কাছে ফিরে আসবেন। যদি তুমি জয় করতে চাও, আমি চাই তুমি যা পরে আছ, আমি তাই করি। একটা আঘাত কাজ অথবা ফাঁদ, সে বড় হয়ে উঠে যখন ভাববাদীর কাছে প্রার্থনা করে... গুলি করার কিছুক্ষণ পরেই মারা গেল, আর এই পবিত্র স্থানে, সন্দেহ করা হচ্ছে যে তুমি অনেক ক্ষেপে যাবে, আলো চলে আসবে আর সে চলে যাবে, এটাই আমাদের একমাত্র প্রবৃত্তি... ...আমরা তাকে হত্যা করেছি, তাকে ব্যর্থ হতে না দেয়া।","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ أَبِي يَعْقُوبَ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏رَكِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَغْلَتَهُ ‏ ‏وَأَرْدَفَنِي ‏ ‏خَلْفَهُ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَبَرَّزَ كَانَ أَحَبَّ مَا تَبَرَّزَ فِيهِ ‏ ‏هَدَفٌ ‏ ‏يَسْتَتِرُ بِهِ أَوْ ‏ ‏حَائِشُ ‏ ‏نَخْلٍ فَدَخَلَ حَائِطًا لِرَجُلٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَإِذَا فِيهِ ‏ ‏نَاضِحٌ ‏ ‏لَهُ فَلَمَّا رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَنَّ ‏ ‏وَذَرَفَتْ ‏ ‏عَيْنَاهُ فَنَزَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَسَحَ ‏ ‏ذِفْرَاهُ ‏ ‏وَسَرَاتَهُ فَسَكَنَ فَقَالَ مَنْ رَبُّ هَذَا الْجَمَلِ فَجَاءَ شَابٌّ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ أَنَا فَقَالَ ‏ ‏أَلَا تَتَّقِي اللَّهَ فِي هَذِهِ الْبَهِيمَةِ الَّتِي مَلَّكَكَ اللَّهُ إِيَّاهَا فَإِنَّهُ شَكَاكَ إِلَيَّ وَزَعَمَ أَنَّكَ تُجِيعُهُ ‏ ‏وَتُدْئِبُهُ ‏ ‏ثُمَّ ذَهَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْحَائِطِ ‏ ‏فَقَضَى حَاجَتَهُ ثُمَّ تَوَضَّأَ ثُمَّ جَاءَ وَالْمَاءُ يَقْطُرُ مِنْ لِحْيَتِهِ عَلَى صَدْرِهِ فَأَسَرَّ إِلَيَّ شَيْئًا لَا أُحَدِّثُ بِهِ أَحَدًا فَحَرَّجْنَا عَلَيْهِ أَنْ يُحَدِّثَنَا فَقَالَ لَا ‏ ‏أُفْشِي عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سِرَّهُ حَتَّى أَلْقَى اللَّهَ ‏","","",""],[1663,1663,"","আমরা বাবার ছেলের কথা বলেছিলাম যে ঈশ্বর আমাকে স্পর্শ করার চেষ্টা করছেন। আল্লাহ্‌ তার ডানের শোকের কারণে, তিনি ঈশ্বরের দ্বারা বড় হয়েছেন, তিনি ছিলেন এবং তিনি তার নিজেরই ছিল।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي رَافِعٍ ‏ ‏مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ جَعْفَرٍ ‏ ‏كَانَ يَتَخَتَّمُ فِي يَمِينِهِ وَزَعَمَ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتَخَتَّمُ فِي يَمِينِهِ ‏","","",""],[1664,1664,"","ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং তার জন্য প্রার্থনা করেছিলেন । তারা বলল, এগুলো বাদ দাও।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شَيْخٌ ‏ ‏قَدِمَ عَلَيْنَا مِنْ ‏ ‏الْحِجَازِ ‏ ‏قَالَ ‏ ‏شَهِدْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ الزُّبَيْرِ ‏ ‏وَعَبْدَ اللَّهِ بْنَ جَعْفَرٍ ‏ ‏بِالْمُزْدَلِفَةِ ‏ ‏فَكَانَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏يَحُزُّ ‏ ‏اللَّحْمَ ‏ ‏لِعَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَطْيَبُ اللَّحْمِ لَحْمُ الظَّهْرِ ‏","","",""],[1665,1665,"","আমরা রাজার হিজাব রক্ষা করার চেষ্টা করেছি... ...আমরা একটা অদ্ভুত জায়গায় আটকে থাকার স্বপ্ন রক্ষা করার জন্য. ঈশ্বর আমাকে বলেছেন, আমার প্রভু এটা করেছেন। কে বলবে আমার বাবা মাফের পর কে যেন বলবে আর আমরা তার মতো ছেলের সাথে কথা বলেছি।","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أَبِي حَكِيمٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يَنْبَغِي لِنَبِيٍّ أَنْ يَقُولَ إِنِّي خَيْرٌ مِنْ ‏ ‏يُونُسَ بْنِ مَتَّى ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏و حَدَّثَنَاه ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏مِثْلَهُ ‏","","",""],[1666,1666,"","আমরা আমার বাবার সাথে কথা বলেছিলাম যে সে নগ্ন ছিল। ঈশ্বর হয়তো আমার বাবার সাথে এমন একজন ছাত্রের সাথে প্রেম করেছেন যিনি ঈশ্বরের দোহাই প্রার্থনা করতে বলেছেন এবং আমাকে উদ্ধার করতে বলেছেন। শীঘ্রই আমি তার দিকে গুলি করব না, আমরা নই।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ فَحَدَّثَنِي ‏ ‏هِشَامُ بْنُ عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَعْفَرِ بْنِ أَبِي طَالِبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُمِرْتُ أَنْ أُبَشِّرَ ‏ ‏خَدِيجَةَ ‏ ‏بِبَيْتٍ مِنْ قَصَبٍ لَا ‏ ‏صَخَبَ ‏ ‏فِيهِ وَلَا نَصَبَ ‏","","",""],[1667,1667,"","আমরা আল্লাহ্‌র কথা বলেছি, আমি আল্লাহ্‌র কথা শুনেছি। কিন্তু ঈশ্বর আমাকে সাহায্য করেছেন এটা করতে। ঈশ্বর এটা করেছেন এবং তাকে আত্মসমর্পণ করেছেন। বিকেলেই রক্ষা করো।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏مِنْ ‏ ‏فَهْمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِلَحْمٍ فَجَعَلَ الْقَوْمُ يُلَقُّونَهُ اللَّحْمَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَطْيَبَ اللَّحْمِ لَحْمُ الظَّهْرِ ‏","","",""],[1668,1668,"","আমরা একটা পিপপির ছেলে থাকার কথা বলেছিলাম, যে আমাকে একটা ছেলে খুঁজতে বলেছিল যে তার একটা মেয়ে আছে যার একটা মেয়ে আছে যে মেয়ে তার মেয়ে মেয়ে হয়েছে তার একটা মেয়ে আছে যার একটা মেয়ে আছে যে মেয়ে মেয়ে আছে, যে তার মেয়ে আছে, যার একটা মেয়ে আছে। যে মেয়ের একটা ছেলে ছিল, যে তার ছেলে ছিল, সে আমাকে বলেছিল, সে আমাকে দেখে ঈশ্বরকে দেখে কিনা, আর আমরা ছেলে, আর আমরা ছেলে, আর সে আমাকে দিয়ে যেতে হবে। তিনি আমাকে একটা সুযোগ দেবেন। যুদ্ধ, সে আমাকে খুন করেছে, আমি কিছু জিনিস শেয়ার করতে চাই, তারপর সে একটা টাকা বহন করতে পারবে এবং তারপর একটা সুযোগ পাবে। যখনই অন্যগুলো তার নিজের হাতে ভোজের অনুমতি থাকে। আমি ঈশ্বরের কাছে যেতে বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏جَعْفَرُ بْنُ خَالِدِ ابْنِ سَارَّةَ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏لَوْ رَأَيْتَنِي ‏ ‏وَقُثَمَ ‏ ‏وَعُبَيْدَ اللَّهِ ‏ ‏ابْنَيْ ‏ ‏عَبَّاسٍ ‏ ‏وَنَحْنُ صِبْيَانٌ نَلْعَبُ إِذْ مَرَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى دَابَّةٍ فَقَالَ ارْفَعُوا هَذَا إِلَيَّ قَالَ فَحَمَلَنِي أَمَامَهُ وَقَالَ ‏ ‏لِقُثَمَ ‏ ‏ارْفَعُوا هَذَا إِلَيَّ فَجَعَلَهُ وَرَاءَهُ وَكَانَ ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏أَحَبَّ إِلَى ‏ ‏عَبَّاسٍ ‏ ‏مِنْ ‏ ‏قُثَمَ ‏ ‏فَمَا اسْتَحَى مِنْ عَمِّهِ أَنْ حَمَلَ ‏ ‏قُثَمًا ‏ ‏وَتَرَكَهُ قَالَ ثُمَّ ‏ ‏مَسَحَ عَلَى رَأْسِي ثَلَاثًا وَقَالَ كُلَّمَا مَسَحَ اللَّهُمَّ اخْلُفْ ‏ ‏جَعْفَرًا ‏ ‏فِي وَلَدِهِ قَالَ قُلْتُ ‏ ‏لِعَبْدِ اللَّهِ ‏ ‏مَا فَعَلَ ‏ ‏قُثَمُ ‏ ‏قَالَ اسْتُشْهِدَ قَالَ قُلْتُ اللَّهُ أَعْلَمُ بِالْخَيْرِ وَرَسُولُهُ بِالْخَيْرِ قَالَ أَجَلْ ‏","","",""],[1669,1669,"","আমরা কথা বলেছিলাম যে একটা পিপপি ছেলে আমাকে বলেছিল যে খোদা একটা কুত্তা হতে পারে, সে তার নিজের তৈরি করা ঈশ্বরের দোহাইর ব্যাপারে জানতে চাচ্ছে। পৌঁছে গেছি।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ مُسَافِعٍ ‏ ‏أَنَّ ‏ ‏مُصْعَبَ بْنَ شَيْبَةَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عُقْبَةَ بْنِ مُحَمَّدِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ شَكَّ فِي صَلَاتِهِ فَلْيَسْجُدْ سَجْدَتَيْنِ بَعْدَمَا يُسَلِّمُ ‏","","",""],[1670,1670,"","আমরা সেই বধির ব্যক্তিদের সম্বন্ধে কথা বলেছিলাম, যাদের সঙ্গে আমার বাবা ছেলে হতে পারে । তার প্রভু আছে, যিনি ঈশ্বরের কাছে তার প্রভুর সেবা করেছেন এবং আত্মসমর্পণ করেছেন। আমি বললাম তিনি তাকে ফোন করেননি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏أَنَّهُ زَوَّجَ ابْنَتَهُ مِنْ ‏ ‏الْحَجَّاجِ بْنِ يُوسُفَ ‏ ‏فَقَالَ لَهَا إِذَا دَخَلَ بِكِ فَقُولِي ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ الْحَلِيمُ الْكَرِيمُ سُبْحَانَ اللَّهِ رَبِّ الْعَرْشِ الْعَظِيمِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ وَزَعَمَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا ‏ ‏حَزَبَهُ ‏ ‏أَمْرٌ قَالَ هَذَا ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏ظَنَنْتُ أَنَّهُ قَالَ فَلَمْ يَصِلْ إِلَيْهَا ‏","","",""],[1671,1671,"","আমরা কিছু সময় কথা বলেছি যে সাগর থেকে তোমার চাচাকে পাওয়া যাবে কিনা তা নিয়ে... আমি আগুনের ঘরে ছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنِ ‏ ‏الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏عَمُّكَ ‏ ‏أَبُو طَالِبٍ ‏ ‏كَانَ ‏ ‏يَحُوطُكَ ‏ ‏وَيَنْفَعُكَ ‏ ‏قَالَ إِنَّهُ فِي ‏ ‏ضَحْضَاحٍ ‏ ‏مِنْ النَّارِ وَلَوْلَا أَنَا كَانَ فِي ‏ ‏الدَّرْكِ ‏ ‏الْأَسْفَلِ مِنْ النَّارِ ‏","","",""],[1672,1672,"","লোকেরা ঈশ্বরের কাছে প্রার্থনা করেছিল আর তিনি সেই ব্যক্তিকে খুঁজে পেয়েছিলেন । আমরা তাকে ঈশ্বরের উদ্ধার করার জন্য পরিচালিত করেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏عَنِ ‏ ‏الْعَبَّاسِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَجَدَ الرَّجُلُ سَجَدَ مَعَهُ سَبْعَةُ ‏ ‏آرَابٍ ‏ ‏وَجْهِهِ وَكَفَّيْهِ وَرُكْبَتَيْهِ وَقَدَمَيْهِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏عَنِ ‏ ‏الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏","","",""],[1673,1673,"","আমার বাবার সাথে এত ছোট হওয়া নিয়ে কথা বলেছিলাম, আমার কিছু ঋতুতে মানুষের ছেলে আছে। সে বলেছিল, সে আমার ভালোবাসা শুনতে পেয়েছে। ঈশ্বর তার জন্য প্রার্থনা করেছেন। আর তার বাবার রক্ত, আমার বাবার রক্ত, আমার বাবা, আমার ভালোবাসা, আর তার মায়ের জন্য। আমি আমার বাবার সাথে কথা বলেছি। আমি আমার বাবার সাথে তোমার সম্পর্কটা নিয়ে কথা বলেছি। আমি যদি তুমি জানো, তুমি জানো, তুমি জানো, তুমি জানো, তুমি জানো না যে, তুমি আমাকে কি করবে। আমি তোমার কথা বলতে চাই না। আমি তোমার কথা বলি, আমি তোমার কথা বলি, আমি তোমার কথা বলছি, আমি তোমার কাছে নেই। আমি তোমার কাছে এটা একটা ছোট। আর তোমার জন্য একটা প্রশ্ন করি। ঈশ্বর আপনাকে উদ্ধার করবেন, প্রভু ঈশ্বর। এমন কিছু যা আমি করতে যাচ্ছি, \"হে আমার চাচা, আমি তোমার জন্য গান গাইব না, এমন কিছু যা হয়তো ভালো হবে।\" আর একজন বলে যে, আমি কিছু একটা করেছি বলে যাব। যাজকরা একজন খুনি, আমার বাবা একজন মানুষ। আমার জন্ম, সে তার বাবার পিপাসার বিষয়ে কথা শুনে তার মন হারিয়ে ফেলেছিল। আমি ঈশ্বরের কাছে ভিক্ষা চাইছি, প্রভু, আমি তোমার চাচার বড় হয়েছি। তার বয়স অনেক বেশি.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏حَاتِمٌ يَعْنِي ابْنَ أَبِي صَغِيرَةَ ‏ ‏حَدَّثَنِي ‏ ‏بَعْضُ ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏قَالَ ‏ ‏قَدِمَ عَلَيْنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏فِي بَعْضِ تِلْكَ الْمَوَاسِمِ ‏ ‏قَالَ فَسَمِعْتُهُ يَقُولُ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَبْدُ اللَّهِ بْنُ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏الْعَبَّاسِ ‏ ‏أَنَّهُ أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَنَا عَمُّكَ كَبِرَتْ سِنِّي وَاقْتَرَبَ أَجَلِي فَعَلِّمْنِي شَيْئًا يَنْفَعُنِي اللَّهُ بِهِ قَالَ يَا ‏ ‏عَبَّاسُ ‏ ‏أَنْتَ عَمِّي وَلَا ‏ ‏أُغْنِي عَنْكَ مِنْ اللَّهِ شَيْئًا وَلَكِنْ ‏ ‏سَلْ رَبَّكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ قَالَهَا ثَلَاثًا ثُمَّ أَتَاهُ عِنْدَ ‏ ‏قَرْنِ ‏ ‏الْحَوْلِ ‏ ‏فَقَالَ لَهُ مِثْلَ ذَلِكَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو يُونُسَ الْقُشَيْرِيُّ حَاتِمُ بْنُ أَبِي صَغِيرَةَ ‏ ‏حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏مِنْ وَلَدِ ‏ ‏عَبْدِ الْمُطَّلِبِ ‏ ‏قَالَ ‏ ‏قَدِمَ عَلَيْنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏فَحَضَرَهُ ‏ ‏بَنُو عَبْدِ الْمُطَّلِبِ ‏ ‏فَقَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبَّاسٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ فَقُلْتُ يَا رَسُولَ اللَّهِ أَنَا عَمُّكَ قَدْ كَبِرَتْ سِنِّي ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[1674,1674,"","আমরা বাবার সাথে যুদ্ধের ব্যাপারে কথা বলেছিলাম, হয়তো তুমি তোমার হৃদয়ের জন্য অনেক কিছু করেছ, সে আগুনের পাশে আছে আর তুমি যদি আগুনের ঘরে ছিলে,","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ نَوْفَلٍ ‏ ‏عَنْ ‏ ‏عَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏هَلْ نَفَعْتَ ‏ ‏أَبَا طَالِبٍ ‏ ‏بِشَيْءٍ فَإِنَّهُ كَانَ ‏ ‏يَحُوطُكَ ‏ ‏وَيَغْضَبُ لَكَ قَالَ نَعَمْ هُوَ فِي ‏ ‏ضَحْضَاحٍ ‏ ‏مِنْ النَّارِ وَلَوْلَا ذَلِكَ لَكَانَ فِي ‏ ‏الدَّرْكِ ‏ ‏الْأَسْفَلِ مِنْ النَّارِ ‏","","",""],[1675,1675,"","আমরা ইশ্বরের সেরা জয়ের চেষ্টা করেছি। তাকে নিয়ে যাও আর গাড়ি চালাও।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏عَنِ ‏ ‏الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَجَدَ ابْنُ ‏ ‏آدَمَ ‏ ‏سَجَدَ مَعَهُ سَبْعَةُ آرَابٍ وَجْهِهِ وَكَفَّيْهِ وَرُكْبَتَيْهِ وَقَدَمَيْهِ ‏","","",""],[1676,1676,"","আমরা পৃথিবীর সেরাদের কথা বলেছি, ঈশ্বর এমন এক ইট তৈরী করেছেন যার জন্য বলা হয়েছে আমরা প্রভুর বার্তাবাহকের সাথে বসে আছি। প্রভু, আমি তাকে সরিয়ে দিব, সে আমাদের মেরে ফেলবে, কারণ সে বলেছে আমি তাকে কত বছর হারিয়ে ফেলেছি। সে মিথ্যা কথা বলতে পারে, তারপর সে খুশি হবে। আর তারপর তুমি আকাশকে যেভাবে দেখবে আর তাকে জিজ্ঞেস করবে, আমার ছেলের সাথে আমার কিছু করার আছে। সে যা করেছে তা করার পরে শিকারীদের সাথে, সে মারা যাচ্ছে, আমার বাবার ছেলে... ...ঈশ্বরকে ভালোবাসে...","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏يَحْيَى بْنُ الْعَلَاءِ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏شُعَيْبِ بْنِ خَالِدٍ ‏ ‏حَدَّثَنِي ‏ ‏سِمَاكُ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمِيرَةَ ‏ ‏عَنْ ‏ ‏عَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْبَطْحَاءِ ‏ ‏فَمَرَّتْ سَحَابَةٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَدْرُونَ مَا هَذَا قَالَ قُلْنَا السَّحَابُ قَالَ ‏ ‏وَالْمُزْنُ ‏ ‏قُلْنَا ‏ ‏وَالْمُزْنُ ‏ ‏قَالَ ‏ ‏وَالْعَنَانُ ‏ ‏قَالَ فَسَكَتْنَا فَقَالَ هَلْ تَدْرُونَ كَمْ بَيْنَ السَّمَاءِ وَالْأَرْضِ قَالَ قُلْنَا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ بَيْنَهُمَا مَسِيرَةُ خَمْسِ مِائَةِ سَنَةٍ وَمِنْ كُلِّ سَمَاءٍ إِلَى سَمَاءٍ مَسِيرَةُ خَمْسِ مِائَةِ سَنَةٍ ‏ ‏وَكِثَفُ ‏ ‏كُلِّ سَمَاءٍ مَسِيرَةُ خَمْسِ مِائَةِ سَنَةٍ وَفَوْقَ السَّمَاءِ السَّابِعَةِ بَحْرٌ بَيْنَ أَسْفَلِهِ وَأَعْلَاهُ كَمَا بَيْنَ السَّمَاءِ وَالْأَرْضِ ثُمَّ فَوْقَ ذَلِكَ ثَمَانِيَةُ أَوْعَالٍ ‏ ‏بَيْنَ رُكَبِهِنَّ وَأَظْلَافِهِنَّ كَمَا بَيْنَ السَّمَاءِ وَالْأَرْضِ ثُمَّ فَوْقَ ذَلِكَ الْعَرْشُ بَيْنَ أَسْفَلِهِ وَأَعْلَاهُ كَمَا بَيْنَ السَّمَاءِ وَالْأَرْضِ وَاللَّهُ تَبَارَكَ وَتَعَالَى فَوْقَ ذَلِكَ وَلَيْسَ ‏ ‏يَخْفَى عَلَيْهِ مِنْ أَعْمَالِ بَنِي ‏ ‏آدَمَ ‏ ‏شَيْءٌ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الصَّبَّاحِ الْبَزَّارُ ‏ ‏وَمُحَمَّدُ بْنُ بَكَّارٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ أَبِي ثَوْرٍ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمِيرَةَ ‏ ‏عَنِ ‏ ‏الْأَحْنَفِ بْنِ قَيْسٍ ‏ ‏عَنِ ‏ ‏الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏","","",""],[1677,1677,"","\"ঈশ্বর, ঈশ্বর,\" বললো, \"ঈশ্বর, যে শার্ক\" বলে। যদি আমরা সেখানে দাঁড়িয়ে থাকতাম, তাহলে আমরা তাকে বলতাম না যে ভাববাদী। তিনি বিশ্বাস দ্বারা সেই ব্যক্তির প্রবেশ করান, যতক্ষণ না তিনি আপনাকে ভালোবাসেন, ততক্ষণ পর্যন্ত না আমরা তাঁর জন্য তোমার জন্য এক দেওয়াল তৈরি করেছি । ঈশ্বরের অনুগ্রহ লাভ করুন, তিনি ঈশ্বরের মনে বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ هَوَ ابْنُ هَارُونَ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنِ ‏ ‏الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏قُرَيْشًا ‏ ‏إِذَا لَقِيَ بَعْضُهُمْ بَعْضًا لَقُوهُمْ بِبِشْرٍ حَسَنٍ وَإِذَا لَقُونَا لَقُونَا بِوُجُوهٍ لَا نَعْرِفُهَا قَالَ فَغَضِبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَضَبًا شَدِيدًا وَقَالَ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَا يَدْخُلُ قَلْبَ رَجُلٍ الْإِيمَانُ حَتَّى يُحِبَّكُمْ لِلَّهِ وَلِرَسُولِهِ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمُطَّلِبِ بْنِ رَبِيعَةَ ‏ ‏قَالَ ‏ ‏دَخَلَ ‏ ‏الْعَبَّاسُ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّا لَنَخْرُجُ ‏ ‏فَنَرَى ‏ ‏قُرَيْشًا ‏ ‏تَحَدَّثُ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[1678,1678,"","রাজা আমাদের সাথে কথা বলার পর আমি এক সুখী ছেলের কথা বলেছি, যে আমাদের সাথে কথা বলেছে, সে আমার সাথে কথা বলেছে। গেমে আমি বলেছিলাম যে, আমার ছেলে তার জন্য প্রার্থনা করে। তোমার চাচার মৃত্যুর ব্যাপারে আমি যা শুনেছি, তা হয়তো তার মৃত্যুর জন্য পড়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏الْعَبَّاسُ ‏ ‏قَالَ ‏ ‏قُلْتُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَغْنَيْتَ عَنْ عَمِّكَ فَقَدْ كَانَ ‏ ‏يَحُوطُكَ ‏ ‏وَيَغْضَبُ لَكَ قَالَ هُوَ فِي ‏ ‏ضَحْضَاحٍ ‏ ‏وَلَوْلَا أَنَا لَكَانَ فِي ‏ ‏الدَّرْكِ ‏ ‏الْأَسْفَلِ مِنْ النَّارِ ‏","","",""],[1679,1679,"","আমরা ভিড়ের কথা বলেছিলাম আমার সাথে বড় একজন খেলোয়াড় হওয়ার কথা। মানুষ বলল যে আমি ঈশ্বরের অনুগ্রহ পেয়েছি, আর বলে যে আমরা হয়তো ঈশ্বরকে দেখেছি। আর তার সাথে কি আছে? সে বলছে, সে দাঙ্গা শুরু করেছে, হয়তো সে বলবে, \"ওয়া, আমি তাকে একটা বিরতি দেবো।\" আমি ঈশ্বরের কাছে প্রার্থনা করছি, সে এটা করতে পারবে না। আমি বলতে চাই যে আমি এক চুপ আছি, তারা আমার গর্বের ঝড় শুনতে পাবে তার ছেলের জন্য, আর আমি তোমার ছেলেকে হারিয়ে ফেলব। তাহলে \"ন\" বলে দিন, শুধু এই প্রতারণার ভয়ে আমি ভীত, সে ঈশ্বরের কাছে প্রার্থনা করলো আর তাকে ছেড়ে দেবে. আর তারপর তাকে উদ্ধার করতে হবে আর তাকে উদ্ধার করতে হবে। তারপর সে বলেছিল সে হয়তো জিতে গেছে এবং মনে হতে পারে সে নাকি মারা গেছে, সে তাদের ছেড়ে দিতে যা করেছে তা হলো ঈশ্বর। সে তার জীবন বাঁচিয়েছে, আর আমি তাদের সবাইকে বাঁচিয়েছি, ঈশ্বর বললেন যে ওর কাছে প্রার্থনা করে তার কাছে প্রার্থনা করে আর তাদের উত্তরাধিকার দিতে চাই।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏كَثِيرُ بْنُ عَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏الْعَبَّاسِ ‏ ‏قَالَ ‏ ‏شَهِدْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حُنَيْنًا ‏ ‏قَالَ فَلَقَدْ رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا مَعَهُ إِلَّا أَنَا ‏ ‏وَأَبُو سُفْيَانَ بْنُ الْحَارِثِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏فَلَزِمْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ نُفَارِقْهُ وَهُوَ عَلَى بَغْلَةٍ ‏ ‏شَهْبَاءَ ‏ ‏وَرُبَّمَا قَالَ ‏ ‏مَعْمَرٌ ‏ ‏بَيْضَاءَ ‏ ‏أَهْدَاهَا لَهُ ‏ ‏فَرْوَةُ بْنُ نَعَامَةَ الْجُذَامِيُّ ‏ ‏فَلَمَّا الْتَقَى الْمُسْلِمُونَ وَالْكُفَّارُ وَلَّى الْمُسْلِمُونَ مُدْبِرِينَ ‏ ‏وَطَفِقَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْكُضُ بَغْلَتَهُ قِبَلَ الْكُفَّارِ قَالَ ‏ ‏الْعَبَّاسُ ‏ ‏وَأَنَا آخِذٌ بِلِجَامِ بَغْلَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكُفُّهَا وَهُوَ لَا ‏ ‏يَأْلُو مَا أَسْرَعَ نَحْوَ الْمُشْرِكِينَ ‏ ‏وَأَبُو سُفْيَانَ بْنُ الْحَارِثِ ‏ ‏آخِذٌ بِغَرْزِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَبَّاسُ ‏ ‏نَادِ يَا أَصْحَابَ ‏ ‏السَّمُرَةِ ‏ ‏قَالَ ‏ ‏وَكُنْتُ رَجُلًا صَيِّتًا ‏ ‏فَقُلْتُ بِأَعْلَى صَوْتِي أَيْنَ أَصْحَابُ ‏ ‏السَّمُرَةِ ‏ ‏قَالَ فَوَاللَّهِ لَكَأَنَّ عَطْفَتَهُمْ حِينَ سَمِعُوا صَوْتِي عَطْفَةُ الْبَقَرِ عَلَى أَوْلَادِهَا فَقَالُوا يَا لَبَّيْكَ يَا لَبَّيْكَ وَأَقْبَلَ الْمُسْلِمُونَ فَاقْتَتَلُوا هُمْ وَالْكُفَّارُ فَنَادَتْ ‏ ‏الْأَنْصَارُ ‏ ‏يَقُولُونَ يَا مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏ثُمَّ قَصَّرَتْ الدَّاعُونَ عَلَى ‏ ‏بَنِي الْحَارِثِ بْنِ الْخَزْرَجِ ‏ ‏فَنَادَوْا يَا ‏ ‏بَنِي الْحَارِثِ بْنِ الْخَزْرَجِ ‏ ‏قَالَ فَنَظَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ عَلَى بَغْلَتِهِ كَالْمُتَطَاوِلِ عَلَيْهَا إِلَى قِتَالِهِمْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا حِينَ حَمِيَ ‏ ‏الْوَطِيسُ ‏ ‏قَالَ ثُمَّ أَخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَصَيَاتٍ فَرَمَى بِهِنَّ وُجُوهَ الْكُفَّارِ ثُمَّ قَالَ انْهَزَمُوا وَرَبِّ ‏ ‏الْكَعْبَةِ ‏ ‏انْهَزَمُوا وَرَبِّ ‏ ‏الْكَعْبَةِ ‏ ‏قَالَ فَذَهَبْتُ أَنْظُرُ فَإِذَا الْقِتَالُ عَلَى هَيْئَتِهِ فِيمَا أَرَى قَالَ فَوَاللَّهِ مَا هُوَ إِلَّا أَنْ رَمَاهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِحَصَيَاتِهِ فَمَا زِلْتُ أَرَى حَدَّهُمْ كَلِيلًا وَأَمْرَهُمْ مُدْبِرًا حَتَّى هَزَمَهُمْ اللَّهُ قَالَ وَكَأَنِّي أَنْظُرُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْكُضُ خَلْفَهُمْ عَلَى بَغْلَتِهِ ‏","","",""],[1680,1680,"","দুই বছর ধরে আমরা শুনেছি ফুলটা একবার অথবা দু'বার আমি কি ভেবেছিলাম। তার সাথে দুজন ছেলে তার কাছে প্রার্থনা করেছে এবং তাদের বলেছে, নবী তার কাছে প্রার্থনা করেছে। সিংহাসন, গরু।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الزُّهْرِيَّ ‏ ‏مَرَّةً أَوْ مَرَّتَيْنِ فَلَمْ أَحْفَظْهُ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عَبَّاسٌ ‏ ‏وَأَبُو سُفْيَانَ ‏ ‏مَعَهُ ‏ ‏يَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَخَطَبَهُمْ وَقَالَ ‏ ‏الْآنَ حَمِيَ ‏ ‏الْوَطِيسُ ‏ ‏وَقَالَ نَادِ يَا أَصْحَابَ سُورَةِ ‏ ‏الْبَقَرَةِ ‏","","",""],[1681,1681,"","আমরা একটি ছেলেকে খুঁজে বের করার চেষ্টা করেছি যে আমার বাবার কাছে প্রতিজ্ঞা করেছে কিন্তু আল্লাহ্‌র অনুগ্রহে ঈশ্বরের অনুগ্রহে আশ্বস্ত হয়েছেন এবং তাকে উদ্ধার করা হবে। ঈশ্বর কথা বলছে, সে আমাদের চলে যেতে দেখেছে, আর সে আমাদের ঈশ্বরের কাছে প্রার্থনা করছে, আর সে আমার গলা ঘুরিয়ে দিতে বলেছে, সে আমার হৃদয়ের ভেতরে প্রবেশ করেছে, এমনকি তোমার ও তোমার জন্য। আমার ঘাড়.","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ عَبْدِ الْحَمِيدِ أَبُو عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمُطَّلِبِ بْنِ رَبِيعَةَ ‏ ‏قَالَ ‏ ‏دَخَلَ ‏ ‏الْعَبَّاسُ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّا لَنَخْرُجُ ‏ ‏فَنَرَى ‏ ‏قُرَيْشًا ‏ ‏تَحَدَّثُ فَإِذَا رَأَوْنَا سَكَتُوا فَغَضِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَدَرَّ ‏ ‏عِرْقٌ بَيْنَ عَيْنَيْهِ ثُمَّ قَالَ وَاللَّهِ ‏ ‏لَا يَدْخُلُ قَلْبَ امْرِئٍ إِيمَانٌ حَتَّى يُحِبَّكُمْ لِلَّهِ وَلِقَرَابَتِي ‏","","",""],[1682,1682,"","আমরা একজন প্রবীন শিক্ষকের সাথে কথা বলেছি যে আমাদের মধ্যে সবচেয়ে ভালো কিছু করেছে, সে এমন এক ছেলে যার কথা সে শুনেছে। ( খ) কেন আমরা বলতে পারি যে, আমরা ঈশ্বরের ইচ্ছা পালন করি?","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِدْرِيسَ يَعْنِي الشَّافِعِيَّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ الْهَادِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏ذَاقَ طَعْمَ الْإِيمَانِ مَنْ رَضِيَ بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِينًا ‏ ‏وَبِمُحَمَّدٍ ‏ ‏نَبِيًّا رَسُولًا ‏","","",""],[1683,1683,"","আমরা একটি সুখী ছেলে খুঁজে পেতে একটি নির্দিষ্ট প্রাণীর দ্বারা পরাজিত হতে একটি সুখী পুত্র খুঁজে পেতে চেষ্টা করেছি. এটা মহান মহান মহান হাতি সঙ্গে খেলা করা হয়েছে. ঈশ্বরের অনুগ্রহের কথা শোনার জন্য আল্লাহ, ঋণ এবং বাধ্যতা দিয়ে।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏عَنِ ‏ ‏الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏ذَاقَ طَعْمَ الْإِيمَانِ مَنْ رَضِيَ بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِينًا ‏ ‏وَبِمُحَمَّدٍ ‏ ‏نَبِيًّا ‏","","",""],[1684,1684,"","আমরা আমার ছেলের চেয়ে সুখী এক দম্পতিকে একটা কথা লিখতে চেয়েছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ الْقُرَشِيُّ ‏ ‏عَنِ ‏ ‏ابْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏عَنِ ‏ ‏الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا سَجَدَ الْعَبْدُ سَجَدَ مَعَهُ سَبْعَةُ ‏ ‏آرَابٍ ‏ ‏وَجْهُهُ وَكَفَّاهُ وَرُكْبَتَاهُ وَقَدَمَاهُ ‏","","",""],[1685,1685,"","আমরা কথা বলেছিলাম আপনার টাকা সম্পর্কে শুধুমাত্র আমি যা করতে চাচ্ছি তা নয় তাকে ভাবতে দাও যে আমরা যে কথোপকথনকে বলেছিলাম, আমরা তাকেই বলি, তারপর আমরা বলবো আমরা তোমাকে বলতে চাই, তাদের মধ্যে এবং তারপর তারা এই খেলায়, সম্রাট প্রিন্স, আউটট্রাস্টকে ছুড়েছে এবং তারপর তারা দিনের মাঝখানে আছে, ঈশ্বর তাকে জিজ্ঞেস করতে হবে আমি কে, আমি গরীব, আমি তোমাকে ঈশ্বরের কাছে আহ্বান করব যে তাকে প্রভুকে সেবা করতে দেবে। আমরা তাঁর উত্তরাধিকারী হতে দেব না। আমি জানি যে নবী তার কাছে প্রার্থনা করেছেন এবং আপনাকে যে আদেশ আমি আপনাকে দিতে হবে যে আপনি কথা বলা হয়. তিনি তার সমস্যা এই মুখে আমি যা দিই নি তার সম্পর্কে তার সম্পর্কে তিনি ভুল ছিল. আমি কি না. আমি এটা জানি আপনি কি আছে? আমি যে কি না যে সব আছে. আমি তা দিতে পারি না. আমি তাকে দিতে পারি না. আমি এটা আমার প্রার্থনা. আমি যে সব কিছু জানি না. আমি তাকে দিতে হবে. আমি কি আপনি কি করব? আমি যে আপনি কি আছে? আমি এটা করতে চাই না যে আপনি কি. আপনি কি আছে. আপনি কি? আপনি একটি ভাল. আপনি একটি বিশেষ কিছু না যে আপনি আপনি আপনার জন্য ধন্যবাদ দিতে পারেন না. আপনি কি আপনি কি আপনি কি আছে? আপনি কি? আপনি একটি মহান? আপনি কি? আপনি কি? আপনি আপনার জন্য একটি মহান? আপনি কি? আপনি কি? আপনি আপনার জন্য একটি মহান? তার নিজের জন্য এটা ছিল, সে এটা পৌঁছে দিত আর তারপর সে তোমাকে দিয়ে দিত, তাকে এটা দিতে হবে, আর সে তোমাকে দিতে হবে, সে শেষ পর্যন্ত তার কাজ করতে হবে। আমরা করব। এই টাকা থেকে বুঝতে পারলে, যা বাকি আছে তা নিয়ে নাও, তার জীবন তার ইচ্ছার কাছে চলে যাবে আর সে বলে দেবে যে আমি তাকে অনেক খুশি। ( খ) কেন আমরা বলতে পারি যে, যিহোবা আমাদের প্রার্থনার উত্তর দেন?","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَنْبَأَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكُ بْنُ أَوْسِ بْنِ الْحَدَثَانِ النَّصْرِيُّ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏دَعَاهُ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ فَبَيْنَا أَنَا عِنْدَهُ إِذْ جَاءَ حَاجِبُهُ ‏ ‏يَرْفَأُ ‏ ‏فَقَالَ هَلْ لَكَ فِي ‏ ‏عُثْمَانَ ‏ ‏وَعَبْدِ الرَّحْمَنِ ‏ ‏وَالزُّبَيْرِ ‏ ‏وَسَعْدٍ ‏ ‏يَسْتَأْذِنُونَ قَالَ نَعَمْ فَأَدْخَلَهُمْ فَلَبِثَ قَلِيلًا ثُمَّ جَاءَ فَقَالَ هَلْ لَكَ فِي ‏ ‏عَلِيٍّ ‏ ‏وَعَبَّاسٍ ‏ ‏يَسْتَأْذِنَانِ قَالَ نَعَمْ فَأَذِنَ لَهُمَا فَلَمَّا دَخَلَا قَالَ ‏ ‏عَبَّاسٌ ‏ ‏يَا أَمِيرَ الْمُؤْمِنِينَ اقْضِ بَيْنِي وَبَيْنَ هَذَا ‏ ‏لَعَلِيٍّ ‏ ‏وَهُمَا يَخْتَصِمَانِ فِي ‏ ‏الصَّوَافِ الَّتِي ‏ ‏أَفَاءَ ‏ ‏اللَّهُ عَلَى رَسُولِهِ مِنْ أَمْوَالِ ‏ ‏بَنِي النَّضِيرِ ‏ ‏فَقَالَ ‏ ‏الرَّهْطُ ‏ ‏يَا أَمِيرَ الْمُؤْمِنِينَ اقْضِ بَيْنَهُمَا وَأَرِحْ أَحَدَهُمَا مِنْ الْآخَرِ قَالَ ‏ ‏عُمَرُ ‏ ‏اتَّئِدُوا أُنَاشِدُكُمْ بِاللَّهِ الَّذِي بِإِذْنِهِ تَقُومُ السَّمَاءُ وَالْأَرْضُ هَلْ تَعْلَمُونَ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا نُورَثُ مَا تَرَكْنَا صَدَقَةٌ يُرِيدُ نَفْسَهُ قَالُوا قَدْ قَالَ ذَلِكَ فَأَقْبَلَ ‏ ‏عُمَرُ ‏ ‏عَلَى ‏ ‏عَلِيٍّ ‏ ‏وَعَلَى ‏ ‏الْعَبَّاسِ ‏ ‏فَقَالَ أَنْشُدُكُمَا بِاللَّهِ أَتَعْلَمَانِ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ذَلِكَ قَالَا نَعَمْ قَالَ فَإِنِّي أُحَدِّثُكُمْ عَنْ هَذَا الْأَمْرِ أَنَّ اللَّهَ عَزَّ وَجَلَّ كَانَ خَصَّ رَسُولَهُ فِي هَذَا ‏ ‏الْفَيْءِ ‏ ‏بِشَيْءٍ لَمْ يُعْطِهِ أَحَدًا غَيْرَهُ فَقَالَ ‏ { ‏وَمَا ‏ ‏أَفَاءَ ‏ ‏اللَّهُ عَلَى رَسُولِهِ مِنْهُمْ فَمَا أَوْجَفْتُمْ ‏ ‏إِلَى ‏ ‏قَدِيرٌ ‏} ‏فَكَانَتْ هَذِهِ خَاصَّةً لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ وَاللَّهِ مَا احْتَازَهَا دُونَكُمْ وَلَا ‏ ‏اسْتَأْثَرَ ‏ ‏بِهَا عَلَيْكُمْ لَقَدْ أَعْطَاكُمُوهَا وَبَثَّهَا فِيكُمْ حَتَّى بَقِيَ مِنْهَا هَذَا الْمَالُ فَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُنْفِقُ عَلَى أَهْلِهِ نَفَقَةَ سَنَتِهِمْ مِنْ هَذَا الْمَالِ ثُمَّ يَأْخُذُ مَا بَقِيَ فَيَجْعَلُهُ مَجْعَلَ مَالِ اللَّهِ فَعَمِلَ بِذَلِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَيَاتَهُ ثُمَّ تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏أَنَا وَلِيُّ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَبَضَهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَعَمِلَ فِيهِ بِمَا عَمِلَ فِيهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1686,1686,"","আমরা তার চাচার কথা বলেছিলাম যে তোমার টাকা আমাকে বলেছে. ( খ) কেন আমাদের ঈশ্বরের সঙ্গে গমনাগমন করতে হবে? ঈশ্বর আপনার উপর দয়া করে, এটা ঘটতে পারে, তিনি বলেন আমরা যে অধিকার আছে আমরা একটি বন্ধু ছেড়ে দিতে চাই না যে ঈশ্বরের দোহাই, আমি আপনাকে পরাজিত করব এবং ভাল ঈশ্বরের সাথে খেলতে হবে ( যোহন ১৭: ৩) কিন্তু, যিশু তাঁর শিষ্যদের বলেছিলেন: “আমার ইচ্ছা এই, যেন তোমরা জান যে, আমি তোমাদের জন্য চিন্তা করি । ” এটা ছিল তার সাথে যা ঘটেছে সেটা তার কাছে আর তারপর সে এটা দিয়ে দিল আমি তাকে দিয়ে দিলাম আর সে আমাকে তার কাছ থেকে দূরে রাখে। ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তিনি আমার কাছে ও সেইসঙ্গে ঈশ্বরের কাছে তাঁর পিতার কাছে সমর্পণ করেছেন । তার পালনকর ্ তার উপর এটা করেছে যেহেতু সে এটা করেছে ঈশ্বরের দোহাই দিয়ে, আমার বিশ্বাস করার কারণ আছে যে বাবা তার উপর খুব মহান, আর ঈশ্বর জানেন এটা তার নিজের অধিকার। লড়াই করার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَخِي ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏مُحَمَّدِ بْنِ مُسْلِمٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَالِكُ بْنُ أَوْسِ بْنِ الْحَدَثَانِ النَّصْرِيُّ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ ‏ ‏فَبَيْنَا أَنَا جَالِسٌ عِنْدَهُ أَتَاهُ حَاجِبُهُ ‏ ‏يَرْفَأُ ‏ ‏فَقَالَ ‏ ‏لِعُمَرَ ‏ ‏هَلْ لَكَ فِي ‏ ‏عُثْمَانَ ‏ ‏وَعَبْدِ الرَّحْمَنِ ‏ ‏وَسَعْدٍ ‏ ‏وَالزُّبَيْرِ ‏ ‏يَسْتَأْذِنُونَ قَالَ نَعَمْ ائْذَنْ لَهُمْ قَالَ فَدَخَلُوا فَسَلَّمُوا وَجَلَسُوا قَالَ ثُمَّ لَبِثَ ‏ ‏يَرْفَأُ ‏ ‏قَلِيلًا فَقَالَ ‏ ‏لِعُمَرَ ‏ ‏هَلْ لَكَ فِي ‏ ‏عَلِيٍّ ‏ ‏وَعَبَّاسٍ ‏ ‏فَقَالَ نَعَمْ فَأَذِنَ لَهُمَا فَلَمَّا دَخَلَا عَلَيْهِ جَلَسَا فَقَالَ ‏ ‏عَبَّاسٌ ‏ ‏يَا أَمِيرَ الْمُؤْمِنِينَ اقْضِ بَيْنِي وَبَيْنَ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ ‏ ‏الرَّهْطُ ‏ ‏عُثْمَانُ ‏ ‏وَأَصْحَابُهُ اقْضِ بَيْنَهُمَا وَأَرِحْ أَحَدَهُمَا مِنْ الْآخَرِ فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏اتَّئِدُوا فَأَنْشُدُكُمْ بِاللَّهِ الَّذِي بِإِذْنِهِ تَقُومُ السَّمَاءُ وَالْأَرْضُ هَلْ تَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا نُورَثُ مَا تَرَكْنَا صَدَقَةٌ يُرِيدُ بِذَلِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَفْسَهُ قَالَ ‏ ‏الرَّهْطُ ‏ ‏قَدْ قَالَ ذَلِكَ فَأَقْبَلَ ‏ ‏عُمَرُ ‏ ‏عَلَى ‏ ‏عَلِيٍّ ‏ ‏وَعَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏فَقَالَ أَنْشُدُكُمَا بِاللَّهِ هَلْ تَعْلَمَانِ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ذَلِكَ قَالَا قَدْ قَالَ ذَلِكَ فَقَالَ ‏ ‏عُمَرُ ‏ ‏فَإِنِّي أُحَدِّثُكُمْ عَنْ هَذَا الْأَمْرِ إِنَّ اللَّهَ عَزَّ وَجَلَّ كَانَ خَصَّ رَسُولَهُ فِي هَذَا ‏ ‏الْفَيْءِ ‏ ‏بِشَيْءٍ لَمْ يُعْطِهِ أَحَدًا غَيْرَهُ فَقَالَ اللَّهُ تَعَالَى ‏ { ‏وَمَا ‏ ‏أَفَاءَ ‏ ‏اللَّهُ عَلَى رَسُولِهِ مِنْهُمْ فَمَا ‏ ‏أَوْجَفْتُمْ ‏ } ‏الْآيَةَ فَكَانَتْ هَذِهِ الْآيَةُ خَاصَّةً لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ وَاللَّهِ مَا احْتَازَهَا وَلَا اسْتَأْثَرَ بِهَا عَلَيْكُمْ لَقَدْ أَعْطَاكُمُوهَا وَبَثَّهَا فِيكُمْ حَتَّى بَقِيَ مِنْهَا هَذَا الْمَالُ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُنْفِقُ عَلَى أَهْلِهِ نَفَقَةَ سَنَتِهِمْ مِنْ هَذَا الْمَالِ ثُمَّ يَأْخُذُ مَا بَقِيَ مِنْهُ فَيَجْعَلُهُ مَجْعَلَ مَالِ اللَّهِ فَعَمِلَ بِذَلِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَيَاتَهُ أَنْشُدُكُمْ اللَّهَ هَلْ تَعْلَمُونَ ذَلِكَ قَالُوا نَعَمْ قَالَ ‏ ‏لِعَلِيٍّ ‏ ‏وَعَبَّاسٍ ‏ ‏فَأَنْشُدُكُمَا بِاللَّهِ هَلْ تَعْلَمَانِ ذَلِكَ قَالَا نَعَمْ ثُمَّ تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏أَنَا وَلِيُّ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَبَضَهَا ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَعَمِلَ فِيهَا بِمَا عَمِلَ بِهِ فِيهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنْتُمْ حِينَئِذٍ وَأَقْبَلَ عَلَى ‏ ‏عَلِيٍّ ‏ ‏وَعَبَّاسٍ ‏ ‏تَزْعُمَانِ أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏فِيهَا كَذَا وَاللَّهُ يَعْلَمُ إِنَّهُ فِيهَا لَصَادِقٌ بَارٌّ رَاشِدٌ تَابِعٌ لِلْحَقِّ ‏","","",""],[1687,1687,"","আমরা বাবার ঘোড়ার জন্য প্রার্থনা করতে বলেছিলাম, আল্লাহ যদি তার জন্য প্রার্থনা করতেন আর আমি যদি ঈশ্বরের পতাকা বলি, তাহলে আবার আমাকে বলতে হবে, প্রভু, আমি জানি, আমি জানি, আমি আমার বাবার ঘোড়ার দাম জিতেছি। আমি যদি ঈশ্বরের পতাকাকে জয় করতে চাই, তাহলে আমি যদি তার কাছে প্রার্থনা করতাম, আমি তাকে বলি, আমি যদি আমার বাবার জন্য প্রার্থনা করতাম, তাহলে আমি তাকেই বলি, আমি যদি আমার বাবার জন্য প্রার্থনা করতাম, তাহলে আমি তাকেই হবে। আমি যদি আমার বাবার জন্য প্রার্থনা করতাম, আমি তোমার কাছে ক্ষমা চাইতে হবে। কিন্তু আমি যদি আমার বাবার জন্য প্রার্থনা করতাম, আমি এটা করতে পারতাম, তাহলে আমি তোমাকে বলি, আমি কি করবো, আমি কি করবো? আমি তাকে যা বলেছি, \"ঈশ্বর, করো, করো।\" তাকে ঋণের বিরুদ্ধে এবং অন্য সবার সাথে লড়াই করতে দেয়া হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنِ ‏ ‏الْعَبَّاسِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ عَلِّمْنِي شَيْئًا أَدْعُو بِهِ فَقَالَ سَلْ اللَّهَ الْعَفْوَ وَالْعَافِيَةَ قَالَ ثُمَّ أَتَيْتُهُ مَرَّةً أُخْرَى فَقُلْتُ يَا رَسُولَ اللَّهِ عَلِّمْنِي شَيْئًا أَدْعُو بِهِ قَالَ فَقَالَ يَا ‏ ‏عَبَّاسُ ‏ ‏يَا عَمَّ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَلْ اللَّهَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ ‏","","",""],[1688,1688,"","আমি ঈশ্বরের সাথে কথা বলেছি, যখন আমার ছেলে ভালোবাসার ছেলের কথা বলেছিল, আমি ঈশ্বরের কাছে প্রার্থনা করেছি যেন তিনি তার শান্তি পান। আমি বাড়িতে থাকি না, আমি নিশ্চিত না যে লর্ডের কাছে নেই। আমি নিশ্চিত না যে, আমার প্রভুর সাথে যোগাযোগ করা উচিত। আমি যদি কোন ভালোবাসা অর্জন করি, তাহলে আমি তার জন্য প্রার্থনা করি। কিন্তু আমি আমার মনে হয় যে, আমি আমার ছেলে না যে আমি তাকে খুশি মনে করে, আমি আমার একমাত্র ভরসা করি, আমি আমার ছেলে। আমি আমার কাছে এটা একটা ভাল কাজ করে। কিন্তু আমি যদি আমার ছেলের সাথে কথা বলি, আমি তাকে আমি আমার মনের মত করে দেখি, আমি আমার মনের মতি না। আমি আমার মনের কথা বলি, আমি আমার মনের কথা বলি, আমি আমার মনের কথা বলি, আমি আমার মনে হয়, আমি আমার মনে হয় যে আমি আমার ছেলে না। আমি তাকে আমি আমার জীবনে এটা একটা সুন্দর জায়গা হিসেবে দেখি। আমি আমার বসবো। আমি আমার বসবো না। আমি আমার একমাত্র ভালোবাসা। আমি আমার মনে হয়। আমি আমার মনে হয়, আমি আমার মনে হয় যে, আমি আমার একমাত্র স্বপ্ন দেখি, আমি আমার ছেলে------------------------------------------- বিশ্বাস করো তুমি খেলতে চাও না, মানুষ বলে বাবা বড় হয়ে গেছে যখন তুমি এত কিছু করেছ, সে কাঁধে বসে পড়ে পড়ে পড়ে পড়ে পড়ে পড়ে পড়ে ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏قَيْسُ بْنُ الرَّبِيعِ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي السَّفَرِ ‏ ‏عَنِ ‏ ‏ابْنِ شُرَحْبِيلَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الْعَبَّاسِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعِنْدَهُ نِسَاؤُهُ فَاسْتَتَرْنَ مِنِّي إِلَّا ‏ ‏مَيْمُونَةَ ‏ ‏فَقَالَ ‏ ‏لَا يَبْقَى فِي الْبَيْتِ أَحَدٌ شَهِدَ ‏ ‏اللَّدَّ ‏ ‏إِلَّا لُدَّ إِلَّا أَنَّ يَمِينِي لَمْ تُصِبْ ‏ ‏الْعَبَّاسَ ‏ ‏ثُمَّ قَالَ مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏أَنْ يُصَلِّيَ بِالنَّاسِ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏لِحَفْصَةَ ‏ ‏قُولِي لَهُ إِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏رَجُلٌ إِذَا قَامَ مَقَامَكَ بَكَى قَالَ مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏لِيُصَلِّ بِالنَّاسِ فَقَامَ فَصَلَّى فَوَجَدَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خِفَّةً فَجَاءَ ‏ ‏فَنَكَصَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَأَرَادَ أَنْ يَتَأَخَّرَ فَجَلَسَ إِلَى جَنْبِهِ ثُمَّ اقْتَرَأَ ‏","","",""],[1689,1689,"","কিন্তু, আমি যখন তাকে জিজ্ঞেস করি যে, কীভাবে আমি আমার ছেলে ও মেয়ে আমার ছেলেকে ভালবাসতে শুরু করি, তখন আমি তাকে বলেছিলাম যে, কীভাবে আমি তাকে ভালবাসতে পারি । তিনি দেরি করে তার শান্তিতে বসেন । আমার বাবা ও ঈশ্বরও আমার জন্য জায়গা তৈরি করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏قَيْسٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي السَّفَرِ ‏ ‏عَنْ ‏ ‏أَرْقَمَ بْنِ شُرَحْبِيلَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي مَرَضِهِ ‏ ‏مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏يُصَلِّي بِالنَّاسِ فَخَرَجَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَكَبَّرَ وَوَجَدَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَاحَةً فَخَرَجَ ‏ ‏يُهَادَى بَيْنَ رَجُلَيْنِ فَلَمَّا رَآهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏تَأَخَّرَ فَأَشَارَ إِلَيْهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَكَانَكَ ثُمَّ جَلَسَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى جَنْبِ ‏ ‏أَبِي بَكْرٍ ‏ ‏فَاقْتَرَأَ مِنْ الْمَكَانِ الَّذِي بَلَغَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏مِنْ السُّورَةِ ‏","","",""],[1690,1690,"","আমরা আমার বাবার সঙ্গে গরু হয়ে কথা বলেছিলাম, যিনি আমার বাবার জন্য সুখী হবেন এমন একটা ছেলে খুঁজে বের করার বিষয়ে কথা বলেছিলাম । খুন, আমি ধনীদের বলেছিলাম যে, সে তোমার কোম্পানির মা হলে একটা মেয়ে মেয়ে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ بْنُ أَبِي قُرَّةَ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي قَبِيلٍ ‏ ‏عَنْ ‏ ‏أَبِي مَيْسَرَةَ ‏ ‏عَنِ ‏ ‏الْعَبَّاسِ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ فَقَالَ انْظُرْ هَلْ ‏ ‏تَرَى فِي السَّمَاءِ مِنْ نَجْمٍ قَالَ قُلْتُ نَعَمْ قَالَ مَا ‏ ‏تَرَى قَالَ قُلْتُ أَرَى ‏ ‏الثُّرَيَّا ‏ ‏قَالَ ‏ ‏أَمَا إِنَّهُ يَلِي هَذِهِ الْأُمَّةَ بِعَدَدِهَا مِنْ صُلْبِكَ اثْنَيْنِ فِي فِتْنَةٍ ‏","","",""],[1691,1691,"","আমি আমার বাবাকে সাহায্য করার চেষ্টা করেছিলাম । তিনি তাকে ফোন করেছিলেন এবং তারপর বাইরে গিয়ে বাইরে গিয়েছিলেন । আমার ভাইয়ের মত বোকা হবার জন্য আমি তাকে বলেছি, কে সে, সে কি বলছে, সে তাকে অনুসরণ করে না, সে তার মন খারাপ করে নি, আমি জানি। এই দুনিয়ার ছেলে একজন যাজককে খুঁজে বের করার জন্য যে বলেছে সে আত্মসমর্পণ করবে, আমার সাথে আমার বাবা তাকে প্রার্থনা করেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي الْأَشْعَثِ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ إِيَاسِ بْنِ عَفِيفٍ الْكِنْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏كُنْتُ امْرَأً تَاجِرًا فَقَدِمْتُ الْحَجَّ فَأَتَيْتُ ‏ ‏الْعَبَّاسَ بْنَ عَبْدِ الْمُطَّلِبِ ‏ ‏لِأَبْتَاعَ مِنْهُ بَعْضَ التِّجَارَةِ وَكَانَ امْرَأً تَاجِرًا فَوَاللَّهِ إِنَّنِي لَعِنْدَهُ ‏ ‏بِمِنًى ‏ ‏إِذْ خَرَجَ رَجُلٌ مِنْ ‏ ‏خِبَاءٍ ‏ ‏قَرِيبٍ مِنْهُ فَنَظَرَ إِلَى الشَّمْسِ فَلَمَّا رَآهَا مَالَتْ ‏ ‏يَعْنِي قَامَ ‏ ‏يُصَلِّي ‏ ‏قَالَ ثُمَّ خَرَجَتْ امْرَأَةٌ مِنْ ذَلِكَ ‏ ‏الْخِبَاءِ ‏ ‏الَّذِي خَرَجَ مِنْهُ ذَلِكَ الرَّجُلُ فَقَامَتْ خَلْفَهُ تُصَلِّي ثُمَّ خَرَجَ غُلَامٌ حِينَ رَاهَقَ الْحُلُمَ مِنْ ذَلِكَ ‏ ‏الْخِبَاءِ ‏ ‏فَقَامَ مَعَهُ ‏ ‏يُصَلِّي قَالَ فَقُلْتُ ‏ ‏لِلْعَبَّاسِ ‏ ‏مَنْ هَذَا يَا ‏ ‏عَبَّاسُ ‏ ‏قَالَ هَذَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏ابْنُ أَخِي قَالَ فَقُلْتُ مَنْ هَذِهِ الْمَرْأَةُ قَالَ هَذِهِ امْرَأَتُهُ ‏ ‏خَدِيجَةُ ابْنَةُ خُوَيْلِدٍ ‏ ‏قَالَ قُلْتُ مَنْ هَذَا الْفَتَى قَالَ هَذَا ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏ابْنُ عَمِّهِ قَالَ فَقُلْتُ فَمَا هَذَا الَّذِي يَصْنَعُ قَالَ ‏ ‏يُصَلِّي وَهُوَ يَزْعُمُ أَنَّهُ نَبِيٌّ وَلَمْ يَتْبَعْهُ عَلَى أَمْرِهِ إِلَّا امْرَأَتُهُ وَابْنُ عَمِّهِ هَذَا ‏ ‏الْفَتَى وَهُوَ يَزْعُمُ أَنَّهُ سَيُفْتَحُ عَلَيْهِ كُنُوزُ ‏ ‏كِسْرَى ‏ ‏وَقَيْصَرَ ‏ ‏قَالَ فَكَانَ عَفِيفٌ وَهُوَ ابْنُ عَمِّ ‏ ‏الْأَشْعَثِ بْنِ قَيْسٍ ‏ ‏يَقُولُ وَأَسْلَمَ بَعْدَ ذَلِكَ فَحَسُنَ إِسْلَامُهُ لَوْ كَانَ اللَّهُ رَزَقَنِي الْإِسْلَامَ يَوْمَئِذٍ فَأَكُونُ ثَالِثًا مَعَ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏","","",""],[1692,1692,"","আমরা বাবার চেয়ে দুই জীবনের কথা বলেছিলাম, ঈশ্বরের ভালবাসার জন্য ঘোড়ার জন্য, কিন্তু আমার বাবা গেমের প্রতি ভালোবাসায় বলেছিলেন যে, তিনি তার জন্য প্রার্থনা করেছেন, যেন তিনি তার কাছে কিছু অর্থ সমর্পণ করেন। মানুষ বলেছে এটাই সঠিক কাজ। আমি ঈশ্বরের টাকা বলে দিয়েছি আমরা ঈশ্বরের ইচ্ছার সাথে আবদ্ধ কিন্তু এটা করতে গিয়ে দুই সপ্তাহ পরে সে আমাকে একটা ভাল রুমে নিয়ে যায়। আর ভাল, শ্বাস নেই।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ نَوْفَلٍ ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ بْنِ أَبِي وَدَاعَةَ ‏ ‏قَالَ قَالَ ‏ ‏الْعَبَّاسُ ‏ ‏بَلَغَهُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْضُ مَا يَقُولُ النَّاسُ قَالَ فَصَعِدَ الْمِنْبَرَ فَقَالَ مَنْ أَنَا قَالُوا أَنْتَ رَسُولُ اللَّهِ فَقَالَ ‏ ‏أَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏إِنَّ اللَّهَ خَلَقَ الْخَلْقَ فَجَعَلَنِي فِي خَيْرِ خَلْقِهِ وَجَعَلَهُمْ فِرْقَتَيْنِ فَجَعَلَنِي فِي خَيْرِ فِرْقَةٍ وَخَلَقَ الْقَبَائِلَ فَجَعَلَنِي فِي خَيْرِ قَبِيلَةٍ وَجَعَلَهُمْ بُيُوتًا فَجَعَلَنِي فِي خَيْرِهِمْ بَيْتًا فَأَنَا خَيْرُكُمْ بَيْتًا وَخَيْرُكُمْ نَفْسًا ‏","","",""],[1693,1693,"","আমরা বাবার সাথে জাহাজ নিয়ে কিছু একটা করার কথা বলেছিলাম, ঈশ্বর বাবার সাথে এমন দাবি করেছেন যে সে হয়ত তোমার প্রতারণা করেছে। ...আর আগুন এর ঘরেই থাকতে হতো।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ نَوْفَلٍ ‏ ‏عَنْ ‏ ‏عَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏قَالَ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏هَلْ نَفَعْتَ ‏ ‏أَبَا طَالِبٍ ‏ ‏بِشَيْءٍ فَإِنَّهُ قَدْ كَانَ ‏ ‏يَحُوطُكَ ‏ ‏وَيَغْضَبُ لَكَ قَالَ نَعَمْ هُوَ فِي ‏ ‏ضَحْضَاحٍ ‏ ‏مِنْ النَّارِ لَوْلَا ذَلِكَ لَكَانَ هُوَ فِي ‏ ‏الدَّرْكِ ‏ ‏الْأَسْفَلِ مِنْ النَّارِ ‏","","",""],[1694,1694,"","আমরা আপনার দুর্ভাগ্যের কথা বলেছি আপনার দুর্ভাগ্যের জন্য আপনার দুর্ভাগ্যের কথা বলছি, সে একজন উড়ন্ত মানুষ যিনি এই বিষের মধ্যে দিয়ে যায়। তার উপর তার গায়ের বিষ প্রয়োগ করা হয়। সে বিষ প্রয়োগ করে। সে বিষ প্রয়োগ করে আঘাত পায়। ( মথি ২৪: ১৪) ঈশ্বরের কাছে তাঁর ভবিষ্যদ্বাণীটা রাখুন, তিনি ঈশ্বরের কাছে প্রার্থনা করবেন । তার দৃষ ্ টিও হয়তো তোমাকে বোঝাতে পারে যে , তুমি তাদের সাথে খেলা চালাতে পারবে না , যদিও তারা নিজেরাই হচ ্ ছে স ্ থায়ীভাবে আর ধর ্ মনিষ ্ ঠ হতে পারে । সে যেখানে আছে, সেখানে সক্ষম হতে সক্ষম হতে সক্ষম হতে সক্ষম। লর্ডের বার্তাবাহক তার কাছে প্রার্থনা করেছেন যেন তিনি এটা করতে রাজি হন যে প্রভুর সৌভাগ্য তার উপর আছে.","‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏أَخِي ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏لِلْعَبَّاسِ ‏ ‏مِيزَابٌ ‏ ‏عَلَى طَرِيقِ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏فَلَبِسَ ‏ ‏عُمَرُ ‏ ‏ثِيَابَهُ يَوْمَ الْجُمُعَةِ وَقَدْ كَانَ ذُبِحَ ‏ ‏لِلْعَبَّاسِ ‏ ‏فَرْخَانِ فَلَمَّا وَافَى ‏ ‏الْمِيزَابَ ‏ ‏صُبَّ مَاءٌ بِدَمِ الْفَرْخَيْنِ فَأَصَابَ ‏ ‏عُمَرَ ‏ ‏وَفِيهِ دَمُ الْفَرْخَيْنِ فَأَمَرَ ‏ ‏عُمَرُ ‏ ‏بِقَلْعِهِ ثُمَّ رَجَعَ ‏ ‏عُمَرُ ‏ ‏فَطَرَحَ ثِيَابَهُ وَلَبِسَ ثِيَابًا غَيْرَ ثِيَابِهِ ثُمَّ جَاءَ فَصَلَّى بِالنَّاسِ فَأَتَاهُ ‏ ‏الْعَبَّاسُ ‏ ‏فَقَالَ ‏ ‏وَاللَّهِ إِنَّهُ لَلْمَوْضِعُ الَّذِي وَضَعَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏لِلْعَبَّاسِ ‏ ‏وَأَنَا أَعْزِمُ عَلَيْكَ لَمَّا صَعِدْتَ عَلَى ظَهْرِي حَتَّى تَضَعَهُ فِي الْمَوْضِعِ الَّذِي وَضَعَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَفَعَلَ ذَلِكَ ‏ ‏الْعَبَّاسُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏","","",""],[1695,1695,"","আমরা একজন কাপুরুষের দাসের বিষয়ে কথা বলেছিলাম, যিনি একজন যাজকের ছেলে হওয়ার বিষয়ে একটা শিক্ষা দিয়েছিলেন, যিনি প্রথম স্থানে তার জীবনকে ব্যয় করতে পারতেন । বাকি সবার কাছ থেকে আত্মসমর্পণ করে, নরক ফেলে দেয়ার আগ পর্যন্ত সে আর কাঁদতেও থাকে না।","‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏أَنَّهُ ‏ ‏كَانَ ‏ ‏رِدْفَ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏جَمْعٍ ‏ ‏فَلَمْ يَزَلْ يُلَبِّي حَتَّى رَمَى ‏ ‏الْجَمْرَةَ ‏","","",""],[1696,1696,"","ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং তিনি আমাকে সেই জাহাজে পাঠিয়ে দিয়েছিলেন । একবার পর্বত।","‏ ‏قَالَ ‏ ‏قُرِئَ عَلَى ‏ ‏سُفْيَانَ ‏ ‏سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ أَبِي حَرْمَلَةَ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَبَّى حَتَّى رَمَى ‏ ‏الْجَمْرَةَ ‏","","",""],[1697,1697,"","আমরা একটি পিপাপির ছেলে সম্পর্কে কথা বলেছি যে একটি ছেলে ঈশ্বরকে রক্ষা করেছে। আমি একটি বাচ্চা সন্তান জন্ম দিয়েছি এবং আমি স্বপ্নের মধ্যে দিয়ে স্বপ্ন দেখছি। আমাকে বলা হয়েছে আমার ছেলেই সবচেয়ে ভালো। আমি জানি, আমার ছেলে আমাকে যে সংবাদ দিয়েছে। আমি তাকে বলেছিলাম, আমি যদি বলি, আমি তাকে একটা ছোট ছেলে হিসেবে চাই, আমি আমার ছেলের স্বপ্নের কথা বলি, তাহলে আমি তাকে বলি। আমি যদি আমার ছেলের জন্য একটা ভাল দিন, আমি আমার ছেলের স্বপ্নের কথা বলি, তাহলে আমি তাকে ছেড়ে দেব। আর আমি তাকে আমি আমার ছেলের সাথে পরিচিত হতাম। আমি যখন আমি বলেছিলাম, আমি তাকে বলেছিলাম, আমি আমার ছেলের সাথে ছিলাম, আমি আমার ছেলের সাথে আমার ছেলের সাথে যোগাযোগ করি, আমি তখন আমি আমার ছেলের সাথে আমার ছেলের সম্পর্কটা ঠিক আছে। আর আমি তাকে বলেছিলাম যে, আমি আমার ছেলের সাথে আমার ছেলের সাথে কথা বলব। পাথর ছুঁড়ে না ফেলে দিলে তাকে জানানো হয় নি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْدَفَ ‏ ‏الْفَضْلَ بْنَ عَبَّاسٍ ‏ ‏مِنْ ‏ ‏جَمْعٍ ‏ ‏قَالَ ‏ ‏عَطَاءٌ ‏ ‏فَأَخْبَرَنِي ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏الْفَضْلَ ‏ ‏أَخْبَرَهُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَزَلْ يُلَبِّي حَتَّى رَمَى ‏ ‏الْجَمْرَةَ ‏","","",""],[1698,1698,"","ঈশ্বরের কাছে প্রার্থনা করার চেয়ে তিনি তোমাকে যে - উত্তম শিক্ষা দিয়েছেন, তা হল, ঈশ্বর তোমাকে শিখিয়েছিলেন । এই সময় তার জন্য প্রার্থনা করা এবং তার হাতের চিহ্ন চিহ্নিত করা উচিত। আর সে বলেছে, যখন তারা টাকা দিয়েছিল, সে জানতো সব মানুষের দুপুরের খাবার।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو مَعْبَدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يُخْبِرُ عَنِ ‏ ‏الْفَضْلِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَشِيَّةَ ‏ ‏عَرَفَةَ ‏ ‏غَدَاةَ ‏ ‏جَمْعٍ ‏ ‏لِلنَّاسِ حِينَ دَفَعْنَا ‏ ‏عَلَيْكُمْ السَّكِينَةَ وَهُوَ ‏ ‏كَافٌّ ‏ ‏نَاقَتَهُ حَتَّى إِذَا دَخَلَ ‏ ‏مِنًى ‏ ‏حِينَ هَبَطَ ‏ ‏مُحَسِّرًا ‏ ‏قَالَ عَلَيْكُمْ بِحَصَى ‏ ‏الْخَذْفِ ‏ ‏الَّذِي ‏ ‏يُرْمَى بِهِ ‏ ‏الْجَمْرَةُ ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُشِيرُ بِيَدِهِ كَمَا ‏ ‏يَخْذِفُ ‏ ‏الْإِنْسَانُ ‏ ‏و قَالَ ‏ ‏رَوْحٌ ‏ ‏وَالبُرْسَانِيُّ ‏ ‏عَشِيَّةَ ‏ ‏عَرَفَةَ ‏ ‏وَغَدَاةَ ‏ ‏جَمْعٍ ‏ ‏وَقَالَا حِينَ دَفَعُوا ‏","","",""],[1699,1699,"","আমরা একটা ছেলের কথা বলেছিলাম যে একটা ছেলের সাথে দেখা করার জন্য ঋণ নিয়ে এসেছিল, হয়তো সে তার জন্য প্রার্থনা করতো আর সে আবার নিজেকে আত্মসমর্পণ করতো আর একটা ছেলের জন্য ডাকতো পিটার ফিরে এসেছে, সে খুঁজে পায়নি.","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَامَ فِي ‏ ‏الْكَعْبَةِ ‏ ‏فَسَبَّحَ وَكَبَّرَ وَدَعَا اللَّهَ عَزَّ وَجَلَّ وَاسْتَغْفَرَ وَلَمْ يَرْكَعْ وَلَمْ يَسْجُدْ ‏","","",""],[1700,1700,"","আমরা দুজন তর্ক আর বাবার ব্যাপারে কথা বলেছি, ঈশ্বর হয়তো ইটের মতো একটা শিক্ষা দিয়েছেন যে ঈশ্বর তাকে তার জীবন দিয়েছেন। আর দুপুরের খাবারটা খেতেও বেশ ভালো লাগে। আর দুপুরের খাবারটা একটু ভালো লাগে। আর আমি জানি, ঈশ্বর তাকে ভালো করে খাবারটি দিয়েছেন। আর আমি জানি না যে, ঈশ্বর আমার বাবা, আমি কি করতে পারি? যে সমস্ত লোক ছুরির জন্য টাকা দিয়েছে, তাদের রক্ষা করা উচিত যদি সে কোন দুর্দশার অবস্থায় থাকে। ওটা উদ্ধার করতে, এটা করতে নয়, চাঁদ.","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِي مَعْبَدٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏وَكَانَ ‏ ‏رَدِيفَ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ فِي عَشِيَّةِ ‏ ‏عَرَفَةَ ‏ ‏وَغَدَاةِ ‏ ‏جَمْعٍ ‏ ‏لِلنَّاسِ حِينَ دَفَعُوا ‏ ‏عَلَيْكُمْ السَّكِينَةَ وَهُوَ ‏ ‏كَافٌّ ‏ ‏نَاقَتَهُ حَتَّى إِذَا دَخَلَ ‏ ‏مُحْسِّرًا ‏ ‏وَهُوَ مِنْ ‏ ‏مِنًى ‏ ‏قَالَ عَلَيْكُمْ بِحَصَى ‏ ‏الْخَذْفِ ‏ ‏الَّذِي ‏ ‏يُرْمَى بِهِ ‏ ‏الْجَمْرَةُ ‏ ‏وَقَالَ لَمْ يَزَلْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُلَبِّي حَتَّى رَمَى الْجَمْرَةَ ‏","","",""],[1701,1701,"","আমরা একটি পিপাপির পুত্র সম্পর্কে কথা বলেছি যে তিনি আমাকে ভালোবাসেন একটি পুত্র পুত্র পুত্র যে আমাকে ভালবাসেন। যেভাবে আমরা সকল ভদ্র আচরণ করি, সেই ভাবে ভাববাদী ঈশ্বরের কাছে প্রার্থনা করেন যেন তিনি পাখিটিকে উদ্ধার করতে এবং তাদের স্বপ্ন ছিল যে দেরি হবে এবং তাকে পাথর মারা হবে না।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ عُمَرَ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَبَّاسِ بْنِ عُبَيْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏زَارَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَبَّاسًا ‏ ‏فِي ‏ ‏بَادِيَةٍ ‏ ‏لَنَا وَلَنَا كُلَيْبَةٌ وَحِمَارَةٌ ‏ ‏تَرْعَى فَصَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَصْرَ وَهُمَا بَيْنَ يَدَيْهِ فَلَمْ تُؤَخَّرَا وَلَمْ ‏ ‏تُزْجَرَا ‏","","",""],[1702,1702,"","আমরা আমাদের আলোচনা নিয়ে কথা বলেছি এবং তারা আমার প্রিয় ভাইয়ের ব্যাপারে কথা বলেছে, আমি লর্ডের লর্ড ছিলাম, এবং তিনি আমার প্রভুর দিনের সম্প্রদায় থেকে উদ্ধার করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏أَنَّهُ كَانَ ‏ ‏رَدِيفَ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏جَمْعٍ ‏ ‏إِلَى ‏ ‏مِنًى ‏ ‏فَلَمْ يَزَلْ ‏ ‏يُلَبِّي حَتَّى رَمَى ‏ ‏الْجَمْرَةَ ‏","","",""],[1703,1703,"","আমরা কথা বলেছিলাম কীভাবে আপনি আমাদের সুখী করতে পারেন । ইশ্বরের দোহাই, দেবতাকে দেবতা বলে, দেবতা দেবতাকে, ঈশ্বর দেবতা, ঈশ্বরের দোহাই প্রার্থনা করেছেন। তার জন্য এবং একই সাথে প্রার্থনা করা হবে সকল হাঁটুর উপর এবং উন্নত হবে. হে খোদা!","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُبَارَكٍ ‏ ‏أَنْبَأَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ رَبِّهِ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ أَبِي أَنَسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ نَافِعِ ابْنِ الْعَمْيَاءِ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ الْحَارِثِ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّلَاةُ مَثْنَى مَثْنَى ‏ ‏تَشَهَّدُ فِي كُلِّ رَكْعَتَيْنِ ‏ ‏وَتَضَرَّعُ ‏ ‏وَتَخَشَّعُ ‏ ‏وَتَمَسْكَنُ ثُمَّ تُقَنِّعُ يَدَيْكَ يَقُولُ تَرْفَعُهُمَا إِلَى رَبِّكَ مُسْتَقْبِلًا بِبُطُونِهِمَا وَجْهَكَ تَقُولُ يَا رَبِّ يَا رَبِّ فَمَنْ لَمْ يَفْعَلْ ذَلِكَ فَقَالَ فِيهِ قَوْلًا شَدِيدًا ‏","","",""],[1704,1704,"","আমরা আমার বাবার সাথে আমার মনের নিয়ম হওয়ার কথা বলেছিলাম... ...হয়তো আমরা কিছুসময় নিচে নেমে যাওয়ার আগেই সে তার সাথে নিচে নেমে আসতো। আমরা আমাদের সবকিছু নষ্ট করতে এসেছিলাম। ভুয়া।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي حَكِيمٍ الْعَدَنِيُّ ‏ ‏حَدَّثَنِي ‏ ‏الْحَكَمُ يَعْنِي ابْنَ أَبَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عِكْرِمَةَ ‏ ‏يَقُولُ قَالَ ‏ ‏الْفَضْلُ بْنُ عَبَّاسٍ ‏ ‏لَمَّا ‏ ‏أَفَاضَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا مَعَهُ فَبَلَغْنَا ‏ ‏الشِّعْبَ ‏ ‏نَزَلَ فَتَوَضَّأَ ثُمَّ رَكِبْنَا حَتَّى جِئْنَا ‏ ‏الْمُزْدَلِفَةَ ‏","","",""],[1705,1705,"","আমি আমার বাবার সাথে আমার ভালবাসার জন্য আমাকে জিততে চেষ্টা করার কথা বলেছিলাম, আমি নিশ্চিত আমার ভাইয়ের সবচেয়ে ভাল বাজি ছিল তার প্রেমিকের সাহস। সেখানে প্রবেশ করতে এবং এতে ভাল বাস করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏مُجَاهِدِ بْنِ جَبْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏حَدَّثَنِي ‏ ‏أَخِي ‏ ‏الْفَضْلُ بْنُ عَبَّاسٍ ‏ ‏وَكَانَ مَعَهُ حِينَ دَخَلَهَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يُصَلِّ فِي ‏ ‏الْكَعْبَةِ ‏ ‏وَلَكِنَّهُ لَمَّا دَخَلَهَا وَقَعَ سَاجِدًا بَيْنَ الْعَمُودَيْنِ ثُمَّ جَلَسَ يَدْعُو ‏","","",""],[1706,1706,"","আমি বাবার ছেলেকে একজন যাজকের ছেলেকে দিতে বলেছি, প্রভু তার জন্য প্রার্থনা করেছেন এবং তাকে আত্মসমর্পণ করেছেন যতদিন না তিনি তার পুরো সম্প্রদায়কে ধ্বংস করতে চান তার নিজের জীবন, আর সে যখন বলেছিল যে আমরা বাবার ছেলে একটা ছেলেকে সাহায্য করবো, ঈশ্বরের বার্তাবাহকের সাথে যে দু'জন সময় কাটাত, সে তা করেছে। ( ১ করি.","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَخْبَرَنِي ‏ ‏الْفَضْلُ بْنُ عَبَّاسٍ ‏ ‏أَنَّهُ كَانَ ‏ ‏رِدْفَ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ أَفَاضَ مِنْ ‏ ‏جَمْعٍ ‏ ‏قَالَ فَأَفَاضَ وَعَلَيْهِ السَّكِينَةُ قَالَ وَلَبَّى حَتَّى رَمَى ‏ ‏جَمْرَةَ الْعَقَبَةِ ‏ ‏و قَالَ ‏ ‏مَرَّةً ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنْبَأَنَا ‏ ‏الْفَضْلُ بْنُ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏شَهِدْتُ الْإِفَاضَتَيْنِ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَفَاضَ وَعَلَيْهِ السَّكِينَةُ وَهُوَ ‏ ‏كَافٌّ ‏ ‏بَعِيرَهُ قَالَ وَلَبَّى حَتَّى رَمَى ‏ ‏جَمْرَةَ الْعَقَبَةِ ‏ ‏مِرَارًا ‏","","",""],[1707,1707,"","আমরা দুজন সালমেন্সের কথা বলেছি, আমরা বাবার বাবার বাবার বাবার বাবার সাথে কথা বলেছি। লর্ড তার জন্য প্রার্থনা করেছে এবং আত্মসমর্পণ করেছে। আমি যখন লোকেদের জ্ঞান জানতে পেরেছি, যাদেরকে মাটিতে রাখা যায় ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ بْنُ سُلَيْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏وَكَانَ ‏ ‏رَدِيفَ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ أَفَاضَ مِنْ ‏ ‏عَرَفَةَ ‏ ‏قَالَ ‏ ‏فَرَأَى النَّاسَ يُوضِعُونَ فَأَمَرَ مُنَادِيَهُ فَنَادَى لَيْسَ الْبِرُّ بِإِيضَاعِ الْخَيْلِ وَالْإِبِلِ فَعَلَيْكُمْ بِالسَّكِينَةِ ‏","","",""],[1708,1708,"","আমরা আমার ভাইয়ের ছেলেকে খুন করার চেষ্টা করেছিলাম, শহীদের ছেলে, তার চাচা আমাকে বলেছে যে তিনি ঈশ্বরকে ভালোবাসেন। তিনি জীবিত এবং মায়ের শান্তি হল প্রভুর প্রভুর। এটা হচ্ছে কাপুরুষের কাজ। এটা আমার কাছে একটা কাপুরুষের মত। আমি যদি আমার ভাই না থাকি, আমি যদি আমার ভাই-বাবার ছেলে না থাকতাম, আমি জানি যে, আমি আমার চাচার ছেলেও তার সাথে নেই। আমি যদি আমার চাচার ছেলেও না থাকে, আমি যদি আমার মা মারা যাই, আমি আমার মা, আমি তোমার সাথে নেই, আমি শুধু তোমার জন্য এটা একটা ভাল করে দেই। আমি জানি। আমি জানি না যে, আমি তোমার জন্য এটা করতে পারি। আমি যদি তুমি আমাকে সাহায্য করো, আমি তোমার কাছে এটা করতে পারি। আমি তোমার সিদ্ধান্তের জন্য। আমি তোমার কাছে এটা একটা বড় সুযোগ হবে। আর আমি তোমার কাছে এটা একটা বড় সুযোগ হবে। কিন্তু আমি যদি তুমি এটা করতে পারি। আমি তোমার কাছে এটা একটা বড় সুযোগ। আমি যখন লাফ দেবার আগে যারা ভিক্ষা করবে, আমি বলছি, ঈশ্বরই ভালোর জন্য সেরা।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَخِي ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو بَكْرِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏وُأُمُّ سَلَمَةَ ‏ ‏زَوْجَا النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصْبِحُ مِنْ أَهْلِهِ جُنُبًا فَيَغْتَسِلُ قَبْلَ أَنْ يُصَلِّيَ الْفَجْرَ ثُمَّ يَصُومُ يَوْمَئِذٍ ‏ ‏قَالَ ‏ ‏فَذَكَرْتُ ذَلِكَ ‏ ‏لِأَبِي هُرَيْرَةَ ‏ ‏فَقَالَ ‏ ‏لَا أَدْرِي ‏ ‏أَخْبَرَنِي ‏ ‏ذَلِكَ ‏ ‏الْفَضْلُ بْنُ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏","","",""],[1709,1709,"","আমরা দু'টি দেশের কথা বলেছি, আমরা আরেকজনের ভাইয়ের বিচার করার চেষ্টা করেছি, আমি লর্ডের কাছে প্রার্থনা করেছি এবং আমাদের সবার কাছে প্রার্থনা করেছি, কিন্তু সে আমাদের চেয়ে ভালো। যদি মেয়ের একটা জীবন থাকতো, সে বলত সে তার দিকে তাকিয়ে থাকবে। তারপর আমি কথা দিচ্ছি, আমি তোমার তিন বার চেষ্টা করে দেখবো। আমি এটা করবো না।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏الْحَكَمِ بْنِ عُتَيْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏الْفَضْلِ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏رَدِيفَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏جَمْعٍ ‏ ‏إِلَى ‏ ‏مِنًى ‏ ‏فَبَيْنَا هُوَ يَسِيرُ إِذْ عَرَضَ لَهُ أَعْرَابِيٌّ مُرْدِفًا ابْنَةً لَهُ جَمِيلَةً وَكَانَ يُسَايِرُهُ قَالَ فَكُنْتُ أَنْظُرُ إِلَيْهَا فَنَظَرَ إِلَيَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَلَبَ وَجْهِي عَنْ وَجْهِهَا ثُمَّ أَعَدْتُ النَّظَرَ فَقَلَبَ وَجْهِي عَنْ وَجْهِهَا حَتَّى فَعَلَ ذَلِكَ ثَلَاثًا وَأَنَا لَا أَنْتَهِي ‏ ‏فَلَمْ يَزَلْ يُلَبِّي حَتَّى رَمَى ‏ ‏جَمْرَةَ الْعَقَبَةِ ‏","","",""],[1710,1710,"","আমি আমার বাবার সঙ্গে কথা বলেছিলাম, যেন তিনি কোনো না কোনো উপায়ে খেলাধুলা করার চেষ্টা করেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَنْبَأَنَا ‏ ‏قَيْسٌ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَبَّى يَوْمَ النَّحْرِ حَتَّى رَمَى ‏ ‏جَمْرَةَ الْعَقَبَةِ ‏","","",""],[1711,1711,"","কয়েক বছর আগে আমরা একটা ছেলেকে দেওয়ার চেষ্টা করেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَامِرٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ ‏ ‏أَنَّهُ كَانَ ‏ ‏رَدِيفَ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُلَبِّي حَتَّى رَمَى ‏ ‏الْجَمْرَةَ ‏","","",""],[1712,1712,"","আমি ভবিষ্যদ্‌বাণীর একজন সম্মানিত ছেলে খুঁজে পাওয়ার চেষ্টা করেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏يُوسُفَ بْنَ مَاهَكَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏رَدِيفَ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَبَّى فِي الْحَجِّ حَتَّى رَمَى ‏ ‏الْجَمْرَةَ ‏ ‏يَوْمَ النَّحْرِ ‏","","",""],[1713,1713,"","ঈশ্বর তাকে শিক্ষা দিয়েছেন এবং ঈশ্বর জয়ী হয়েছেন!","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَامِرٍ الْأَحْوَلِ ‏ ‏وَجَابِرٍ الْجُعْفِيِّ ‏ ‏وَابْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏أَنَّهُ كَانَ ‏ ‏رَدِيفَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَبَّى حَتَّى رَمَى ‏ ‏الْجَمْرَةَ ‏ ‏يَوْمَ النَّحْرِ ‏","","",""],[1714,1714,"","আমরা একটা কামনায় বাপ্তাইজিত হয়েছি... ...যে আমরা একটা ভুল করার চেষ্টা করেছি, আমি সেরা ইটের মধ্যে ছিলাম...","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏وَعَامِرٍ الْأَحْوَلِ ‏ ‏وَابْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏الْفَضْلَ بْنَ عَبَّاسٍ ‏ ‏كَانَ ‏ ‏رَدِيفَ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَانَ ‏ ‏يُلَبِّي يَوْمَ النَّحْرِ حَتَّى رَمَى ‏ ‏الْجَمْرَةَ ‏","","",""],[1715,1715,"","আমি আমার ছেলেকে একটা কুঁড়েঘর দেওয়া সম্পর্কে বলতে চেয়েছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏مُشَاشٌ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَعَفَةَ ‏ ‏بَنِي هَاشِمٍ ‏ ‏أَمَرَهُمْ أَنْ يَتَعَجَّلُوا مِنْ ‏ ‏جَمْعٍ ‏ ‏بِلَيْلٍ ‏","","",""],[1716,1716,"","আমরা একটি সাধারণ উদ্বেগের কথা বলেছি যে আমার বাবাকে আরও ভালো একটি জীবন খুঁজতে হবে। একজন মানুষ যে তাকে এই ভবিষ্যদ্বাণী করতে বলবে, প্রভু, আমার বাবার কাছে অবশ্যই আছে। আমি তার কাছে প্রমাণ করতে চাই যে তার কাছে অনেক ঋণ আছে। আমি ঈশ্বরের মহান প্রভু ছিলাম, আমাকে বলতে বলা হত যে আমার বাবা বা মা ভুল করবে।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏أَوْ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏أَنَّ رَجُلًا سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ أَبِي أَدْرَكَهُ الْإِسْلَامُ وَهُوَ شَيْخٌ كَبِيرٌ لَا يَثْبُتُ عَلَى رَاحِلَتِهِ أَفَأَحُجُّ عَنْهُ قَالَ أَرَأَيْتَ لَوْ كَانَ عَلَيْهِ دَيْنٌ فَقَضَيْتَهُ عَنْهُ أَكَانَ ‏ ‏يُجْزِيهِ قَالَ نَعَمْ قَالَ ‏ ‏فَاحْجُجْ عَنْ أَبِيكَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُلَيْمَانَ بْنَ يَسَارٍ ‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏رَدِيفَ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَهُ رَجُلٌ فَقَالَ إِنَّ أَبِي ‏ ‏أَوْ أُمِّي ‏ ‏شَيْخٌ كَبِيرٌ لَا يَسْتَطِيعُ الْحَجَّ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[1717,1717,"","আমি আমার আবেগকে ফিরিয়ে আনার এবং একটি পাপ দিয়ে পাপ করার ব্যাপারে তর্ক করেছি।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْأَحْوَلِ ‏ ‏وَجَابِرٍ الْجُعْفِيِّ ‏ ‏وَابْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ ‏ ‏أَنَّهُ كَانَ ‏ ‏رَدِيفَ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَبَّى حَتَّى رَمَى الْجَمْرَةَ يَوْمَ النَّحْرِ ‏","","",""],[1718,1718,"","আমার বাবার কাছে একটা gudds সন্তানের চেয়ে আরও ভাল ছেলে থাকার জন্য বাবার সঙ্গে আমাদের সম্পর্ক আরও ভালো ছিল ঈশ্বরের পুত্র, ঈশ্বর নন বরং তিনি তাও দেখেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصٌ ‏ ‏عَنْ ‏ ‏جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَزَلْ يُلَبِّي حَتَّى رَمَى ‏ ‏جَمْرَةَ الْعَقَبَةِ ‏ ‏فَرَمَاهَا بِسَبْعِ حَصَيَاتٍ يُكَبِّرُ مَعَ كُلِّ حَصَاةٍ ‏","","",""],[1719,1719,"","আমরা একটা ছেলের কথা বলেছিলাম যে দাস ছিল, আর তারপর আমরা আপনাকে ঈশ্বরের দোহাই দিতে পারতাম, প্রভু তার প্রার্থনা এবং আশ্বস্ত করার জন্য। লর্ড তার দয়া, তার হাত বাড়ার আগে এবং সে তার হাতে এক চতুর্থাংশ পর্যন্ত, বিছানায় থাকার সময় সে লড়াই করবে না। সে আমার প্যাঁচকে দিয়ে গেল যতক্ষণ না সে এই গুজবটা ছুঁড়ে ফেলে।","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏وَمُحَمَّدٌ ‏ ‏ابْنًا ‏ ‏عُبَيْدٍ ‏ ‏قَالَا ثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ ‏ ‏قَالَ ‏ ‏أَفَاضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏عَرَفَاتٍ ‏ ‏وَأُسَامَةُ بْنُ زَيْدٍ ‏ ‏رِدْفُهُ ‏ ‏فَجَالَتْ بِهِ النَّاقَةُ وَهُوَ وَاقِفٌ ‏ ‏بِعَرَفَاتٍ ‏ ‏قَبْلَ أَنْ يُفِيضَ وَهُوَ رَافِعٌ يَدَيْهِ لَا تُجَاوِزَانِ رَأْسَهُ فَلَمَّا أَفَاضَ سَارَ عَلَى هِينَتِهِ حَتَّى أَتَى ‏ ‏جَمْعًا ‏ ‏ثُمَّ أَفَاضَ مِنْ ‏ ‏جَمْعٍ ‏ ‏وَالْفَضْلُ ‏ ‏رِدْفُهُ ‏ ‏قَالَ ‏ ‏الْفَضْلُ ‏ ‏مَا زَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُلَبِّي حَتَّى رَمَى الْجَمْرَةَ ‏","","",""],[1720,1720,"","আমরা আমাদের আগের জগতের সর্বোত্তমতমগুলোর বিষয়ে কথা বলেছিলাম । এটা এক আশীর্বাদ যে, এটা তার ছেলে নয় এবং তারা এমন কিছু যা তার ছেলেকে দিয়ে যায়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عُمَرَ بْنِ عَلِيٍّ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏زَارَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَبَّاسًا ‏ ‏وَنَحْنُ فِي ‏ ‏بَادِيَةٍ ‏ ‏لَنَا ‏ ‏فَقَامَ ‏ ‏يُصَلِّي قَالَ ‏ ‏أُرَاهُ قَالَ الْعَصْرَ ‏ ‏وَبَيْنَ يَدَيْهِ كُلَيْبَةٌ لَنَا وَحِمَارٌ ‏ ‏يَرْعَى لَيْسَ بَيْنَهُ وَبَيْنَهُمَا شَيْءٌ يَحُولُ بَيْنَهُ وَبَيْنَهُمَا ‏","","",""],[1721,1721,"","আমরা আমাদের সেরাটা নিয়ে কথা বলেছি... ...কিছু খারাপ জিনিস থেকে দূরে সরে যেতে সক্ষম হওয়ার ব্যাপারে। বাবা।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏حَدَّثَنِي ‏ ‏الْفَضْلُ بْنُ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَتَتْ امْرَأَةٌ مِنْ ‏ ‏خَثْعَمٍ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ أَبِي أَدْرَكَتْهُ فَرِيضَةُ اللَّهِ عَزَّ وَجَلَّ فِي الْحَجِّ وَهُوَ شَيْخٌ كَبِيرٌ لَا يَسْتَطِيعُ أَنْ يَثْبُتَ عَلَى دَابَّتِهِ قَالَ ‏ ‏فَحُجِّي عَنْ أَبِيكِ ‏","","",""],[1722,1722,"","আমরা সেই জনতার সম্বন্ধে বলেছিলাম, যাদের মধ্যে আমরা আগে কখনো সবচেয়ে ভালো ছিলাম, পিপাডির ছেলে একটা গোরানির ছেলে, যে কিনা এক ছেলের ছেলে, যে ভয় পেয়েছিল, সে ভয় পেয়েছিল । ছেলে যে ছেলে ছিল, সে ছিল এক ছেলে যে ছেলে ছেলে ছিল, সে ভাববাদীর সাথে ছিল, তাই ঈশ্বর তাকে জানেন আর সে নেকড়েদের উদ্ধার করেছে আর ভবিষ্যদ্বাণী তার কাছে প্রার্থনা করেছে, সে ঘরে প্রার্থনা করবে যখন সে ভেতরে থাকে... ...কিন্তু সে প্রভুর সাথে বাসায় ফিরে যায় নি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو ابْنُ دِينَارٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏كَانَ يُخْبِرُ ‏ ‏أَنَّ ‏ ‏الْفَضْلَ بْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ دَخَلَ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَيْتَ ‏ ‏وَأَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يُصَلِّ فِي ‏ ‏الْبَيْتِ ‏ ‏حِينَ دَخَلَهُ وَلَكِنَّهُ لَمَّا خَرَجَ فَنَزَلَ ‏ ‏رَكَعَ رَكْعَتَيْنِ عِنْدَ بَابِ ‏ ‏الْبَيْتِ ‏","","",""],[1723,1723,"","আমরা একজন অতিথির কথা বলেছি যার মানে আমার বাবার ছেলে বাবার বাবার জন্য কাজ করে। তিনি একটা ছেলের কাছ থেকে আমাকে বলেছিলেন যে, ঈশ্বর আছেন এমন একটা ছেলে যাকে তিনি যা করেছেন, তা করতে হবে ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا يَعْنِي ابْنَ أَبِي زَائِدَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْدَفَ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏مِنْ ‏ ‏عَرَفَةَ ‏ ‏حَتَّى جَاءَ ‏ ‏جَمْعًا ‏ ‏وَأَرْدَفَ ‏ ‏الْفَضْلَ بْنَ عَبَّاسٍ ‏ ‏مِنْ ‏ ‏جَمْعٍ ‏ ‏حَتَّى جَاءَ ‏ ‏مِنًى ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏وَأَخْبَرَنِي ‏ ‏الْفَضْلُ بْنُ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَزَلْ يُلَبِّي حَتَّى رَمَى الْجَمْرَةَ ‏","","",""],[1724,1724,"","আমরা একটা কুকুর ছেলে সম্পর্কে কথা বলেছি আর মাখন চলে গেছে। একটা ছেলের প্রতিশ্রুতি যে হয়তো তার সবচেয়ে ভালো কাজে আসতে পারে। আমি বলেছি, সে জেনে এবং মজা করে মজা করতে পারে। যারা ছুরির জন্য টাকা দিয়েছে, তারা অনেক দিন ধরে শান্ত ছিল, সে তোমাকে বলেছে, মানুষ কতটা ভীত।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏أَبُو مَعْبَدٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ فِي عَشِيَّةِ ‏ ‏عَرَفَةَ ‏ ‏وَغَدَاةِ ‏ ‏جَمْعٍ ‏ ‏لِلنَّاسِ حِينَ دَفَعُوا ‏ ‏عَلَيْكُمْ السَّكِينَةَ وَهُوَ ‏ ‏كَافٌّ ‏ ‏نَاقَتَهُ حَتَّى إِذَا دَخَلَ ‏ ‏مِنًى ‏ ‏حِينَ هَبَطَ ‏ ‏مُحَسِّرًا ‏ ‏قَالَ عَلَيْكُمْ بِحَصَى ‏ ‏الْخَذْفِ ‏ ‏الَّذِي ‏ ‏يُرْمَى بِهِ الْجَمْرَةُ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُشِيرُ بِيَدِهِ كَمَا يَخْذِفُ الْإِنْسَانُ ‏","","",""],[1725,1725,"","আমরা একটা কুকুর ছেলের কথা বলেছিলাম, যে আমাকে বলেছিল সে ঘুমাতে যাচ্ছে। সে তো লজ্জা পাচ্ছে বলে মনে হচ্ছে না।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏سُلَيْمَانُ بْنُ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ ‏ ‏أَنَّ امْرَأَةً مِنْ ‏ ‏خَثْعَمٍ ‏ ‏قَالَتْ يَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَبِي أَدْرَكَتْهُ فَرِيضَةُ اللَّهِ فِي الْحَجِّ وَهُوَ شَيْخٌ كَبِيرٌ لَا يَسْتَطِيعُ أَنْ يَسْتَوِيَ عَلَى ظَهْرِ بَعِيرِهِ قَالَ ‏ ‏فَحُجِّي عَنْهُ ‏","","",""],[1726,1726,"","আমরা কথা বলেছি, আমি সবচেয়ে ভালো দুটো বিষয় নিয়ে কথা বলেছি, যার জন্য আমি একজন যাজকের হৃদয় হারানোর জুয়া খেলার ছেলের জন্য। ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তার ঋণের জন্য আমি আত্মসমর্পণ করবো। আমি ঈশ্বরকে জিজ্ঞেস করেছিলাম যে, তিনি ও তার মুখকে মুক্ত করবেন ।","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنُ بْنُ الْمُثَنَّى ‏ ‏وَأَبُو أَحْمَدَ يَعْنِي الزُّبَيْرِيَّ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنِي ‏ ‏الْفَضْلُ بْنُ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كُنْتُ رَدِيفَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ أَفَاضَ مِنْ ‏ ‏الْمُزْدَلِفَةِ ‏ ‏وَأَعْرَابِيٌّ يُسَايِرُهُ وَرِدْفُهُ ابْنَةٌ لَهُ حَسْنَاءُ قَالَ ‏ ‏الْفَضْلُ ‏ ‏فَجَعَلْتُ أَنْظُرُ إِلَيْهَا فَتَنَاوَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِوَجْهِي يَصْرِفُنِي عَنْهَا ‏ ‏فَلَمْ يَزَلْ يُلَبِّي حَتَّى رَمَى ‏ ‏جَمْرَةَ الْعَقَبَةِ ‏","","",""],[1727,1727,"","আমরা শিল্পবিদ্যা নিয়ে কথা বলেছি, যেমন আমার কথা শুনেছি, এটা শোনার ব্যাপারে, সে ঈশ্বরের বার্তাবাহকের সাথে গিয়েছিল, প্রার্থনা করেছিল, আর তিনি হতে যাচ্ছেন সে বলেছিল, যখন পাখি সামনে যেতে পারে না অথবা তুমি চাও না।","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عُلَاثَةَ ‏ ‏عَنْ ‏ ‏مَسْلَمَةَ الْجُهَنِيِّ ‏ ‏قَالَ سَمِعْتُهُ يُحَدِّثُ عَنِ ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا فَبَرِحَ ظَبْيٌ فَمَالَ فِي شِقِّهِ فَاحْتَضَنْتُهُ فَقُلْتُ يَا رَسُولَ اللَّهِ تَطَيَّرْتَ قَالَ ‏ ‏إِنَّمَا الطِّيَرَةُ مَا أَمْضَاكَ أَوْ رَدَّكَ ‏","","",""],[1728,1728,"","আমরা একটি দেবীর পুত্র হিসেবে একটি শিক্ষা প্রদান একটি শিশু সন্তানের সন্তানের সন্তানের সন্তানের জন্য একটি শিক্ষা সম্পর্কে কথা বলেছি, তিনি আমার কাছে হস্তান্তর করা হয়েছে তাই তিনি রিং খালি করে দিয়েছেন","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَبَّى حَتَّى رَمَى ‏ ‏جَمْرَةَ الْعَقَبَةِ ‏","","",""],[1729,1729,"","আমরা একটা ছেলে নিয়ে কথা বলেছিলাম যে একটা ভাগ্য নিয়ে ফিরে এসেছে, যদি আমি এটা না মানতে পারি, আমি তাকে জিজ্ঞেস করবো আমি কী ভয় পাই, সে ফাদার বারবারকে বলে দিয়েছে। দুঃখ মায়ের জন্য তোমার আত্মা, তারপর এটা একটা লড়াই, সে তাকে বলেছিল আমি ভবিষ্যদ্বাণীর ব্যাপারে তার কথা শুনি নাই।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏رَجَاءِ بْنِ حَيْوَةَ ‏ ‏قَالَ ‏ ‏بَنَى ‏ ‏يَعْلَى بْنُ عُقْبَةَ ‏ ‏فِي رَمَضَانَ فَأَصْبَحَ وَهُوَ جُنُبٌ فَلَقِيَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَسَأَلَهُ فَقَالَ ‏ ‏أَفْطِرْ قَالَ أَفَلَا أَصُومُ هَذَا الْيَوْمَ وَأُجْزِئُهُ مِنْ يَوْمٍ آخَرَ قَالَ أَفْطِرْ ‏ ‏فَأَتَى ‏ ‏مَرْوَانَ ‏ ‏فَحَدَّثَهُ فَأَرْسَلَ ‏ ‏أَبَا بَكْرِ بْنَ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ ‏ ‏إِلَى ‏ ‏أُمِّ الْمُؤْمِنِينَ ‏ ‏فَسَأَلَهَا فَقَالَتْ قَدْ كَانَ ‏ ‏يُصْبِحُ فِينَا ‏ ‏جُنُبًا ‏ ‏مِنْ غَيْرِ احْتِلَامٍ ثُمَّ يُصْبِحُ صَائِمًا فَرَجَعَ إِلَى ‏ ‏مَرْوَانَ ‏ ‏فَحَدَّثَهُ فَقَالَ الْقَ بِهَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَقَالَ جَارٌ جَارٌ فَقَالَ ‏ ‏أَعْزِمُ عَلَيْكَ ‏ ‏لَتَلْقَانِهِ ‏ ‏بِهِ قَالَ فَلَقِيَهُ فَحَدَّثَهُ فَقَالَ إِنِّي لَمْ أَسْمَعْهُ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا أَنْبَأَنِيهِ ‏ ‏الْفَضْلُ بْنُ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏فَلَمَّا كَانَ بَعْدَ ذَلِكَ لَقِيتُ ‏ ‏رَجَاءً ‏ ‏فَقُلْتُ حَدِيثُ ‏ ‏يَعْلَى ‏ ‏مَنْ حَدَّثَكَهُ قَالَ إِيَّايَ حَدَّثَهُ ‏","","",""],[1730,1730,"","আমরা একটা বোকা ছেলে চেষ্টা করেছি, যে একটা ছেলের কথা বলেছে, প্রভু হলেন সৃষ্টিকর্তা যিনি সবচেয়ে ভালো ছিলেন সমুদ্রের অনুগ্রহে। আমি নিজেকে রক্ষা করতে পারি। তার কথাবার্তার মাধ্যমে আমরা বলেছিলাম যে তুমি তোমার বাবাকে ফোন করেছ.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ هُوَ ابْنُ جَعْفَرٍ ‏ ‏وَرَوْحٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ ‏ ‏أَنَّهُ كَانَ ‏ ‏رَدِيفَ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ النَّحْرِ فَكَانَ ‏ ‏يُلَبِّي حَتَّى رَمَى الْجَمْرَةَ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏فِي الْحَجِّ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏يَعْنِي فِي حَدِيثِهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏يُوسُفَ بْنَ مَاهَكَ ‏ ‏كِلَاهُمَا ‏ ‏قَالَ ‏ ‏ابْنُ مَاهَكَ ‏","","",""],[1731,1731,"","আমরা কামনার সাথে কথা বলেছি, আমার ভালবাসার জন্য আমরা অনেক বার ভালো কাজ করেছি। এটা একটা শিক্ষা যা তিনি সবচেয়ে ভালো ঈশ্বর হিসেবে দিয়েছেন এবং তা পাওয়া যাবে। আমি এটাকে উপস্থাপন করেছি। আমি এটা আমার কল্পনা করি। এটা আমার ভালবাসার জন্য অনেক বার আমরা আমার ভালবাসার সাথে। এটা একটা বিষয়। এটা একটা গুরুত্বপূর্ণ বিষয়। এটা হচ্ছে, এটা হচ্ছে, এটা হলো, এটা আমাদের কাছে এমন এক শিক্ষা যা তিনি অর্জন করেছেন। আমরা যা করতে পারি। আমরা শুধু জানি না, আমরা যদি আমরা শুধু চাই, আমরা শুধু একটা বিষয় নিয়ে আলোচনা করি, এবং আমরা শুধু একটা বিষয় নিয়ে কথা বলি, এবং আমরা যখন আমরা তা করি, আমরা আমাদের কাছে যাই। আমরা শুধু একটা ছোট ছোট ছোট দল, এবং আমরা একে অপরের সাথে ভাগ করি। আমরা একে অপরের সাথে ভাগ করি। আমরা যখন দেখি, তখন আমরা আমাদের কাছে এটা একটা বিষয় হবে। আমরা আমাদের কাছে এটা একটা বিষয় হবে। আমরা আমাদের কাছে এটা একটা বিষয়। কিন্তু আমরা আমাদের কাছে এটা একটা বিষয় হবে। কিন্তু আমরা এর জন্য। আমরা আমাদের কাছে একটা বিষয় হবে। কিন্তু আমরা এর জন্য যা করছি। আমরা যখন আমরা আমাদের কাছে এটা একটি বিষয় হবে, আমরা আমাদের কাছের কথা বলি, এবং আমরা আমাদের কাছে এটা একটি বিষয় হবে। (হাততালি) তার দিকে, ঈশ্বরের ইচ্ছা ছিল তার আর তার পতাকা উদ্ধার করা হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ شِنْظِيرٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏أَنَّهُ كَانَ ‏ ‏رِدْفَ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ النَّحْرِ وَكَانَتْ جَارِيَةٌ خَلْفَ أَبِيهَا فَجَعَلْتُ أَنْظُرُ إِلَيْهَا فَجَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْرِفُ وَجْهِي عَنْهَا ‏ ‏فَلَمْ يَزَلْ مِنْ ‏ ‏جَمْعٍ ‏ ‏إِلَى ‏ ‏مِنًى ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُلَبِّي حَتَّى رَمَى الْجَمْرَةَ يَوْمَ النَّحْرِ ‏","","",""],[1732,1732,"","আমরা দুজন মিলে কয়েকটি বিষয় নিয়ে কথা বলেছিলাম, যা নিয়ে আমি কথা বলছিলাম... ...যেগুলো আমি যাদের নিয়ে কথা বলছিলাম তারা কথা বলতে চাচ্ছি, প্রভু. ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং তার জীবন যাত্রার অন্ধকার থেকে তাকে উঠিয়ে নিয়ে যাওয়া হয়েছিল । ঈশ্বর ঈশ্বর জগতের দর্শন দ্বারা দ্বারা চালিত হয়েছেন ।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏حَدَّثَنِي ‏ ‏عَزْرَةُ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏أَنَّ ‏ ‏الْفَضْلَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّهُ كَانَ ‏ ‏رَدِيفَ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏عَرَفَةَ ‏ ‏فَلَمْ تَرْفَعْ رَاحِلَتُهُ رِجْلَهَا غَادِيَةً حَتَّى بَلَغَ ‏ ‏جَمْعًا ‏ ‏قَالَ ‏ ‏و حَدَّثَنِي ‏ ‏الشَّعْبِيُّ ‏ ‏أَنَّ ‏ ‏أُسَامَةَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّهُ كَانَ ‏ ‏رَدِيفَ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏جَمْعٍ ‏ ‏فَلَمْ تَرْفَعْ رَاحِلَتُهُ رِجْلَهَا غَادِيَةً حَتَّى رَمَى الْجَمْرَةَ ‏","","",""],[1733,1733,"","আমরা কিভাবে একটি ছেলে হয়ে যাবো, তার ছেলে যে কিনা বিশ্বাস নিয়ে ঘুমাবে। আমি সেই ভাববাদী যে তার জন্য প্রার্থনা করেছিল এবং তার সবচেয়ে ভালো এবং ভালো কিছু খেলার জন্য তাকে দিয়েছি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَامَ فِي ‏ ‏الْكَعْبَةِ ‏ ‏فَسَبَّحَ وَكَبَّرَ وَدَعَا اللَّهَ وَاسْتَغْفَرَهُ وَلَمْ يَرْكَعْ وَلَمْ يَسْجُدْ ‏","","",""],[1734,1734,"","আমরা কয়েক বছর ধরে লড়াই করছি... ...ঈশ্বরের অনুগ্রহের সন্তান হিসেবে... ...আর আমি একদলের কাছ থেকে একটি নাম চাই যারা তাকে বলেছিল তার থেকে ভাল তাকে বলুন যে, সে-ই সেই ব্যক্তি নয় যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি । সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি এই ব্যক্তি যিনি ছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ شُجَاعٍ ‏ ‏عَنْ ‏ ‏خُصَيْفٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْدَفَ ‏ ‏أُسَامَةَ ‏ ‏مِنْ ‏ ‏عَرَفَاتٍ ‏ ‏إِلَى ‏ ‏جَمْعٍ ‏ ‏وَأَرْدَفَ ‏ ‏الْفَضْلَ ‏ ‏مِنْ ‏ ‏جَمْعٍ ‏ ‏إِلَى ‏ ‏مِنًى ‏ ‏فَأَخْبَرَهُ بِأَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَزَلْ يُلَبِّي حَتَّى رَمَى ‏ ‏جَمْرَةَ الْعَقَبَةِ ‏","","",""],[1735,1735,"","আমি অনেক ভয় পেয়েছি যে আমরা মাঝে মাঝে চেষ্টা করেছি যখন আমরা একটি ভাল ছেলেকে সাহায্য করার জন্য অনেক সময় পেয়েছি. শান্তি ফিরিয়ে দাও, আর তাকে শান্তি দাও।","‏ ‏أَنْبَأَنَا ‏ ‏كَثِيرُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏فُرَاتٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏أَنَّهُ كَانَ ‏ ‏رَدِيفَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يَزَلْ يُلَبِّي حَتَّى رَمَى ‏ ‏جَمْرَةَ الْعَقَبَةِ ‏","","",""],[1736,1736,"","আমি আমার সবচেয়ে ভালো বন্ধুর সঙ্গে কথা বলেছিলাম কিন্তু এরপর আমরা কয়েক বছর ধরে আমাকে কিনতে চেষ্টা করেছিলাম । ( ২ তীম.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏فُضَيْلِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَوْ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏أَوْ أَحَدِهِمَا عَنْ صَاحِبِهِ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَرَادَ أَنْ يَحُجَّ فَلْيَتَعَجَّلْ فَإِنَّهُ قَدْ تَضِلُّ الضَّالَّةُ وَيَمْرَضُ الْمَرِيضُ وَتَكُونُ الْحَاجَةُ ‏","","",""],[1737,1737,"","বাবার সাথে আমার খেলার গোপন বিষয় নিয়ে কিছু দিন ধরে কথা বলেছি, ভালো অথবা কেউ বলে যে এটা তার জন্য প্রার্থনা করুক আর যার কাছে আমি যেতে পারি, রোগীরা অসুস্থ আর অসুস্থ। ভুল করে তোমার সাহায্য দরকার.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْرَائِيلَ الْعَبْسِيُّ ‏ ‏عَنْ ‏ ‏فُضَيْلِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ ‏ ‏أَوْ ‏ ‏أَحَدِهِمَا ‏ ‏عَنِ ‏ ‏الْآخَرِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَرَادَ الْحَجَّ فَلْيَتَعَجَّلْ فَإِنَّهُ قَدْ يَمْرَضُ الْمَرِيضُ وَتَضِلُّ الضَّالَّةُ وَتَعْرِضُ الْحَاجَةُ ‏","","",""],[1738,1738,"","আমরা আমার ছেলের কথা আবার আমার সাথে দেখা করার চেষ্টা করেছি। তার বাবা বলেছেন, ভাববাদী তার কাছে প্রার্থনা করেছেন যেন তিনি আত্মসমর্পণ করেন বা আমাকে কি বলতে হয়। যদি আমি তা না করি তাহলে আমি মিস করবো না। মা, আমি তাদের জিজ্ঞেস করতে হবে কিভাবে আমি তাদের পালিয়েছি.","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُمَرَ أَبُو الْمُنْذِرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي عَلِيٍّ الزَّرَّادِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏جَعْفَرُ بْنُ تَمَّامِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَتَوْا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ أُتِيَ ‏ ‏فَقَالَ مَا لِي أَرَاكُمْ تَأْتُونِي ‏ ‏قُلْحًا ‏ ‏اسْتَاكُوا ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَفَرَضْتُ عَلَيْهِمْ السِّوَاكَ كَمَا فَرَضْتُ عَلَيْهِمْ الْوُضُوءَ ‏","","",""],[1739,1739,"","আমরা আমার বাবার ছেলে, শিকারী হওয়ার সাহস নিয়ে কথা বলেছি, কিন্তু ঈশ্বর তার কাছে প্রার্থনা করেছেন, তিনি ঈশ্বরের হাত বর্ণনা করেছেন এবং অনেকে আমাকে বলবে যে, ইতোমধ্যে কে করেছে। তারা এটা করবে? তার পিঠ ও রপ্তানির আগে তাকে সাইন করে দাও.","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُفُّ ‏ ‏عَبْدَ اللَّهِ ‏ ‏وَعُبَيْدَ اللَّهِ ‏ ‏وَكَثِيرًا مِنْ ‏ ‏بَنِي الْعَبَّاسِ ‏ ‏ثُمَّ يَقُولُ ‏ ‏مَنْ سَبَقَ إِلَيَّ فَلَهُ كَذَا وَكَذَا قَالَ فَيَسْتَبِقُونَ إِلَيْهِ فَيَقَعُونَ عَلَى ظَهْرِهِ وَصَدْرِهِ فَيُقَبِّلُهُمْ وَيَلْزَمُهُمْ ‏","","",""],[1740,1740,"","আমরা এমন কিছু কথা বলেছি যা আমার বাবার উপর করা উচিত, যেখানে ঈশ্বরের ইচ্ছার উপর রক্ত খোঁজা উচিত। মেঘ হয় অথবা প্রভু ঈশ্বরের কাছে প্রার্থনা করেন এবং তাকে উদ্ধার করা হবে। তার স্বামী মিথ্যা বলবে, কিন্তু সে তার কাছে ফিরে যেতে চায়, সে এমনকি তোমাকে এটা করার উপায়ও দেবে না।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏يَحْيَى بْنُ أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ الْعَبَّاسِ ‏ ‏قَالَ ‏ ‏جَاءَتْ ‏ ‏الْغُمَيْصَاءُ ‏ ‏أَوْ ‏ ‏الرُّمَيْصَاءُ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَشْكُو زَوْجَهَا وَتَزْعُمُ أَنَّهُ لَا يَصِلُ إِلَيْهَا فَمَا كَانَ إِلَّا يَسِيرًا حَتَّى جَاءَ زَوْجُهَا فَزَعَمَ أَنَّهَا كَاذِبَةٌ وَلَكِنَّهَا تُرِيدُ أَنْ تَرْجِعَ إِلَى زَوْجِهَا الْأَوَّلِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ لَكِ ذَلِكَ حَتَّى يَذُوقَ ‏ ‏عُسَيْلَتَكِ ‏ ‏رَجُلٌ غَيْرُهُ ‏","","",""],[1741,1741,"","আমি দুঃখিত, তোমার টাকা আমাদের উপর অনেক কঠিন যে আমি ঈশ্বরের দ্বারা সংরক্ষিত হতে পারে, কিন্তু আমাকে অবশ্যই একটি নির্দিষ্ট ছেলের দ্বারা সুরক্ষিত হতে হবে। এটা হচ্ছে কিভাবে আমরা পরিবর্তন করছি এবং পরিবর্তিত হচ্ছে। আমি কি ভাবি যে ঈশ্বর ভুলে গেছেন তার কথা, অন্ত্যেষ্টিক্রিয়া থেকে পান করুন আর এটা সিনিয়রের কাজ।","‏ ‏أَنْبَأَنَا ‏ ‏أَبُو عَلِيٍّ الْحَسَنُ بْنُ عَلِيِّ بْنِ مُحَمَّدِ بْنِ الْمُذْهِبِ الْوَاعِظُ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏أَبُو بَكْرٍ أَحْمَدُ بْنُ جَعْفَرِ بْنِ حِمْدَانَ بْنِ مَالِكٍ ‏ ‏قِرَاءَةً عَلَيْهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد بْن مُحَمَّد بْن حَنْبَلٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏مِنْ كِتَابِهِ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏وَمُغِيرَةُ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَرِبَ مِنْ ‏ ‏زَمْزَمَ ‏ ‏وَهُوَ قَائِمٌ ‏","","",""],[1742,1742,"","আমরা এমন কিছু কথা বলেছি, যার জন্য আমরা একটা ছেলের নাম খুঁজছি যে মারা গেছে। সে ঈশ্বরের কাছে কিছু একটা ছেড়ে দেবে আর তুমি আমাকে হত্যা করেছ ভবিষ্যদ্বাণীর ব্যাপারে ওর কাছে প্রার্থনা করলে সে আমাকে একটা প্রতিজ্ঞা করবে।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏أَجْلَحُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْأَصَمِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَجُلًا قَالَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا شَاءَ اللَّهُ وَشِئْتَ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَجَعَلْتَنِي وَاللَّهَ ‏ ‏عَدْلًا ‏ ‏بَلْ مَا شَاءَ اللَّهُ وَحْدَهُ ‏","","",""],[1743,1743,"","আমরা একজন অমরের কথা বলেছি যে ভাববাদীর ছেলে সম্পর্কে জানে, যিনি বিচারের জন্য বিখ্যাত।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏مَسَحَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأْسِي وَدَعَا لِي بِالْحِكْمَةِ ‏","","",""],[1744,1744,"","আমরা একটি সাধারণ উদ্বেগ কথা বলেছি যে আমার বাবা একটি পুত্র সন্তানের সন্তানের সন্তানের সম্পর্কে শেখার শিকারী যে তার প্রার্থনা উলের মধ্যে দিয়ে উড়ে যায় এবং তিনি তার সাথে বলেছেন যে তিনি ছিলেন কিন্তু আমরা বেবস থেকে এসেছি, যে আমার প্রাণ বাঁচার প্রয়োজন নেই।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَافَ ‏ ‏بِالْبَيْتِ ‏ ‏وَهُوَ عَلَى بَعِيرِهِ ‏ ‏وَاسْتَلَمَ ‏ ‏الْحَجَرَ ‏ ‏بِمِحْجَنٍ ‏ ‏كَانَ مَعَهُ قَالَ وَأَتَى السِّقَايَةَ ‏ ‏فَقَالَ اسْقُونِي فَقَالُوا إِنَّ هَذَا يَخُوضُهُ النَّاسُ وَلَكِنَّا ‏ ‏نَأْتِيكَ بِهِ مِنْ الْبَيْتِ فَقَالَ ‏ ‏لَا حَاجَةَ لِي فِيهِ اسْقُونِي مِمَّا يَشْرَبُ مِنْهُ النَّاسُ ‏","","",""],[1745,1745,"","আমার বাবার কথা বলেছি, বেনকে ধন্যবাদ, একজন যাজকের ছেলে দিয়ে সাহায্য করার জন্য যে তার নিজের বাবার কাছে প্রার্থনা করতো, সেটা নয়।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ الْخَبَرُ كَالْمُعَايَنَةِ ‏","","",""],[1746,1746,"","আমরা বাবার সঙ্গে একটা গেম তৈরি করার জন্য একটা ভালো কাপুরুষকে সাহায্য করার বিষয়ে কথা বলেছিলাম । তার প্রার্থনা আমাকে সঠিক সিদ্ধান্ত নিতে না দিলে সে একটা পাপ নিয়ে যায়।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏بِتُّ لَيْلَةً عِنْدَ خَالَتِي ‏ ‏مَيْمُونَةَ بِنْتِ الْحَارِثِ ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَهَا فِي لَيْلَتِهَا ‏ ‏فَقَامَ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ فَقُمْتُ عَنْ يَسَارِهِ لِأُصَلِّيَ بِصَلَاتِهِ قَالَ فَأَخَذَ ‏ ‏بِذُؤَابَةٍ ‏ ‏كَانَتْ لِي ‏ ‏أَوْ بِرَأْسِي ‏ ‏حَتَّى جَعَلَنِي عَنْ يَمِينِهِ ‏","","",""],[1747,1747,"","আমরা কতবার দেখেছি, আপনার শহরের নীরবতা আর তার কান্নার জন্য... ...তার প্রভুর ক্ষমতা নিয়ে তার কাছে প্রার্থনা করেছেন, তার অনুগ্রহে আত্মসমর্পণ করেছেন। তিনি হারিয়ে যান এবং তাকে কখনোই বলা হয়নি যে, ঈর্ষাপরায়ণ লোকেদের একটা শব্দ আছে ।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا خُيِّرَتْ ‏ ‏بَرِيرَةُ ‏ ‏رَأَيْتُ زَوْجَهَا يَتْبَعُهَا فِي ‏ ‏سِكَكِ ‏ ‏الْمَدِينَةِ ‏ ‏وَدُمُوعُهُ تَسِيلُ عَلَى لِحْيَتِهِ فَكُلِّمَ ‏ ‏الْعَبَّاسُ ‏ ‏لِيُكَلِّمَ فِيهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِبَرِيرَةَ ‏ ‏إِنَّهُ زَوْجُكِ فَقَالَتْ تَأْمُرُنِي بِهِ يَا رَسُولَ اللَّهِ قَالَ إِنَّمَا أَنَا ‏ ‏شَافِعٌ ‏ ‏قَالَ فَخَيَّرَهَا فَاخْتَارَتْ نَفْسَهَا ‏ ‏وَكَانَ عَبْدًا لِآلِ ‏ ‏الْمُغِيرَةِ ‏ ‏يُقَالُ لَهُ ‏ ‏مُغِيثٌ ‏","","",""],[1748,1748,"","আমরা বাবার কথা বলেছি, আমার বাবার কাছে কৃতজ্ঞ, একজন কাপুরুষের জন্য সাহায্যের জন্য... ...যে ঈশ্বরের কাছে প্রার্থনা করেছে, সে বলল, ঈশ্বর কি করছেন।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ ‏ ‏ذَرَارِيِّ ‏ ‏الْمُشْرِكِينَ فَقَالَ ‏ ‏اللَّهُ أَعْلَمُ بِمَا كَانُوا عَامِلِينَ ‏","","",""],[1749,1749,"","তিনি আমাদের কাছে পৌঁছে দিয়েছিলেন এবং পাঁচ বছর ছয় বছর ধরে একজন ছেলে ।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مِهْرَانَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قُبِضَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ابْنُ خَمْسٍ وَسِتِّينَ ‏","","",""],[1750,1750,"","আমরা আবেগ নিয়ে কথা বলেছি যে আমরা একটা পয়সা পার হয়েছি... ...যে মহান রান্নার পুত্র... ...তার জন্য... যাজক আর আমি তার মত সবকিছু অনুভব করব.","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏الطَّعَامُ الَّذِي نَهَى عَنْهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُبَاعَ حَتَّى يُقْبَضَ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏وَأَحْسَبُ كُلَّ شَيْءٍ مِثْلَهُ ‏","","",""],[1751,1751,"","আমরা একটা ছেলের প্রতি আসক্তির কথা বলেছি যে ঈশ্বরের কাছে পাপ করেছে তাকে আত্মসমর্পণ করতে হবে আর বলতে হবে যে সে যুদ্ধকে রহস্য জয় করতে পারবে না আর তারপর সে আর যেতে দেবে না।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏خَطَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏إِذَا لَمْ يَجِدْ الْمُحْرِمُ ‏ ‏إِزَارًا ‏ ‏فَلْيَلْبَسْ السَّرَاوِيلَ وَإِذَا لَمْ يَجِدْ النَّعْلَيْنِ فَلْيَلْبَسْ الْخُفَّيْنِ ‏","","",""],[1752,1752,"","আমরা এমন কিছু কথা বলেছি যা আমার বাবার থেকে বেশি বলা হয়েছে... ...যে কিনা লর্ডকে জিতেছে. আর সে গোসল করে আর সে একটা বধির যুদ্ধলক.","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْتَجَمَ ‏ ‏وَهُوَ ‏ ‏مُحْرِمٌ ‏ ‏صَائِمٌ ‏","","",""],[1753,1753,"","আমরা এমন কিছু কথা বলেছি যা আমার বাবা একজন মানুষের ছেলে যার সাথে ঈশ্বরের সম্পর্ক আছে তার জন্য একটা ভালো কাপুরুষের সাথে সুখী হতে হবে। তার পতাকা তার গল্পকে আত্মসমর্পণ করবে, তার বিতর্ক হচ্ছে যুদ্ধবিগ্রহ। ওকে ওর জামায় থামাও আর ওকে এত সুন্দর করে স্পর্শ করো না।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَجُلًا كَانَ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَقَصَتْهُ ‏ ‏نَاقَتُهُ وَهُوَ مُحْرِمٌ فَمَاتَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اغْسِلُوهُ بِمَاءٍ ‏ ‏وَسِدْرٍ ‏ ‏وَكَفِّنُوهُ فِي ثَوْبَيْهِ وَلَا تَمَسُّوهُ بِطِيبٍ وَلَا ‏ ‏تُخَمِّرُوا ‏ ‏رَأْسَهُ فَإِنَّهُ يُبْعَثُ يَوْمَ الْقِيَامَةِ ‏ ‏مُلَبِّيًا ‏","","",""],[1754,1754,"","আমরা আমার বাবার সাথে ঘোড়ার কথা বলেছিলাম... ...আমার বাবার সাথে দুই ঘোড়া নিয়ে... ...একটা যাজকের ছেলে বানানোর জন্য... ...যে বলেছে ঈশ্বর তাকে শিখিয়েছিলেন আর গাথতোকে আমার কাছে তার মালপত্রের টাকা আছে, যেমন... যাই হোক না কেন, ঋণের আগে, যখন তুমি ঋণের আগে ছিলে।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ حُصَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَدَاةَ ‏ ‏جَمْعٍ ‏ ‏هَلُمَّ الْقُطْ لِي فَلَقَطْتُ لَهُ حَصَيَاتٍ مِنْ حَصَى ‏ ‏الْخَذْفِ ‏ ‏فَلَمَّا وَضَعَهُنَّ فِي يَدِهِ قَالَ نَعَمْ بِأَمْثَالِ هَؤُلَاءِ وَإِيَّاكُمْ ‏ ‏وَالْغُلُوَّ ‏ ‏فِي الدِّينِ فَإِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ بِالْغُلُوِّ فِي الدِّينِ ‏","","",""],[1755,1755,"","আমরা স্যারের ছেলের কথা বলেছি ঈশ্বরের দোহাই আর শান্তির জন্য প্রার্থনা করছে, আর শহর জিতেনি দুই বার ফিরে এসো।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَافَرَ مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏لَا يَخَافُ إِلَّا اللَّهَ عَزَّ وَجَلَّ فَصَلَّى رَكْعَتَيْنِ رَكْعَتَيْنِ حَتَّى رَجَعَ ‏","","",""],[1756,1756,"","আমরা একটা ভাল কাপুরুষকে সাহায্য করার কথা বলেছিলাম... ...যে ধার্মিকদের জয় করেছে, তাকে একটা রাজ্য দিয়ে আত্মসমর্পণ করতে হবে যা জানা যাবে না ( লূক ১১: ১৩) আপনার প্রার্থনা এবং নির্ভীকভাবে এই বলে বলা যায় যে, রাজার বিরুদ্ধে লড়াই করার ক্ষমতা ঈশ্বরের রয়েছে । দুঃখ প্রকাশ করছি, আমি চেষ্টা করছি আপনি তাদের সম্পর্কে এমনকি আপনি শুনতে না এবং আপনি শান্ত হবেন না.","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏نَزَلَتْ هَذِهِ الْآيَةُ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُتَوَارٍ ‏ ‏بِمَكَّةَ ‏ { ‏وَلَا تَجْهَرْ بِصَلَاتِكَ وَلَا ‏ ‏تُخَافِتْ ‏ ‏بِهَا ‏} ‏قَالَ وَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى بِأَصْحَابِهِ رَفَعَ صَوْتَهُ بِالْقُرْآنِ فَلَمَّا سَمِعَ ذَلِكَ الْمُشْرِكُونَ سَبُّوا الْقُرْآنَ وَسَبُّوا مَنْ أَنْزَلَهُ وَمَنْ جَاءَ بِهِ قَالَ فَقَالَ اللَّهُ عَزَّ وَجَلَّ لِنَبِيِّهِ ‏ { ‏وَلَا تَجْهَرْ بِصَلَاتِكَ ‏} ‏أَيْ بِقِرَاءَتِكَ فَيَسْمَعَ الْمُشْرِكُونَ فَيَسُبُّوا الْقُرْآنَ ‏ { ‏وَلَا ‏ ‏تُخَافِتْ ‏ ‏بِهَا ‏} ‏عَنْ أَصْحَابِكَ فَلَا تُسْمِعُهُمْ الْقُرْآنَ حَتَّى يَأْخُذُوهُ عَنْكَ ‏ { ‏وَابْتَغِ بَيْنَ ذَلِكَ ‏ ‏سَبِيلًا ‏ }","","",""],[1757,1757,"","আমরা একটা কথা বলেছি, যা আমি বাবার বাবার কাছে ফিরে যাচ্ছি... ...তার বাবার গডফাদারের কাছে, যে ছেলে তাকে স্পর্শ করতে সক্ষম হয়েছে, সে আমার গোলাপ লর্ডকে দিয়ে দিচ্ছে। বাবা-মা বলেছে এটা আমার দিন। আর এটা হচ্ছে ডাবলক্রসিং ইভেন্ট যা দ্বিতীয় বারের স্বাদের গন্ধ। এই লেখাটা আমি যখন বিদায় নিচ্ছি তখন আমি তার বক্তব্যের কথা মেনে নিতাম। সে আমাকে ভয় দেখাচ্ছে, মানে আমি একটা হাস্যকর জিনিস নিয়ে কেঁদেছি, আর সে কেঁদেছে।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏دَاوُدُ بْنُ أَبِي هِنْدٍ ‏ ‏عَنِ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ ‏ ‏بِوَادِي الْأَزْرَقِ ‏ ‏فَقَالَ ‏ ‏أَيُّ وَادٍ هَذَا قَالُوا هَذَا ‏ ‏وَادِي الْأَزْرَقِ ‏ ‏فَقَالَ كَأَنِّي أَنْظُرُ إِلَى ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَهُوَ هَابِطٌ مِنْ ‏ ‏الثَّنِيَّةِ ‏ ‏وَلَهُ ‏ ‏جُؤَارٌ ‏ ‏إِلَى اللَّهِ عَزَّ وَجَلَّ بِالتَّلْبِيَةِ حَتَّى أَتَى عَلَى ‏ ‏ثَنِيَّةِ هَرْشَاءَ ‏ ‏فَقَالَ أَيُّ ‏ ‏ثَنِيَّةٍ ‏ ‏هَذِهِ قَالُوا ‏ ‏ثَنِيَّةُ هَرْشَاءَ ‏ ‏قَالَ كَأَنِّي أَنْظُرُ إِلَى ‏ ‏يُونُسَ بْنِ مَتَّى ‏ ‏عَلَى نَاقَةٍ حَمْرَاءَ ‏ ‏جَعْدَةٍ ‏ ‏عَلَيْهِ ‏ ‏جُبَّةٌ ‏ ‏مِنْ صُوفٍ ‏ ‏خِطَامُ ‏ ‏نَاقَتِهِ ‏ ‏خُلْبَةٌ ‏ ‏قَالَ ‏ ‏هُشَيْمٌ ‏ ‏يَعْنِي لِيفٌ ‏ ‏وَهُوَ يُلَبِّي ‏","","",""],[1758,1758,"","আমরা আমার বাবা একজন যাজকের চেয়ে ভালো হওয়ার কথা বলেছি, ঈশ্বর আদেশ দিয়েছেন আর আমি তার ঋণ দিনের দিক থেকে তার ঋণ অনুভব করবো আর তারপর আপনি রক্তটা তার জন্য নিতে বলছেন সংরক্ষণ.","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏أَصْحَابُنَا مِنْهُمْ ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي حَسَّانَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشْعَرَ ‏ ‏بَدَنَتَهُ ‏ ‏مِنْ الْجَانِبِ الْأَيْمَنِ ثُمَّ ‏ ‏سَلَتَ ‏ ‏الدَّمَ عَنْهَا ‏ ‏وَقَلَّدَهَا ‏ ‏نَعْلَيْنِ ‏","","",""],[1759,1759,"","আমরা একটি সাধারণ উদ্বেগ কথা বলেছি যে আমাদের বাবার চেয়েও বেশি কিছু হতে হবে একটি শরীরের পুত্র শিকারী, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং একজন যুদ্ধ এবং একটি যুদ্ধলক আছে কে একজন যোদ্ধা আর সে একজন যুদ্ধেরলক।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏يَزِيدُ بْنُ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏الصَّعْبَ بْنَ جَثَّامَةَ الْأَسْدِيَّ ‏ ‏أَهْدَى إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رِجْلَ حِمَارِ وَحْشٍ وَهُوَ مُحْرِمٌ فَرَدَّهُ وَقَالَ إِنَّا مُحْرِمُونَ ‏","","",""],[1760,1760,"","আমরা একটি ছেলেকে দেয়া একটি দর্শন সম্পর্কে কথা বলেছি যে ঈশ্বরের কাছে প্রার্থনা করেছে।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَمَّنْ حَلَقَ قَبْلَ أَنْ يَذْبَحَ وَنَحْوِ ذَلِكَ فَجَعَلَ يَقُولُ لَا ‏ ‏حَرَجَ ‏ ‏لَا ‏ ‏حَرَجَ ‏","","",""],[1761,1761,"","আমরা একটা ছেলের কথা বলেছিলাম যে হয়তো ঈশ্বর আমার ছেলের ব্যাপারে কিছু বলেছে, সে এমন কিছু বলার আগেই সে তার আঙ্গুল থেকে কিছু বের হয়ে আসতে বলেছিল যেটা সে বলতে পারে যে লজ্জা পাবে না।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَمَّنْ قَدَّمَ مِنْ ‏ ‏نُسُكِهِ ‏ ‏شَيْئًا قَبْلَ شَيْءٍ فَجَعَلَ يَقُولُ لَا ‏ ‏حَرَجَ ‏","","",""],[1762,1762,"","আমরা বাবার চেয়ে ভালো স্বপ্নের কথা বলেছি, আমার বাবার একজন মহান পুত্র যিনি ঈশ্বরের অনুগ্রহে মহান। তারা দুজন ছাত্রকে ক্ষমা করেছে যারা বলেছে যে পুরুষ ও ছোট বাচ্চাদের আছে। ৩ জন আর বাকি চারজনকে মেরে ফেলো, আর ছোটগুলো নয়।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اللَّهُمَّ اغْفِرْ لِلْمُحَلِّقِينَ فَقَالَ رَجُلٌ وَلِلْمُقَصِّرِينَ فَقَالَ اللَّهُمَّ اغْفِرْ لِلْمُحَلِّقِينَ فَقَالَ الرَّجُلُ وَلِلْمُقَصِّرِينَ فَقَالَ فِي الثَّالِثَةِ ‏ ‏أَوْ الرَّابِعَةِ ‏ ‏وَلِلْمُقَصِّرِينَ ‏","","",""],[1763,1763,"","আমরা রাজার আদর্শের কথা বলেছি একটি ছেলেকে তার ভালোবাসার জন্য... ...ঈশ্বরের কাছে প্রার্থনা করা হয়েছে. যাজক যিনি একটি ক্র্যাডেল নিক্ষেপ চেষ্টা করা হয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفَاضَ ‏ ‏مِنْ ‏ ‏عَرَفَاتٍ ‏ ‏وَرِدْفُهُ ‏ ‏أُسَامَةُ ‏ ‏وَأَفَاضَ ‏ ‏مِنْ ‏ ‏جَمْعٍ ‏ ‏وَرِدْفُهُ ‏ ‏الْفَضْلُ بْنُ عَبَّاسٍ ‏ ‏قَالَ وَلَبَّى حَتَّى رَمَى ‏ ‏جَمْرَةَ الْعَقَبَةِ ‏","","",""],[1764,1764,"","আমরা বাবার কথা বলেছি, আমি কৃতজ্ঞ যে একটা কাপুরুষের জন্য... ...যে মারা গেছে তার জন্য। তোমার আশীর্বাদ প্রভুর কাছে বেঁচে যাবে। আত্মসমর্পণ করেছে, সে তোমার কথা বলেছে, আমার কল্পনার জন্য সে তোমার মৃত্যু ঘটিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ امْرَأَةً ‏ ‏رَكِبَتْ الْبَحْرَ فَنَذَرَتْ إِنْ اللَّهُ تَبَارَكَ وَتَعَالَى أَنْجَاهَا أَنْ تَصُومَ شَهْرًا فَأَنْجَاهَا اللَّهُ عَزَّ وَجَلَّ فَلَمْ تَصُمْ حَتَّى مَاتَتْ فَجَاءَتْ قَرَابَةٌ لَهَا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَتْ ذَلِكَ لَهُ فَقَالَ صُومِي ‏","","",""],[1765,1765,"","আমরা আমার ক্লাসের লোকদের কথা বলেছি... ...একটা বাচ্চা ছেলের ইঁদুরের ব্যাপারে জানার চেষ্টা করছি। ফিরে যেতে, আমার বাবা, তার কাছে প্রার্থনা করেছিলেন এবং তাকে উদ্ধার করেছিলেন","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ الطُّفَاوِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ سَلَمَةَ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏بِمَكَّةَ ‏ ‏فَقُلْتُ ‏ ‏إِنَّا إِذَا كُنَّا مَعَكُمْ صَلَّيْنَا أَرْبَعًا وَإِذَا رَجَعْنَا إِلَى ‏ ‏رِحَالِنَا ‏ ‏صَلَّيْنَا رَكْعَتَيْنِ قَالَ تِلْكَ سُنَّةُ ‏ ‏أَبِي الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1766,1766,"","আমরা একটা ছেলের কথা বলেছি যে তার ছেলেকে চিহ্নিত করবে, ঈশ্বর তার কাছে প্রার্থনা করেছেন আর তার গর্ভের মধ্যে থাকা অবস্থায়ই তিনি ছিলেন।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ يَعْنِي ابْنَ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُتَّخَذَ ذُو الرُّوحِ ‏ ‏غَرَضًا ‏","","",""],[1767,1767,"","আমরা একজন যাজকের সাথে কথা বলেছি যিনি সূর্য থেকে ভাগ হয়ে এসেছেন। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তাকে ছেড়ে চলে গেছেন। এরপর দুই নতুন বন্ধু খুঁজে পায় এবং দুটি স্থানে দুটি মসজিদ স্থাপন করা হয়।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ يَعْنِي ابْنَ يُوسُفَ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏خُصَيْفٍ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَسَفَتِ الشَّمْسُ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابُهُ ‏ ‏فَقَرَأَ سُورَةً طَوِيلَةً ثُمَّ رَكَعَ ثُمَّ رَفَعَ رَأْسَهُ فَقَرَأَ ثُمَّ رَكَعَ وَسَجَدَ سَجْدَتَيْنِ ثُمَّ قَامَ فَقَرَأَ وَرَكَعَ ثُمَّ سَجَدَ سَجْدَتَيْنِ أَرْبَعَ رَكَعَاتٍ وَأَرْبَعَ سَجَدَاتٍ فِي رَكْعَتَيْنِ ‏","","",""],[1768,1768,"","আমরা আমাদের দুই জীবন একজন ছেলের শিক্ষক থেকে চুরি করার চেষ্টা করেছি, আমি কখনোই ভাববাদীকে তার কাছে প্রার্থনা করতে দিবো না। আর আমি তাকে অন্যকারো কাছ থেকে এটা দিয়ে দেব। তিনি বলেছিলেন যে, একজন যাজকের ছেলেই প্রথম মারা যাবে ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ الْبَطِينِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا ‏ ‏أُخْرِجَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏مَكَّةَ ‏ ‏قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏أَخْرَجُوا نَبِيَّهُمْ إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ لَيَهْلِكُنَّ فَنَزَلَتْ ‏ { ‏أُذِنَ لِلَّذِينَ يُقَاتَلُونَ بِأَنَّهُمْ ظُلِمُوا وَإِنَّ اللَّهَ عَلَى نَصْرِهِمْ لَقَدِيرٌ ‏} ‏قَالَ فَعُرِفَ أَنَّهُ سَيَكُونُ قِتَالٌ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏هِيَ أَوَّلُ آيَةٍ نَزَلَتْ فِي الْقِتَالِ ‏","","",""],[1769,1769,"","আমরা আমাদের হৃদয়ের দাসকে বলেছি, যে কিনা ঈশ্বরকে জিজ্ঞেস করেছে, যে কিনা এটা জানার জন্য যে কিনা এটা করেছে। অত্যাচারের শিকার হওয়া মানে, সে নিজেই নিজের দুর্দশা এবং স্বপ্নের উপর আঘাত করে। কীভাবে তাকে রক্ষা করতে হয় তা শোনার এবং তাকে বাঁচানোর উপায় বের করার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَوَّرَ صُورَةً عُذِّبَ يَوْمَ الْقِيَامَةِ حَتَّى يَنْفُخَ فِيهَا وَلَيْسَ بِنَافِخٍ وَمَنْ ‏ ‏تَحَلَّمَ ‏ ‏عُذِّبَ يَوْمَ الْقِيَامَةِ حَتَّى يَعْقِدَ شَعِيرَتَيْنِ وَلَيْسَ عَاقِدًا وَمَنْ اسْتَمَعَ إِلَى حَدِيثِ قَوْمٍ يَفِرُّونَ بِهِ مِنْهُ صُبَّ فِي أُذُنَيْهِ يَوْمَ الْقِيَامَةِ عَذَابٌ ‏","","",""],[1770,1770,"","আমি ঈশ্বরের কাছে অনুরোধ করছি সে যেন মুক্তি পায়, আর যদি শুধু বলতেই হয় যে, সে আমাদের কখনো শেষ করে ফেলবে না, নিজের দেশেও আছি, কখনো কোন ক্ষতি করো না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ الصَّمَدِ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ الْغَطَفَانِيِّ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ أَنَّ أَحَدَهُمْ إِذَا ‏ ‏أَتَى ‏ ‏أَهْلَهُ قَالَ بِسْمِ اللَّهِ اللَّهُمَّ جَنِّبْنِي الشَّيْطَانَ وَجَنِّبْ الشَّيْطَانَ مَا رَزَقْتَنَا فَإِنْ قُدِرَ بَيْنَهُمَا فِي ذَلِكَ وَلَدٌ لَمْ يَضُرَّ ذَلِكَ الْوَلَدَ الشَّيْطَانُ أَبَدًا ‏","","",""],[1771,1771,"","আমি শুনেছি যে তারা আমার বাবার সাথে এমন করেছে, কিন্তু আমি নিশ্চিত নই আমি একটা বাচ্চা পাব কিনা। সে ঈশ্বরের কাছে প্রার্থনা করছে এবং তা উদ্ধার করবে। দু বছর এবং তাকে প্রত্যেক পরিচিত ও সময়ের সেবা করার জন্য বলা হয়েছে । বিজ্ঞান।","‏ ‏حَدَّثَنِي ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمِنْهَالِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏وَالنَّاسُ ‏ ‏يُسَلِّفُونَ ‏ ‏فِي التَّمْرِ الْعَامَ وَالْعَامَيْنِ ‏ ‏أَوْ قَالَ عَامَيْنِ وَالثَّلَاثَةَ ‏ ‏فَقَالَ ‏ ‏مَنْ ‏ ‏سَلَّفَ ‏ ‏فِي تَمْرٍ ‏ ‏فَلْيُسَلِّفْ ‏ ‏فِي كَيْلٍ مَعْلُومٍ وَوَزْنٍ مَعْلُومٍ ‏","","",""],[1772,1772,"","আমি একজন যাজকের ছেলের কথা বলেছিলাম যে কিনা ঈশ্বরের অনুগ্রহে ছিল। সে আমাকে ডজন খানেক বার একজন মানুষের সাথে পরিচয় করিয়ে দিল, তারপর আমি তার আদেশে এটা করবো। আর তারপর এমন হবে, সে আমার বাবার কাছ থেকে একটা কুত্তার বাচ্চাের কথা শোনেনি।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَنْبَأَنَا ‏ ‏أَبُو التَّيَّاحِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ سَلَمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ بِثَمَانِي عَشْرَةَ ‏ ‏بَدَنَةً ‏ ‏مَعَ رَجُلٍ فَأَمَرَهُ فِيهَا بِأَمْرِهِ فَانْطَلَقَ ثُمَّ رَجَعَ إِلَيْهِ فَقَالَ أَرَأَيْتَ إِنْ ‏ ‏أَزْحَفَ ‏ ‏عَلَيْنَا مِنْهَا شَيْءٌ فَقَالَ ‏ ‏انْحَرْهَا ثُمَّ اصْبُغْ نَعْلَهَا فِي دَمِهَا ثُمَّ اجْعَلْهَا عَلَى ‏ ‏صَفْحَتِهَا ‏ ‏وَلَا تَأْكُلْ مِنْهَا أَنْتَ وَلَا أَحَدٌ مِنْ أَهْلِ رُفْقَتِكَ ‏ ‏وَلَمْ يَسْمَعْ ‏ ‏إِسْمَاعِيلُ ابْنُ عُلَيَّةَ ‏ ‏مِنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏إِلَّا هَذَا الْحَدِيثَ ‏","","",""],[1773,1773,"","সে বলেছিল সে কি বলেছে আমি তার কথা বলেছি যে আমি ভালো ছেলে হতে পেরে খুশির কথা শুনতে পাইনি। একজন জিনিয়াসের ছেলে যিনি জানেন এবং ধূসর খেতেন এবং সে ঈশ্বরের দোহাই মেরেছেন। এক ছেলের সাথে নির্যাতন করা","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏قَالَ ‏ ‏لَا أَدْرِي أَسَمِعْتُهُ مِنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏أَمْ نُبِّئْتُهُ عَنْهُ ‏ ‏قَالَ ‏ ‏أَتَيْتُ عَلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏بِعَرَفَةَ ‏ ‏وَهُوَ يَأْكُلُ رُمَّانًا فَقَالَ ‏ ‏أَفْطَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعَرَفَةَ ‏ ‏وَبَعَثَتْ إِلَيْهِ ‏ ‏أُمُّ الْفَضْلِ ‏ ‏بِلَبَنٍ فَشَرِبَهُ ‏","","",""],[1774,1774,"","আর তিনি বললেন, \"ঈশ্বর, তারা তালের সেরা দিন এবং ভদ্র পোশাকের জন্য করেছে।","‏ ‏و قَالَ ‏ ‏لَعَنَ اللَّهُ فُلَانًا عَمَدُوا إِلَى أَعْظَمِ أَيَّامِ الْحَجِّ فَمَحَوْا زِينَتَهُ وَإِنَّمَا زِينَةُ الْحَجِّ التَّلْبِيَةُ ‏","","",""],[1775,1775,"","সে বলেছে আমি তাদেরকে আগুনে পুড়িয়ে ছাঁতে চাই না আর যদি ঈশ্বর তার জন্য প্রার্থনা করেন, তাহলে তিনি তার কথা বলে দেবেন। তার কাছে এবং তার ঋণের কারণে যে - ব্যক্তি তাকে হত্যা করেছিলেন, তাকে তিনি হত্যা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏حَرَّقَ نَاسًا ارْتَدُّوا عَنْ الْإِسْلَامِ فَبَلَغَ ذَلِكَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَقَالَ لَمْ أَكُنْ لِأُحَرِّقَهُمْ بِالنَّارِ وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُعَذِّبُوا بِعَذَابِ اللَّهِ وَكُنْتُ قَاتِلَهُمْ لِقَوْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ بَدَّلَ دِينَهُ فَاقْتُلُوهُ فَبَلَغَ ذَلِكَ ‏ ‏عَلِيًّا ‏ ‏كَرَّمَ اللَّهُ وَجْهَهُ فَقَالَ وَيْحَ ‏ ‏ابْنِ أُمِّ ابْنِ عَبَّاسٍ ‏","","",""],[1776,1776,"","আমরা কীভাবে ঈশ্বরকে তাঁর কাজ করতে বলা হয়েছিল, সেই বিষয়ে আমরা কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ لَنَا مَثَلُ السُّوءِ الْعَائِدُ فِي هِبَتِهِ كَالْكَلْبِ يَعُودُ فِي قَيْئِهِ ‏","","",""],[1777,1777,"","আমরা কয়েকদিন ধরে বাপ্তাইজিত হয়েছি, আমরা এক কাপুরুষকে সাহায্য করতে পেরেছি যে কিনা জিতবেন, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আমার আত্মা দান করবেন যে তিনি সন্তুষ্ট রানীর ইচ্ছা.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ ‏إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نُعِيَتْ إِلَيَّ نَفْسِي بِأَنَّهُ مَقْبُوضٌ فِي تِلْكَ السَّنَةِ ‏","","",""],[1778,1778,"","আমরা কথা বলেছি একজন যাজকের ছেলেকে দেয়ার চেয়ে... ...আর তিনি বলেছিলেন তিনি লর্ড লর্ডের পালনকর। তিনি দুটি প্রার্থনা অন্ধকার আর বাসা আর সন্ধ্যায় একত্রিত করেছেন রাগ.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَجْمَعُ بَيْنَ الصَّلَاتَيْنِ فِي السَّفَرِ الْمَغْرِبِ وَالْعِشَاءِ وَالظُّهْرِ وَالْعَصْرِ ‏","","",""],[1779,1779,"","আমরা একটা স্বপ্নের কথা বলেছি, যে আমার বাবাকে ছেড়ে দিবে, তার বাবাকে তার কাছে প্রার্থনা করলো। আর তার বাবার মঙ্গলের জন্য সে তার বাবার কাছে প্রার্থনা করল। তুমি কি করে অসুস্থ হয়ে যাচ্ছ? সে অনেক চেষ্টা করে একটা গুরুত্বপূর্ণ জায়গা তৈরি করার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَلْعُونٌ مَنْ سَبَّ أَبَاهُ مَلْعُونٌ مَنْ سَبَّ أُمَّهُ مَلْعُونٌ مَنْ ذَبَحَ لِغَيْرِ اللَّهِ مَلْعُونٌ مَنْ غَيَّرَ ‏ ‏تُخُومَ ‏ ‏الْأَرْضِ مَلْعُونٌ مَنْ ‏ ‏كَمَهَ ‏ ‏أَعْمَى عَنْ طَرِيقٍ مَلْعُونٌ مَنْ ‏ ‏وَقَعَ ‏ ‏عَلَى بَهِيمَةٍ مَلْعُونٌ مَنْ عَمِلَ بِعَمَلِ قَوْمِ ‏ ‏لُوطٍ ‏","","",""],[1780,1780,"","আমরা একটা স্বপ্নের কথা বলেছি একটা ছেলে যে দুটো ঘোড়ার মধ্য দিয়ে চলে গেছে, ভগবান তার কাছে প্রার্থনা করেছে আর তার মেয়ের পাপ সে তার বাবার সাথে ঝড়ে নিয়ে যাবে ঈশ্বরের দয়া।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ حُصَيْنٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏رَدَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَيْنَبَ ‏ ‏ابْنَتَهُ عَلَى زَوْجِهَا ‏ ‏أَبِي الْعَاصِ بْنِ الرَّبِيعِ ‏ ‏بِالنِّكَاحِ الْأَوَّلِ وَلَمْ يُحْدِثْ شَيْئًا ‏","","",""],[1781,1781,"","জীবিতদের রাজত্বের সময় সবাই বলে গিয়েছিল যে একটা ছেলে আছে যার একটা ছেলে আছে । রাজার আশীর্বাদ, তাকে এটা জানতে হবে যে, দুঃখর দুঃখের সাথে তিনি তাদের সমবেদনার সাথে কোন সম্পর্ক রাখতে পারবেন না। \"অনেক ভালো বলেছেন, \"অনেক খারাপ কথা বলেছেন।\" লড়াই।","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ شُجَاعٍ ‏ ‏حَدَّثَنِي ‏ ‏خُصَيْفٌ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ طَافَ مَعَ ‏ ‏مُعَاوِيَةَ ‏ ‏بِالْبَيْتِ ‏ ‏فَجَعَلَ ‏ ‏مُعَاوِيَةُ ‏ ‏يَسْتَلِمُ ‏ ‏الْأَرْكَانَ ‏ ‏كُلَّهَا فَقَالَ لَهُ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏لِمَ تَسْتَلِمُ هَذَيْنِ الرُّكْنَيْنِ ‏ ‏وَلَمْ يَكُنْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتَلِمُهُمَا فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏لَيْسَ شَيْءٌ مِنْ ‏ ‏الْبَيْتِ ‏ ‏مَهْجُورًا فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ { ‏لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ ‏} ‏فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏صَدَقْتَ ‏","","",""],[1782,1782,"","আমরা দুজন ব্যক্তির কথা বলেছিলাম যারা ঈশ্বর সম্বন্ধে আমার সঙ্গে কথা বলে এসেছেন এবং তিনি তাঁর কাছে এসে ভুলে গেছেন । যে ব ্ যক ্ তি উপুড় হয়ে পড়ে এবং বলে , এটাই তো আল ্ লাহর কাছে সত ্ য । যে ই সেই সেই ব্যক্তি যিনি এই ব্যক্তি যিনি সেই সেই একমাত্র ব্যক্তি যিনি সেই সেই ব্যক্তি যিনি সেই ব্যক্তি ।","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ ‏ ‏حَدَّثَنِي ‏ ‏خُصَيْفٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يُجْمَعَ بَيْنَ الْعَمَّةِ وَالْخَالَةِ وَبَيْنَ الْعَمَّتَيْنِ وَالْخَالَتَيْنِ ‏","","",""],[1783,1783,"","আমরা দুটো বিষয় নিয়ে কথা বলেছিলাম যখন ঈশ্বর তাকে জিজ্ঞেস করেছিলেন । তিনি বলেন যে, তিনি হলেন সর্বোত্তম কাজ । কখনো শিক্ষা হয়নি।","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ ‏ ‏حَدَّثَنَا ‏ ‏خُصَيْفٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏إِنَّمَا ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الثَّوْبِ ‏ ‏الْمُصْمَتِ ‏ ‏مِنْ ‏ ‏قَزٍّ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَمَّا ‏ ‏السَّدَى ‏ ‏وَالْعَلَمُ ‏ ‏فَلَا نَرَى بِهِ بَأْسًا ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ يَعْنِي ابْنَ سُلَيْمَانَ الرَّقِّيَّ ‏ ‏قَالَ قَالَ ‏ ‏خُصَيْفٌ ‏ ‏حَدَّثَنِي ‏ ‏غَيْرُ وَاحِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ إِنَّمَا نَهَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمُصْمَتِ ‏ ‏مِنْهُ فَأَمَّا ‏ ‏الْعَلَمُ ‏ ‏فَلَا ‏","","",""],[1784,1784,"","তিনি বলেছিলেন, ঈশ্বর তাঁর জন্য প্রার্থনা করেছিলেন এবং তিনি রাতের বেলা আমার জন্য প্রার্থনা করবেন এবং তারপর তিনি হবেন । - বাদ দাও।","‏ ‏حَدَّثَنَا ‏ ‏عَثَّامُ بْنُ عَلِيٍّ الْعَامِرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ رَكْعَتَيْنِ ثُمَّ يَنْصَرِفُ فَيَسْتَاكُ ‏","","",""],[1785,1785,"","আমরা একটা সিংহাসনের সাথে কথা বলেছি যেটা আমি বলেছিলাম ল্যাবরিনের সাথে কথা বলেছি, একজন যাজকের ছেলে বলেছিল যে ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তার মুখে হাত দিয়েছেন। আমার বিজয়ের স্লাইডটা এক বিরাট জীবনে রয়েছে আর তুমি যা বলছিলে তার কথা শুনে আমি ও তোমার কথায় । একটা বাচ্চার মৃত্যুর জন্য, আল্লাহ তাকে প্রার্থনা করেছেন আর তাকে দোষারোপ করবেন যেন সে তার মাংসের মধ্যে ফেলে না দেয়। থ্রেড তখন আকাশের হল. তারপর রক্ত ব্যবহার করা হবে সিংহাসনের বর্বরতা. তার মুখ ঠিক আছে, কিন্তু তারা মিথ্যা বলবে আর স্পেক্টেটরটা চুরি করে ফেলবে, আমরা কথা বলেছি আমার সাথে একজন কুত্তার বাচ্চা আছে. তিনি আদেশ দিয়েছেন এবং তিনি তার প্রভুর বার্তাবাহকের সাথে বসে আছেন। সিংহাসন, আর্দ্র আকাশ বলবে যারা তৃষ্ণা নিয়ে যাবে... ...তোমার ক্ষুধার্থদের রক্ষা করবে. এমনকি সূর্য যখন চলে যাবে, তখন খবর প্রথমে তাদের পরাজিত করতে হবে, আর তারা হারিয়ে যাচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏قَالَ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏أَخْبَرَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَالِسًا فِي نَفَرٍ مِنْ أَصْحَابِهِ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَرُمِيَ بِنَجْمٍ عَظِيمٍ فَاسْتَنَارَ قَالَ ‏ ‏مَا كُنْتُمْ تَقُولُونَ إِذَا كَانَ مِثْلُ هَذَا فِي الْجَاهِلِيَّةِ قَالَ كُنَّا نَقُولُ يُولَدُ عَظِيمٌ أَوْ يَمُوتُ عَظِيمٌ ‏ ‏قُلْتُ ‏ ‏لِلزُّهْرِيِّ ‏ ‏أَكَانَ ‏ ‏يُرْمَى بِهَا فِي الْجَاهِلِيَّةِ قَالَ نَعَمْ وَلَكِنْ غُلِّظَتْ حِينَ بُعِثَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِنَّهُ لَا ‏ ‏يُرْمَى بِهَا لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ وَلَكِنَّ رَبَّنَا تَبَارَكَ اسْمُهُ إِذَا قَضَى أَمْرًا سَبَّحَ حَمَلَةُ الْعَرْشِ ثُمَّ سَبَّحَ أَهْلُ السَّمَاءِ الَّذِينَ يَلُونَهُمْ حَتَّى يَبْلُغَ التَّسْبِيحُ هَذِهِ السَّمَاءَ الدُّنْيَا ثُمَّ يَسْتَخْبِرُ أَهْلُ السَّمَاءِ الَّذِينَ يَلُونَ حَمَلَةَ الْعَرْشِ فَيَقُولُ الَّذِينَ يَلُونَ حَمَلَةَ الْعَرْشِ لِحَمَلَةِ الْعَرْشِ مَاذَا قَالَ رَبُّكُمْ فَيُخْبِرُونَهُمْ وَيُخْبِرُ أَهْلُ كُلِّ سَمَاءٍ سَمَاءً حَتَّى ‏ ‏يَنْتَهِيَ الْخَبَرُ إِلَى هَذِهِ السَّمَاءِ وَيَخْطِفُ الْجِنُّ السَّمْعَ فَيُرْمَوْنَ فَمَا جَاءُوا بِهِ عَلَى وَجْهِهِ فَهُوَ حَقٌّ وَلَكِنَّهُمْ يَقْذِفُونَ وَيَزِيدُونَ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَيَخْطِفُ الْجِنُّ وَيُرْمَوْنَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏حَدَّثَنِي ‏ ‏رِجَالٌ مِنَ الْأَنْصَارِ ‏ ‏مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُمْ كَانُوا جُلُوسًا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ إِذْ رُمِيَ بِنَجْمٍ فَذَكَرَ الْحَدِيثَ إِلَّا أَنَّهُ قَالَ إِذَا قَضَى رَبُّنَا أَمْرًا سَبَّحَهُ حَمَلَةُ الْعَرْشِ ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ الَّذِينَ يَلُونَهُمْ حَتَّى يَبْلُغَ التَّسْبِيحُ السَّمَاءَ الدُّنْيَا فَيَقُولُونَ الَّذِينَ يَلُونَ حَمَلَةَ الْعَرْشِ لِحَمَلَةِ الْعَرْشِ مَاذَا قَالَ رَبُّكُمْ فَيَقُولُونَ الْحَقَّ وَهُوَ الْعَلِيُّ الْكَبِيرُ فَيَقُولُونَ كَذَا وَكَذَا فَيُخْبِرُ أَهْلُ السَّمَاوَاتِ بَعْضُهُمْ بَعْضًا حَتَّى يَبْلُغَ الْخَبَرُ السَّمَاءَ الدُّنْيَا قَالَ وَيَأْتِي الشَّيَاطِينُ فَيَسْتَمِعُونَ الْخَبَرَ فَيَقْذِفُونَ بِهِ إِلَى أَوْلِيَائِهِمْ وَيَرْمُونَ بِهِ إِلَيْهِمْ فَمَا جَاءُوا بِهِ عَلَى وَجْهِهِ فَهُوَ حَقٌّ وَلَكِنَّهُمْ يَزِيدُونَ فِيهِ وَيَقْرِفُونَ وَيَنْقُصُونَ ‏","","",""],[1786,1786,"","আমরা ইশ্বরের চেয়ে মহান ঈশ্বর হওয়ার কথা বলেছিলাম। তারা বলল, কেন আমরা প্রভুর অনুগ্রহে ওকে এটা শেখানো শুরু করলাম? সে বলছে, সে হচ্ছে ঈশ্বরের অনুগ্রহ থেকে ভালো। প্রভু, প্রভু, প্রভু তার সম্পূর্ণ কথার কবর দিয়েছেন.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏وَعَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهُمَا قَالَا ‏ ‏لَمَّا نُزِلَ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَفِقَ ‏ ‏يُلْقِي ‏ ‏خَمِيصَةً ‏ ‏عَلَى وَجْهِهِ فَلَمَّا ‏ ‏اغْتَمَّ ‏ ‏رَفَعْنَاهَا عَنْهُ وَهُوَ يَقُولُ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏وَالنَّصَارَى ‏ ‏اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ ‏ ‏تَقُولُ ‏ ‏عَائِشَةُ ‏ ‏يُحَذِّرُهُمْ مِثْلَ الَّذِي صَنَعُوا ‏","","",""],[1787,1787,"","তার কাছে যে সালম প্রার্থনা করেছিলেন সেই সালা তার কাছে আছে আর তাকে এই বলে যে, মাস মাস প্রসারিত হয়েছে ও তা পূর্ণ হয়েছে । বেঁচে আছি।","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْهَيْثَمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي الْحَكَمِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏تَمَّ الشَّهْرُ تِسْعًا وَعِشْرِينَ ‏","","",""],[1788,1788,"","আমরা আমার বাবার ছেলেকে বলেছিলাম কিভাবে সে একটা বোকা ছেলের সাথে কথা বলেছে। ডিপার্টমেন্টের প্রার্থনা আর সালাদ আছে.","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏صَلَّيْتُ الظُّهْرَ ‏ ‏بِالْبَطْحَاءِ ‏ ‏خَلْفَ شَيْخٍ أَحْمَقَ ‏ ‏فَكَبَّرَ ثِنْتَيْنِ وَعِشْرِينَ تَكْبِيرَةً يُكَبِّرُ إِذَا سَجَدَ وَإِذَا رَفَعَ رَأْسَهُ قَالَ فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏تِلْكَ صَلَاةُ ‏ ‏أَبِي الْقَاسِمِ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏","","",""],[1789,1789,"","বাবার ছেলের সাথে আমার বাবার এক ছেলের কথা বলেছি, আমি বাবার ছেলের কথা শুনে খুশি হব। আমার বাবা একটা ছেলের কথা উল্লেখ করার চেয়ে বেশি কিছু। তার গৌরবে ঈশ্বর ভুলে গেছেন, তার কথা তিনি ভুলে গেছেন। শান্তি তার ছেলে এবং তিনি প্রভুর আদেশের প্রতি অভিযুক্তের সবচেয়ে সেরাটা করেছেন। আমাকে বলা হয়েছে এটা করতে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏الْمَعْنَى ‏ ‏وَقَالَ ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي يَزِيدَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَرَأَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي صَلَوَاتٍ وَسَكَتَ فَنَقْرَأُ فِيمَا قَرَأَ فِيهِنَّ نَبِيُّ اللَّهِ وَنَسْكُتُ فِيمَا سَكَتَ فَقِيلَ لَهُ فَلَعَلَّهُ كَانَ يَقْرَأُ فِي نَفْسِهِ فَغَضِبَ مِنْهَا وَقَالَ أَيُتَّهَمُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏أَتَتَّهِمُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1790,1790,"","আমরা তোমার জন্য আমার উপহারের কথা বলেছি... ...ঈশ্বরের কাছে ভালো ছেলের জন্য, সে এটা চায়, আর সে এটা আমাকে দিয়ে দেবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْفَضْلِ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْأَيِّمُ ‏ ‏أَحَقُّ بِنَفْسِهَا مِنْ وَلِيِّهَا ‏ ‏وَالْبِكْرُ ‏ ‏تُسْتَأْمَرُ ‏ ‏فِي نَفْسِهَا وَإِذْنُهَا صُمَاتُهَا ‏","","",""],[1791,1791,"","আমরা প্রভুর সাথে শান্তিতে কথা বলেছি, আমার ছেলের লজ্জাটা তিনি একবারও ভুলবেন না আর ঈশ্বরের কাছে প্রার্থনা করবেন না।","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏الْمُطَّلِبُ بْنُ عَبْدِ اللَّهِ بْنِ حَنْطَبٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏كَانَ ‏ ‏يَتَوَضَّأُ مَرَّةً مَرَّةً وَيُسْنِدُ ذَاكَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1792,1792,"","আমরা দুই মাস ধরে মরুভূমি সম্পর্কে কথা বলেছি... ...যে কিনা একজন মহিলাকে অনুসন্ধান থেকে খুঁজে পেতে পারবে, ঈশ্বর তাকে ঘুরে ঘুরে ঘুরে ঘুরে যেতে এবং তার সেরা বিচার বিভাগ থেকে ভাল খেলতে শিখিয়েছেন। বাবা বড় ভাই, আমি তোমাকে ধরতে পারবো না।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏سَمِعَ ‏ ‏سُلَيْمَانَ بْنَ يَسَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ امْرَأَةً مِنْ ‏ ‏خَثْعَمَ ‏ ‏سَأَلَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَدَاةَ ‏ ‏جَمْعٍ ‏ ‏وَالْفَضْلُ بْنُ عَبَّاسٍ ‏ ‏رِدْفُهُ ‏ ‏فَقَالَتْ ‏ ‏إِنَّ فَرِيضَةَ اللَّهِ فِي الْحَجِّ عَلَى عِبَادِهِ أَدْرَكَتْ أَبِي شَيْخًا كَبِيرًا لَا يَسْتَطِيعُ أَنْ يَسْتَمْسِكَ عَلَى الرَّحْلِ فَهَلْ ‏ ‏تَرَى أَنْ أَحُجَّ عَنْهُ قَالَ نَعَمْ ‏","","",""],[1793,1793,"","আমরা দুই মাস ধরে ঈশ্বরের সন্তানের মরুভূমি সম্পর্কে কথা বলেছি... ...আমি একজন যাজকের ছেলে আর কুমারীর জন্য ভাল কিছু করতে এসেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর আমাদের কিছু লোক বলবেন যারা আমাদের লক্ষ করে আমি জিততে পারব না। মাঝে মাঝে সে আমাকে বলেনি যে ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তিনি কিছু একটা দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏جِئْتُ أَنَا ‏ ‏وَالْفَضْلُ ‏ ‏وَنَحْنُ عَلَى ‏ ‏أَتَانٍ ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بِالنَّاسِ ‏ ‏بِعَرَفَةَ ‏ ‏فَمَرَرْنَا عَلَى بَعْضِ الصَّفِّ فَنَزَلْنَا عَنْهَا وَتَرَكْنَاهَا ‏ ‏تَرْتَعُ ‏ ‏وَدَخَلْنَا فِي الصَّفِّ فَلَمْ يَقُلْ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَيْئًا ‏","","",""],[1794,1794,"","আমরা ২ মাস কথা বলেছি ঈশ্বরের পুত্র হতে পারে ফুলিং এর উপর ভিত্তি করে। সে বের হয়ে আসবে, এমনকি যদি সে হারিয়ে যায়ও। সে দু'জন ছেলেকে কিছু কথা বলে। আমি জানি, আমি কি এই ফুলটা পেয়েছি? সে আরেকজনকে নিয়ে যাচ্ছিল, যে বলেছিল সে একটা কুত্তার বাচ্চা।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ يَوْمَ الْفَتْحِ فَصَامَ حَتَّى إِذَا كَانَ ‏ ‏بِالْكَدِيدِ ‏ ‏أَفْطَرَ ‏ ‏وَإِنَّمَا يُؤْخَذُ بِالْآخِرِ مِنْ فِعْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قِيلَ ‏ ‏لِسُفْيَانَ ‏ ‏قَوْلُهُ إِنَّمَا يُؤْخَذُ بِالْآخِرِ مِنْ قَوْلِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَوْ قَوْلِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ كَذَا فِي الْحَدِيثِ ‏","","",""],[1795,1795,"","আমরা দুই গ্রীষ্মের কথা বলেছি আমরা ঈশ্বরের ছেলের কথা বলেছি একটি ছেলে নিয়ে ওঠার চেষ্টা করার জন্য। ঈশ্বর তার মায়ের কাছে শপথ নিতে হয়েছে যে তাকে হত্যা করার আগে মারা যেতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏سَعْدَ بْنَ عُبَادَةَ ‏ ‏سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ نَذْرٍ كَانَ عَلَى ‏ ‏أُمِّهِ ‏ ‏تُوُفِّيَتْ قَبْلَ أَنْ تَقْضِيَهُ فَقَالَ اقْضِهِ عَنْهَا ‏","","",""],[1796,1796,"","আমরা ঈশ্বরের পুত্রের মরুভূমি সম্পর্কে কথা বলেছি যিনি প্রভুর সাথে ভাগ হয়ে গেছেন। তিনি শান্তি এবং তার প্রভুর কাছে প্রার্থনা করেছেন, তার মনে হয় তার কাছে আত্মসমর্পণ করা উচিত না। বিভক্ত।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏أَقْسَمَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُقْسِمْ ‏","","",""],[1797,1797,"","আমরা দুজন ছেলের কথা বলেছি যে আমাকে বলতে শুনেছি খোদা এসেছে, সে বলবে যাই হোক না কেন, সে হয়ত চলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنِ ‏ ‏ابْنِ وَعْلَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَيُّمَا ‏ ‏إِهَابٍ ‏ ‏دُبِغَ ‏ ‏فَقَدْ طَهُرَ ‏","","",""],[1798,1798,"","আমরা দুই বছর ধরে কথা বলেছি একজন শিকারী যার মানে আমার শ্বশুর আব্বা ও শ্বশুর আব্বাকে নিয়ে খুশি। আল্লাহ আছে এবং তিনি বলবেন, \"এক উন্নত সুরের জন্য থাকুন এবং আপনার মত কাজ করুন।\" পাপ","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زِيَادٍ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِي مَعْبَدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ارْفَعُوا عَنْ ‏ ‏بَطْنِ مُحَسِّرٍ ‏ ‏وَعَلَيْكُمْ بِمِثْلِ حَصَى ‏ ‏الْخَذْفِ ‏","","",""],[1799,1799,"","আমরা দুই বছর ধরে একটি ছেলেকে দেখতে এসেছি যে তার ছেলের জন্য ঈশ্বরের প্রেমে ফিরে আসবে। ঈশ্বর তার জন্য প্রার্থনা করবেন এবং তার ছেলের আত্মা থেকে যে খুশি তা উদ্ধার করা হবে। বড় হয়ে, তার আঙ্গুলের ছাপ।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْفَضْلِ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏يَبْلُغُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الثَّيِّبُ ‏ ‏أَحَقُّ بِنَفْسِهَا مِنْ وَلِيِّهَا ‏ ‏وَالْبِكْرُ ‏ ‏يَسْتَأْمِرُهَا ‏ ‏أَبُوهَا فِي نَفْسِهَا وَإِذْنُهَا ‏ ‏صُمَاتُهَا ‏","","",""],[1800,1800,"","আমরা দুই বছর ধরে একটি বাবা-মা'র শাস্তির ভয়ে তাদের গর্বে আছি, যে ঈশ্বর আদেশ দিয়েছেন লর্ডের পালনকর ্ তাকে জয় করেছেন, সে একটা আঘাত করবে। আমরা আমাদের সবচেয়ে ভাল একজন দেবীর ছেলেকে খুঁজতে শুরু করেছি.","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالرَّوْحَاءِ ‏ ‏فَلَقِيَ ‏ ‏رَكْبًا ‏ ‏فَسَلَّمَ عَلَيْهِمْ فَقَالَ مَنْ الْقَوْمُ قَالُوا الْمُسْلِمُونَ قَالَ فَمَنْ أَنْتُمْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَفَزِعَتْ امْرَأَةٌ ‏ ‏فَأَخَذَتْ بِعَضُدِ صَبِيٍّ فَأَخْرَجَتْهُ مِنْ ‏ ‏مِحَفَّتِهَا ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ هَلْ لِهَذَا حَجٌّ قَالَ نَعَمْ وَلَكِ أَجْرٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏مَعْنَاهُ ‏","","",""]];
